window.MIT_COURSE_PARTS=window.MIT_COURSE_PARTS||[];window.MIT_COURSE_PARTS.push([{"code":"21W.226","title":"Advanced Workshop in Writing for Science and Engineering (ELS)","level":"U","description":"For advanced bilingual students who wish to build confidence and skills in writing in various contexts of academic and professional life. Short assignments include writing for a general audience, proposals, data commentaries, cover letters, and personal statements, leading to a written term project such as part of a thesis or journal article. Students encouraged to use their research as material for written assignments. Discusses the use of generative AI in writing and learning. Students taking graduate version complete additional assignments. May be repeated for credit with permission of instructor. Limited to 15 per section. Listeners not permitted.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:00","end":"13:30","room":"1-375"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.226","terms":["fall","spring"],"rating":6.63,"hours":8.52,"inClassHours":3.01,"outOfClassHours":5.51,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"21W.232","title":"Advanced Speaking and Critical Listening Skills (ELS)","level":"G","description":"For advanced bilingual students who wish to build confidence and skills in presenting and understanding material in a variety of academic and professional contexts: group discussions, classroom teaching and interactions, theses/research proposals, and conference talks. Includes frequent video and audio recording for analysis and feedback. Develops effective speaking and listening skills for academic and professional contexts. Students are encouraged to use their research as material for written assignments. Discusses the use of generative AI in writing and learning. May be repeated for credit with permission of instructor. Limited to 15 per section.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"1-135"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.232","terms":["fall","spring"],"rating":6.29,"hours":7.46,"inClassHours":2.93,"outOfClassHours":4.53,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"21W.233","title":"Advanced Speaking and Critical Listening Skills (ELS)","level":"U","description":"For advanced bilingual students who wish to build confidence and skills in presenting and understanding material in a variety of academic and professional contexts: group discussions, classroom teaching and interactions, theses/research proposals, and conference talks. Includes frequent video and audio recording for analysis and feedback. Develops effective speaking and listening skills for academic and professional contexts. Students are encouraged to use their research as material for written assignments. Discusses the use of generative AI in writing and learning. May be repeated for credit with permission of instructor. Limited to 15 per section.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"1-135"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.233","terms":["fall","spring"],"rating":7.0,"hours":8.33,"inClassHours":3.38,"outOfClassHours":4.95,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"21W.725","title":"Gender, Myth, and Magic","level":"U","description":"Explores ways contemporary writers re-imagine myth and fairy tales through lens of gender and sexuality. Examines how old stories can be retold to resonate with issues of power, violence, courage, resistance, identity, community, silence, and voice. Students complete writing project where they re-imagine a myth or fairy tale.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:30","room":"4-253"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.725","terms":["fall"],"rating":6.8,"hours":6.93,"inClassHours":3.0,"outOfClassHours":3.93,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"21W.735","title":"Writing and Reading the Essay","level":"U","description":"Exploration of formal and informal modes of writing nonfiction prose. Extensive practice in composition, revision, and editing. Reading in the literature of the essay from the Renaissance to the present, with an emphasis on modern writers. Classes alternate between discussion of published readings and workshops on student work. Individual conferences. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"4-159"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.735","terms":["fall","spring"],"rating":6.41,"hours":8.32,"inClassHours":3.11,"outOfClassHours":5.21,"prerequisites":"''Writing sample'', ''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"21W.738","title":"Intersectional Feminist Memoir","level":"U","description":"Explores the memoir genre through a feminist intersectional lens, looking at the ways in which feminist writers ground personal experience within a complex understanding of race, gender, sexuality, class, ethnicity, immigration status/nationality, and dis/ablity. Gives particular attention to the relationships between the personal and the political; form and content; fact, truth, and imagination; self and community; trauma and healing; coming to voice and breaking silence. Readings include books by Audre Lorde, Janet Mock, Daisy Hernandez, Jessica Valenti, and Ariel Gore, and shorter pieces by Meena Alexander and Leah Lakshmi Piepzna-Samarasinha. Drawing on lessons taken from these works, students write a short memoir of their own.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"2-103"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.738","terms":["fall","spring"],"rating":6.9,"hours":8.86,"inClassHours":2.98,"outOfClassHours":5.88,"prerequisites":"","corequisites":"","recommendedPreparation":"Explores the memoir genre through a feminist intersectional lens, looking at the ways in which feminist writers ground personal experience within a complex understanding of race, gender, sexuality, class, ethnicity, immigration status/nationality, and dis/ablity."},{"code":"21W.740","title":"Writing Autobiography and Biography","level":"U","description":"Writing an autobiography is a vehicle for improving one's style while studying the nuances of the language. Literary works are read with an emphasis on different forms of autobiography. Students examine various stages of life, significant transitions, personal struggles, and memories translated into narrative prose, and discuss: what it means for autobiographer and biographer to develop a personal voice; and the problems of reality and fiction in autobiography and biography.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"16-220"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.740","terms":["fall"],"rating":5.69,"hours":6.77,"inClassHours":2.57,"outOfClassHours":4.2,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"21W.742","title":"Writing about Race","level":"U","description":"The issue of race and racial identity have preoccupied many writers throughout the history of the US. Students read Jessica Abel, Diana Abu-Jaber, Lynda Barry, Felicia Luna Lemus, James McBride, Sigrid Nunez, Ruth Ozeki, Danzy Senna, Gloria Anzaldua, Judith Ortiz Cofer, Carmit Delman, Stefanie Dunning, Cherrie Moraga, Hiram Perez and others, and consider the story of race in its peculiarly American dimensions. The reading, along with the writing of members of the class, is the focus of class discussions. Oral presentations on subjects of individual interest are also part of the class activities. Students explore race and ethnicity in personal essays, pieces of cultural criticism or analysis, or (with permission of instructor) fiction. All written work is read and responded to in class workshops and subsequently revised. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:30","end":"13:00","room":"4-253"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.742","terms":["fall","spring"],"rating":6.7,"hours":6.8,"inClassHours":3.02,"outOfClassHours":3.78,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"21W.744","title":"The Art of Comic Book Writing","level":"U","description":"Students create short scripts and full-length comic book narratives across a variety of genres, while analyzing a wide range of comics (corporate and independent, print and web). Focuses on scripts; drawing skills not required, but illustrations or storyboards are welcome. Special attention to questions of gender, race, ethnicity, and sexuality in both critical and creative work. Limited to 13.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"16:00","room":"1-132"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.744","terms":["fall"],"rating":6.55,"hours":7.94,"inClassHours":2.88,"outOfClassHours":5.06,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"21W.745","title":"Advanced Essay Workshop","level":"U","description":"For students with experience in writing essays and nonfiction prose. Focuses on negotiating and representing identities grounded in gender, race, class, nationality, and sexuality in prose that is expository, exploratory, investigative, persuasive, lyrical, or incantatory. Authors include James Baldwin, Minnie Bruce Pratt, Audre Lorde, Richard Rodriguez, Alice Walker, John Edgar Wideman, Diana Hume George, bell hooks, Margaret Atwood, Patricia J. Williams, and others. Designed to help students build upon their strengths as writers and to expand their repertoire of styles and approaches in essay writing. Approved for credit in Women's and Gender Studies when content meets the requirements for subjects in that program. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"56-169"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.745","terms":["fall","spring"],"rating":5.0,"hours":6.8,"inClassHours":3.0,"outOfClassHours":3.8,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"21W.747","title":"Rhetoric","level":"U","description":"For students with a special interest in learning how to make forceful arguments in oral and written form. Studies the forms and structures of argumentation, including organization of ideas, awareness of audience, methods of persuasion, evidence, factual vs. emotional argument, figures of speech, and historical forms and uses of arguments. Limited to 18 per section.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"E17-136"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.747","terms":["fall","spring"],"rating":6.34,"hours":6.56,"inClassHours":3.02,"outOfClassHours":3.54,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"21W.748","title":"Apocalyptic Storytelling","level":"U","description":"Focuses on the critical making of apocalyptic, post-apocalyptic and dystopian stories across various narrative media.  Considers the long history of Western apocalypticism as well as the uses and abuses of apocalypticism across time.  Examines a wide variety of influential texts in order to enhance students' creative and theoretical repertoires.  Students create their own apocalyptic stories and present on selected texts.  Investigates conventions such as plague, zombies, nuclear destruction, robot uprising, alien invasion, environmental collapse, and supernatural calamities. Considers questions of race, gender, sexuality, colonialism, trauma, memory, witness, and genocide. Intended for students with prior creative writing experience. Students taking graduate version complete additional assignments. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"16:00","room":"5-233"}]}],"url":"http://student.mit.edu/catalog/m21Wa.html#21W.748","terms":["fall"],"rating":6.57,"hours":9.28,"inClassHours":3.0,"outOfClassHours":6.28,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"21W.754","title":"Playwriting Fundamentals","level":"U","description":"Introduces the craft of writing for the theater, with special attention to the basics of dramatic structure. Through weekly assignments and in-class exercises, students explore character, conflict, language and plasticity in scenes and short plays. In workshop format, students present individual work for feedback and heavily revise their work based on that response. Readings include a variety of plays.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"4-253"}]}],"url":"http://student.mit.edu/catalog/m21Wb.html#21W.754","terms":["fall","spring"],"rating":6.81,"hours":8.11,"inClassHours":3.0,"outOfClassHours":5.11,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"21W.755","title":"Writing and Reading Short Stories","level":"U","description":"An introduction to writing fiction. Students write their own stories and study essays and short stories by contemporary authors from around the world. Discussion focuses on students' writing and on assigned works in their historical and social contexts. Limited to 15 per section.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"5-231"},{"days":["T","R"],"start":"15:00","end":"16:30","room":"5-231"},{"days":["T","R"],"start":"13:30","end":"15:00","room":"4-146"}]}],"url":"http://student.mit.edu/catalog/m21Wb.html#21W.755","terms":["fall","spring"],"rating":6.69,"hours":6.68,"inClassHours":2.87,"outOfClassHours":3.81,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"21W.757","title":"Fiction Workshop","level":"U","description":"Intermediate class for students with some experience in writing fiction. Students write short stories and complete other writing exercises. Readings include short story collections by contemporary writers such as Sandra Cisneros, Benjamin Percy, Leila Lalami, Laura Pritchett, Bret Anthony Johnston, and Edward P. Jones. Discussions focus on sources of story material, characterization, setting, architecture, point of view, narrative voice, and concrete detail.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"19:00","end":"22:00","room":"56-191"}]}],"url":"http://student.mit.edu/catalog/m21Wb.html#21W.757","terms":["fall","spring"],"rating":6.63,"hours":7.84,"inClassHours":2.7,"outOfClassHours":5.14,"prerequisites":"21W.755","corequisites":"","recommendedPreparation":""},{"code":"21W.762","title":"Poetry Workshop","level":"U","description":"For students with some previous experience in poetry writing. Frequent assignments stress use of language, diction, word choice, line breaks, imagery, mood, and tone. Considers the functions of memory, imagination, dreams, poetic impulses. Throughout the term, students examine the work of published poets. Revision stressed.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"66-148"},{"days":["T"],"start":"19:00","end":"22:00","room":"66-148"}]}],"url":"http://student.mit.edu/catalog/m21Wb.html#21W.762","terms":["fall","spring"],"rating":6.97,"hours":4.82,"inClassHours":2.46,"outOfClassHours":2.36,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"21W.770","title":"Advanced Fiction Workshop","level":"U","description":"For students with some experience in writing fiction. Write longer works of fiction and short stories which are related or interconnected. Read short story collections by individual writers, such as Sandra Cisneros, Raymond Carver, Edward P. Jones, and Tillie Olsen, and discuss them critically and analytically, with attention to the ways in which the writers' choices about component parts contribute to meaning. In-class exercises and weekly workshops of student work focus on sources of story material, characterization, structure, narrative voice, point of view and concrete detail. Concentration on revision. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"13:00","end":"16:00","room":"4-253"}]}],"url":"http://student.mit.edu/catalog/m21Wb.html#21W.770","terms":["fall","spring"],"rating":7.0,"hours":9.83,"inClassHours":3.0,"outOfClassHours":6.83,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"21W.771","title":"Advanced Poetry Workshop","level":"U","description":"For students experienced in writing poems. Regular reading of published contemporary poets and weekly submission of manuscripts for class review and criticism. Students expected to do a substantial amount of rewriting and revision. Classwork supplemented with individual conferences.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"17:00","room":"4-253"}]}],"url":"http://student.mit.edu/catalog/m21Wb.html#21W.771","terms":["fall","spring"],"rating":6.53,"hours":6.08,"inClassHours":2.85,"outOfClassHours":3.23,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"21W.773","title":"Writing Longer Fiction","level":"U","description":"Designed for students who have some experience in writing fiction and want to try longer forms like the novella and novel. Students interested in writing a novel are expected to produce at least two chapters and an outline of the complete work. Readings include several novels from Fitzgerald to the present, and novellas from Gogol's The Overcoat to current examples. Students discuss one another's writing in a roundtable workshop, with a strong emphasis on revision. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"14N-112"}]}],"url":"http://student.mit.edu/catalog/m21Wb.html#21W.773","terms":["fall","spring"],"rating":5.81,"hours":10.15,"inClassHours":3.0,"outOfClassHours":7.15,"prerequisites":"''A fiction workshop''/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"21W.775","title":"Writing about Nature and Environmental Issues","level":"U","description":"Focuses on traditional nature writing and the environmentalist essay. Students keep a web log as a journal. Writings are drawn from the tradition of nature writing and from contemporary forms of the environmentalist essay. Authors include Henry Thoreau, Loren Eiseley, Annie Dillard, Chet Raymo, Sue Hubbel, Rachel Carson, Bill McKibben, and Terry Tempest Williams. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"66-148"}]}],"url":"http://student.mit.edu/catalog/m21Wb.html#21W.775","terms":["fall","spring"],"rating":6.65,"hours":7.42,"inClassHours":3.07,"outOfClassHours":4.35,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"21W.776","title":"Screenwriting","level":"U","description":"Explores the fundamentals of screenplay writing.  Presents skills to create compelling characters and stories in different dramatic genres (comedy, drama). In addition to their own writing, students read a selection of screenplays and watch short films that form the basis of class discussion early in the term.  Class is modeled on a professional development workshop in which participants, over the course of the term, write a short screenplay, including a final draft.  Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"16:00","room":"4-253"}]}],"url":"http://student.mit.edu/catalog/m21Wb.html#21W.776","terms":["fall"],"rating":6.2,"hours":7.11,"inClassHours":3.02,"outOfClassHours":4.09,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"21W.778","title":"Science Journalism","level":"U","description":"An introduction to print daily journalism and news writing, focusing on science news writing in general, and medical writing in particular. Emphasis is on writing clearly and accurately under deadline pressure. Class discussions involve the realities of modern journalism, how newsrooms function, and the science news coverage in daily publications. Discussions of, and practice in, interviewing and various modes of reporting. In class, students write numerous science news stories on deadline. There are additional longer writing assignments outside of class. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"14N-112"}]}],"url":"http://student.mit.edu/catalog/m21Wb.html#21W.778","terms":["fall","spring"],"rating":5.58,"hours":8.34,"inClassHours":3.04,"outOfClassHours":5.3,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"21W.779","title":"The Modern Newsroom: Principles and Practices","level":"U","description":"Offers an introduction to news writing and production. Presents the basics of journalism, including its core ethical tenets, news writing and reporting techniques, media literacy, deadline-driven production processes, and newsroom standards. Students complete a broad range of journalistic pieces, including assignments on news and scientific reporting, local and field reporting, opinion writing, editing, and fact-checking, some of which may be published in The Tech. Students are expected to come to class prepared to discuss major news events as well as weekly readings from major journalism outlets. Learning objectives are to gain a clear idea of what makes a strong news story successful, hone reporting and analytic skills, create a portfolio of journalistic work, and exercise a strong grasp of ethical practices and procedures that guide newsrooms across the world.  Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"14N-112"}]}],"url":"http://student.mit.edu/catalog/m21Wb.html#21W.779","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"21W.786","title":"Social Justice and The Documentary Film","level":"U","description":"Explores the history and current state of social-issue documentary. Examines how cultural and political upheaval and technological change have converged at different moments to bring about new waves of activist documentary film production. Particular focus on films and other non-fiction media of the present and recent past. Students screen and analyze a series of key films and work in groups to produce their own short documentary using digital video and computer-based editing. Students taking graduate version complete additional assignments. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"19:00","end":"22:00","room":"14N-112"}]}],"url":"http://student.mit.edu/catalog/m21Wb.html#21W.786","terms":["fall"],"rating":6.76,"hours":9.87,"inClassHours":3.0,"outOfClassHours":6.87,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"21W.791","title":"Critical Internet Studies","level":"U","description":"Focuses on the power dynamics in internet-related technologies (including social networking platforms, surveillance technology, entertainment technologies, and emerging media forms). Theories and readings focus on the cultural, social, economic, and political aspects of internet use and design, with a special attention to gender and race. Topics include: online communication and communities, algorithms and search engines, activism and online resistance, surveillance and privacy, content moderation and platform governance, and the spread of dis- and misinformation. Instruction and practice in written and oral communication provided. Students taking the graduate version complete additional readings and assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:30","room":"66-154"}]}],"url":"http://student.mit.edu/catalog/m21Wb.html#21W.791","terms":["fall","spring"],"rating":6.65,"hours":9.39,"inClassHours":3.14,"outOfClassHours":6.25,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"21W.822","title":"Science Writing Thesis Development and Workshop","level":"G","description":"Develops abilities to produce long-form pieces of science-based journalism, with a focus on constructing multiple narratives, source building and interview techniques, rewriting and working with editors. Students also hone their ability to shape their classmates' work.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"17:00","end":"19:30","room":"14N-112"}]}],"url":"http://student.mit.edu/catalog/m21Wb.html#21W.822","terms":["fall"],"rating":5.61,"hours":11.24,"inClassHours":2.97,"outOfClassHours":8.27,"prerequisites":"","corequisites":"21W.THG","recommendedPreparation":""},{"code":"21W.825","title":"Advanced Science Writing Seminar I","level":"G","description":"First term of year-long graduate sequence in science writing offers students intensive workshops and critiques of their own writing, and that of published books, articles, and essays; discussions of ethical and professional issues; study of science and scientists in historical and social context; analysis of recent events in science and technology. Emphasis throughout on developing skills and habits of mind that enable the science writer to tackle scientifically formidable material and write about it for ordinary readers. Topics include the tools of research, conceived in its broadest sense- including interviewing, websites, archives, scientific journal articles; science journalism, including culture of the newsroom and magazine-style journalism; science essays. Considerable attention to science writing's audiences, markets, and publics and the special requirements of each.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"12:00","room":"14N-112"}]}],"url":"http://student.mit.edu/catalog/m21Wb.html#21W.825","terms":["fall"],"rating":5.65,"hours":18.72,"inClassHours":5.77,"outOfClassHours":12.95,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"21W.THG","title":"Graduate Thesis","level":"G","description":"Research and writing of thesis in consultation with faculty, including individual meetings and group seminars, undertaken over the course of one year.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"17:00","end":"19:30","room":"14N-112"}]}],"url":"http://student.mit.edu/catalog/m21Wb.html#21W.THG","terms":["fall","spring"],"rating":5.7,"hours":12.12,"inClassHours":2.96,"outOfClassHours":9.16,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"22.002","title":"Introduction to Undergraduate Research II","level":"U","description":"Instruction in formal communications for undergraduate research, particularly preparing journal manuscripts. Students practice self-reflection and motivation skills to enable independent research. Provides foundation to build and maintain professional networks. Current participation in a UROP within the Nuclear Science and Engineering Department or Plasma Science and Fusion Center with one term of prior experience is strongly recommended. Limit to 25. Preference to students accepted into the FUSars program, followed by students UROPing on any nuclear-related project.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"16:00","end":"17:00","room":"10-063"},{"days":["W"],"start":"16:00","end":"17:00","room":"10-063"}]}],"url":"http://student.mit.edu/catalog/m22a.html#22.002","terms":["fall"],"rating":5.8,"hours":4.7,"inClassHours":1.0,"outOfClassHours":3.7,"prerequisites":"22.001","corequisites":"","recommendedPreparation":"Current participation in a UROP within the Nuclear Science and Engineering Department or Plasma Science and Fusion Center with one term of prior experience is strongly recommended."},{"code":"22.003","title":"NEET Seminar: Renewable Energy Machines","level":"U","description":"Seminar for students enrolled in the Renewable Energy Machines NEET thread. Focuses on topics around renewable energy via guest lectures and research discussions.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"19:00","end":"20:00","room":"3-001"}]}],"url":"http://student.mit.edu/catalog/m22a.html#22.003","terms":["fall","spring"],"rating":6.07,"hours":1.48,"inClassHours":1.0,"outOfClassHours":0.48,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"22.01","title":"Introduction to Nuclear Engineering and Ionizing Radiation","level":"U","description":"Provides an introduction to fundamental concepts in nuclear science and its engineering applications. Describes basic nuclear structure, radioactivity, nuclear reactions, and kinematics. Covers the interaction of ionizing radiation with matter, emphasizing radiation detection, shielding, and radiation effects on human health and materials. Presents energy systems based on fission and fusion nuclear reactions, as well as industrial and medical applications of nuclear science.","groups":[{"type":"Lab","options":[{"days":["F"],"start":"15:00","end":"16:00","room":"24-121"}]},{"type":"Recitation","options":[{"days":["M","W","F"],"start":"14:00","end":"15:00","room":"24-121"}]}],"url":"http://student.mit.edu/catalog/m22a.html#22.01","terms":["fall"],"rating":5.61,"hours":10.7,"inClassHours":3.94,"outOfClassHours":6.76,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"22.014","title":"Ethics for Engineers","level":"U","description":"Explores how to be an ethical engineer. Students examine engineering case studies along with foundational ethical readings, and investigate which ethical approaches are best and how to apply them as engineers. Topics include justice, rights, cost-benefit analysis, safety, bias, genetic engineering, climate change, and the promise and peril of AI. Discussion-based. All sections cover the same core ethical frameworks, but some sections have a particular focus for engineering case studies, such as Computer Science or Bioengineering. Students are eligible to take any section of the course, regardless of their registered course number. The subject is taught in separate sections. For 20.005, students additionally undertake an ethical-technical analysis of a BE-related topic of their choosing.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["T"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["W"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["W"],"start":"19:00","end":"21:00","room":"66-148"}]}],"url":"http://student.mit.edu/catalog/m22a.html#22.014","terms":["fall","spring"],"rating":6.42,"hours":5.15,"inClassHours":2.04,"outOfClassHours":3.11,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"22.03","title":"Introduction to Design Thinking and Rapid Prototyping","level":"U","description":"Focuses on design thinking, an iterative process that uses divergent and convergent thinking to approach design problems and prototype and test solutions. Includes experiences in creativity, problem scoping, and rapid prototyping skills. Skills are built over the course of the semester through design exercises and projects. Enrollment limited; preference to Course 22 & Course 3 majors and minors, and NEET students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:00","end":"17:00","room":"N52-342B"}]},{"type":"Lab","options":[{"days":["W"],"start":"15:00","end":"17:00","room":"N52-342B"}]}],"url":"http://student.mit.edu/catalog/m22a.html#22.03","terms":["fall"],"rating":6.64,"hours":7.06,"inClassHours":4.29,"outOfClassHours":2.77,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"22.033","title":"Nuclear Systems Design Project","level":"U","description":"Group design project involving integration of nuclear physics, particle transport, control, heat transfer, safety, instrumentation, materials, environmental impact, and economic optimization. Provides opportunity to synthesize knowledge acquired in nuclear and non-nuclear subjects and apply this knowledge to practical problems of current interest in nuclear applications design. Past projects have included using a fusion reactor for transmutation of nuclear waste, design and implementation of an experiment to predict and measure pebble flow in a pebble bed reactor, and development of a mission plan for a manned Mars mission including the conceptual design of a nuclear powered space propulsion system and power plant for the Mars surface, a lunar/Martian nuclear power station and the use of nuclear plants to extract oil from tar sands. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"24-112"}]}],"url":"http://student.mit.edu/catalog/m22a.html#22.033","terms":["fall"],"rating":5.55,"hours":12.6,"inClassHours":2.79,"outOfClassHours":9.81,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"22.039","title":"Integration of Reactor Design, Operations, and Safety","level":"U","description":"Covers the integration of reactor physics and engineering sciences into nuclear power plant design, focusing on designs projected to be used in the first half of this century. Topics include materials issues in plant design and operations, aspects of thermal design, fuel depletion and fission-product poisoning, and temperature effects on reactivity. Addresses safety considerations in regulations and operations, such as the evolution of the regulatory process, the concept of defense in depth, general design criteria, accident analysis, probabilistic risk assessment, and risk-informed regulations.  Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"24-115"}]}],"url":"http://student.mit.edu/catalog/m22a.html#22.039","terms":["fall"],"rating":6.23,"hours":10.22,"inClassHours":3.02,"outOfClassHours":7.2,"prerequisites":"22.05, 22.06","corequisites":"","recommendedPreparation":""},{"code":"22.05","title":"Neutron Physics and Radiation Transport","level":"U","description":"Introduces fundamental properties of the neutron. Covers reactions induced by neutrons, nuclear fission, slowing down of neutrons in infinite media, diffusion theory, the few-group approximation, point kinetics, and fission-product poisoning. Emphasizes the nuclear physics bases of reactor design and its relationship to reactor engineering problems.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"24-121"}]},{"type":"Recitation","options":[{"days":["F"],"start":"09:00","end":"11:00","room":"24-121"}]}],"url":"http://student.mit.edu/catalog/m22a.html#22.05","terms":["fall"],"rating":5.13,"hours":10.11,"inClassHours":4.29,"outOfClassHours":5.82,"prerequisites":"18.03, 22.01, (1.000/2.086/6.100B/12.010)","corequisites":"","recommendedPreparation":""},{"code":"22.051","title":"Systems Analysis of the Nuclear Fuel Cycle","level":"U","description":"Studies the relationship between technical and policy elements of the nuclear fuel cycle. Topics include uranium supply, enrichment, fuel fabrication, in-core reactivity and fuel management of uranium and other fuel types, used fuel reprocessing, and waste disposal. Presents principles of fuel cycle economics and the applied reactor physics of both contemporary and proposed thermal and fast reactors. Examines nonproliferation aspects, disposal of excess weapons plutonium, and transmutation of long lived radioisotopes in spent fuel. Several state-of-the-art computer programs relevant to reactor core physics and heat transfer are provided for student use in problem sets and term papers.  Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"24-115"}]}],"url":"http://student.mit.edu/catalog/m22a.html#22.051","terms":["fall"],"rating":6.2,"hours":7.06,"inClassHours":2.91,"outOfClassHours":4.15,"prerequisites":"22.05","corequisites":"","recommendedPreparation":""},{"code":"22.07","title":"Introduction to Materials in Nuclear Science and Engineering","level":"U","description":"Introduces the fundamental concepts of processing-structure-properties for materials used in nuclear science and engineering. Presents basic crystallography and thermodynamics, phase stability, mechanical properties, and microstructure factors. Covers radiation effects and defect production, knock-ons, transmutation, cascades, swelling, and electronic excitations. Includes the study of radiation detectors, as well as materials in fission and fusion energy applications, core internal, cladding, and waste.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"24-112"}]}],"url":"http://student.mit.edu/catalog/m22a.html#22.07","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"22.072","title":"Corrosion: The Environmental Degradation of Materials","level":"U","description":"Applies thermodynamics and kinetics of electrode reactions to aqueous corrosion of metals and alloys. Application of advanced computational and modeling techniques to evaluation of materials selection and susceptibility of metal/alloy systems to environmental degradation in aqueous systems. Discusses materials degradation problems in marine environments, oil and gas production, and energy conversion and generation systems, including fossil and nuclear.  Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"24-121"}]}],"url":"http://student.mit.edu/catalog/m22a.html#22.072","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"22.081","title":"Introduction to Sustainable Energy","level":"U","description":"Assessment of current and potential future energy systems. Covers resources, extraction, conversion, and end-use technologies, with emphasis on meeting 21st-century regional and global energy needs in a sustainable manner. Examines various renewable and conventional energy production technologies, energy end-use practices and alternatives, and consumption practices in different countries. Investigates their attributes within a quantitative analytical framework for evaluation of energy technology system proposals. Emphasizes analysis of energy propositions within an engineering, economic and social context. Students taking graduate version complete additional assignments. Limited to juniors and seniors.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"10-250"}]}],"url":"http://student.mit.edu/catalog/m22a.html#22.081","terms":["fall"],"rating":5.65,"hours":8.07,"inClassHours":3.13,"outOfClassHours":4.94,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"22.101","title":"Applied Nuclear Physics","level":"G","description":"Provides an accelerated introduction to the basic principles of nuclear physics and its application within nuclear science and engineering. Fundamentals of quantum mechanics, nuclear properties, and nuclear structure. Origins of radioactivity and radioactive decay processes. Development of nuclear reaction theory, including cross sections, energetics, and kinematics. The interactions of photons, electrons, neutrons, and ions with matter, including the use of nuclear data and modeling tools. Basic theory of radiation and particle detection, shielding, and dosimetry. Uses of nuclear physics in energy, medicine, security, and science applications.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"24-115"}]},{"type":"Recitation","options":[{"days":["F"],"start":"15:00","end":"16:00","room":"24-307"}]}],"url":"http://student.mit.edu/catalog/m22b.html#22.101","terms":["fall"],"rating":3.77,"hours":13.07,"inClassHours":3.7,"outOfClassHours":9.37,"prerequisites":"GIR:PHY2, 18.03","corequisites":"","recommendedPreparation":""},{"code":"22.103","title":"Nuclear Technology and Society","level":"G","description":"Introduces the societal context and challenges for nuclear technology. Major themes include economics and valuation of nuclear power, interactions with government and regulatory frameworks, safety, quantification of radiation hazards, and public attitudes to risk. Covers policies and methods for limiting nuclear-weapons proliferation, including nuclear detection, materials security, and fuel-cycle policy.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"45-102"}]}],"url":"http://student.mit.edu/catalog/m22b.html#22.103","terms":["fall"],"rating":6.63,"hours":9.83,"inClassHours":3.13,"outOfClassHours":6.7,"prerequisites":"22.01/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"22.251","title":"Systems Analysis of the Nuclear Fuel Cycle","level":"G","description":"Study of the relationship between the technical and policy elements of the nuclear fuel cycle. Topics include uranium supply, enrichment, fuel fabrication, in-core reactivity and fuel management of uranium and other fuel types, used fuel reprocessing and waste disposal. Principles of fuel cycle economics and the applied reactor physics of both contemporary and proposed thermal and fast reactors are presented. Nonproliferation aspects, disposal of excess weapons plutonium, and transmutation of long lived radioisotopes in spent fuel are examined. Several state-of-the-art computer programs relevant to reactor core physics and heat transfer are provided for student use in problem sets and term papers. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"24-115"}]}],"url":"http://student.mit.edu/catalog/m22b.html#22.251","terms":["fall"],"rating":6.2,"hours":7.07,"inClassHours":2.91,"outOfClassHours":4.16,"prerequisites":"22.05","corequisites":"","recommendedPreparation":""},{"code":"22.312","title":"Engineering of Nuclear Reactors","level":"G","description":"Engineering principles of nuclear reactors, emphasizing power reactors. Power plant thermodynamics, reactor heat generation and removal (single-phase as well as two-phase coolant flow and heat transfer), and structural mechanics. Engineering considerations in reactor design.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"24-112"}]},{"type":"Recitation","options":[{"days":["T"],"start":"12:30","end":"13:30","room":"24-112"}]}],"url":"http://student.mit.edu/catalog/m22b.html#22.312","terms":["fall"],"rating":6.13,"hours":18.23,"inClassHours":3.98,"outOfClassHours":14.25,"prerequisites":"(2.001, 2.005)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"22.33","title":"Nuclear Engineering Design","level":"G","description":"Group design project involving integration of nuclear physics, particle transport, control, heat transfer, safety, instrumentation, materials, environmental impact, and economic optimization. Provides opportunity to synthesize knowledge acquired in nuclear and non-nuclear subjects and apply this knowledge to practical problems of current interest in nuclear applications design. Past projects have included using a fusion reactor for transmutation of nuclear waste, design and implementation of an experiment to predict and measure pebble flow in a pebble bed reactor, and development of a mission plan for a manned Mars mission including the conceptual design of a nuclear powered space propulsion system and power plant for the Mars surface. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"24-112"}]}],"url":"http://student.mit.edu/catalog/m22b.html#22.33","terms":["fall"],"rating":5.55,"hours":12.6,"inClassHours":2.79,"outOfClassHours":9.81,"prerequisites":"22.312","corequisites":"","recommendedPreparation":""},{"code":"22.39","title":"Integration of Reactor Design, Operations, and Safety","level":"G","description":"Integration of reactor physics and engineering sciences into nuclear power plant design focusing on designs that are projected to be used in the first half of this century. Topics include materials issues in plant design and operations, aspects of thermal design, fuel depletion and fission-product poisoning, and temperature effects on reactivity. Safety considerations in regulations and operations such as the evolution of the regulatory process, the concept of defense in depth, general design criteria, accident analysis, probabilistic risk assessment, and risk-informed regulations. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"24-115"}]}],"url":"http://student.mit.edu/catalog/m22b.html#22.39","terms":["fall"],"rating":6.22,"hours":10.22,"inClassHours":3.02,"outOfClassHours":7.2,"prerequisites":"22.211, 22.312","corequisites":"","recommendedPreparation":""},{"code":"22.54","title":"Biomedical Imaging with MRI: From Technology to Computation Applications","level":"U","description":"Presents medical imaging with MRI, motivated by examples of problems in human health that engage students in imaging hardware design, data acquisition and image reconstruction, and signal analysis and inference. Data from scientific and clinical applications in neuro- and cardiac MRI as applied in current practice are sourced for computational labs. Labs include kits for interactive and portable low-cost devices that can be assembled by the students to demonstrate fundamental building blocks of an MRI system. Students program lab MRI systems on their laptops for data collection and image reconstruction. Students apply concepts from lectures in labs for data collection for image reconstruction, image analysis, and inference by their own design, drawing on concepts in signal processing and machine learning.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"15:00","room":"48-316"}]},{"type":"Lab","options":[{"days":["F"],"start":"14:00","end":"17:00","room":"38-530"}]}],"url":"http://student.mit.edu/catalog/m22b.html#22.54","terms":["fall"],"rating":7.0,"hours":6.5,"inClassHours":5.5,"outOfClassHours":1.0,"prerequisites":"(18.C06, (6.3000/16.002))/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"22.611","title":"Introduction to Plasma Physics I","level":"G","description":"Introduces plasma phenomena relevant to energy generation by controlled thermonuclear fusion and to astrophysics. Elementary plasma concepts, plasma characterization. Motion of charged particles in magnetic fields. Coulomb collisions, relaxation times, transport processes. Two-fluid hydrodynamic and MHD descriptions. Plasma confinement by magnetic fields, simple equilibrium and stability analysis. Wave propagation in a magnetic field; application to RF plasma heating. Introduction to kinetic theory; Vlasov, Boltzmann and Fokker-Planck equations; relation of fluid and kinetic descriptions. Electron and ion acoustic plasma waves, Landau damping.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:30","room":"NW14-1112"}]}],"url":"http://student.mit.edu/catalog/m22c.html#22.611","terms":["fall"],"rating":5.87,"hours":14.53,"inClassHours":3.42,"outOfClassHours":11.11,"prerequisites":"(6.2300/8.07), (18.04/''Coreq: 18.075'')","corequisites":"","recommendedPreparation":""},{"code":"22.64","title":"Ionized Gases","level":"G","description":"Properties and behavior of low-temperature plasmas for energy conversion, plasma propulsion, and gas lasers. Equilibrium of ionized gases: energy states, statistical mechanics, and relationship to thermodynamics. Kinetic theory: motion of charged particles, distribution function, collisions, characteristic lengths and times, cross sections, and transport properties. Gas surface interactions: thermionic emission, sheaths, and probe theory. Radiation in plasmas and diagnostics.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"33-319"}]}],"url":"http://student.mit.edu/catalog/m22c.html#22.64","terms":["fall"],"rating":6.61,"hours":8.79,"inClassHours":3.01,"outOfClassHours":5.78,"prerequisites":"8.02/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"22.71","title":"Modern Physical Metallurgy","level":"G","description":"Focuses on the links between the processing, structure, and properties of metals and alloys. First, the physical bases for strength, stiffness, and ductility are discussed with reference to crystallography, defects, and microstructure. Second, phase transformations and microstructural evolution are studied in the context of alloy thermodynamics and kinetics. Together, these components comprise the modern paradigm for designing metallic microstructures for optimized properties. Concludes with a focus on processing-microstructure-property relationships in structural engineering alloys. Students taking the graduate version explore the subject in greater depth.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:30","end":"17:00","room":"4-261"}]}],"url":"http://student.mit.edu/catalog/m22c.html#22.71","terms":["fall"],"rating":6.15,"hours":8.66,"inClassHours":3.06,"outOfClassHours":5.6,"prerequisites":"(3.20, 3.22)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"22.72","title":"Corrosion: The Environmental Degradation of Materials","level":"G","description":"Applies thermodynamics and kinetics of electrode reactions to aqueous corrosion of metals and alloys. Application of advanced computational and modeling techniques to evaluation of materials selection and susceptibility of metal/alloy systems to environmental degradation in aqueous systems. Discusses materials degradation problems in marine environments, oil and gas production, and energy conversion and generation systems, including fossil and nuclear.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"24-121"}]}],"url":"http://student.mit.edu/catalog/m22c.html#22.72","terms":["fall"],"rating":5.4,"hours":13.8,"inClassHours":3.8,"outOfClassHours":10.0,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"22.811","title":"Sustainable Energy","level":"G","description":"Assessment of current and potential future energy systems. Covers resources, extraction, conversion, and end-use technologies, with emphasis on meeting 21st-century regional and global energy needs in a sustainable manner. Examines various energy technologies in each fuel cycle stage for fossil (oil, gas, synthetic), nuclear (fission and fusion) and renewable (solar, biomass, wind, hydro, and geothermal) energy types, along with storage, transmission, and conservation issues. Emphasizes analysis of energy propositions within an engineering, economic and social context. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"10-250"}]}],"url":"http://student.mit.edu/catalog/m22c.html#22.811","terms":["fall"],"rating":5.65,"hours":8.07,"inClassHours":3.13,"outOfClassHours":4.94,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"22.911","title":"Seminar in Nuclear Science and Engineering I","level":"G","description":"Provides instruction in aspects of effective oral presentations and exposure to technical communication skills useful for professional conferences and scientific meetings. Focuses on presenting research for scientifically knowledgeable audiences. Culminates in a technical talk at a department-wide seminar series.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"10:00","end":"12:00","room":"24-307"}]}],"url":"http://student.mit.edu/catalog/m22c.html#22.911","terms":["fall"],"rating":4.2,"hours":2.83,"inClassHours":1.6,"outOfClassHours":1.23,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"22.C25","title":"Real World Computation with Julia","level":"U","description":"Focuses on algorithms and techniques for writing and using modern technical software in a job, lab, or research group environment that may consist of interdisciplinary teams, where performance may be critical, and where the software needs to be flexible and adaptable. Topics include automatic differentiation, matrix calculus, scientific machine learning, parallel and GPU computing, and performance optimization with introductory applications to climate science, economics, agent-based modeling, and other areas. Labs and projects focus on performant, readable, composable algorithms, and software. Programming will be in Julia. Expects students to have some familiarity with Python, Matlab, or R. No Julia experience necessary.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"45-102"}]}],"url":"http://student.mit.edu/catalog/m22a.html#22.C25","terms":["fall"],"rating":6.3,"hours":7.33,"inClassHours":3.1,"outOfClassHours":4.23,"prerequisites":"6.100A, 18.03, 18.06","corequisites":"","recommendedPreparation":"Expects students to have some familiarity with Python, Matlab, or R."},{"code":"22.EPE","title":"UPOP Engineering Practice Experience","level":"U","description":"Provides students with skills to prepare for and excel in the world of industry. Emphasizes practical application of career theory and professional development concepts. Introduces students to relevant and timely resources for career development, provides students with tools to embark on a successful internship search, and offers networking opportunities with employers and MIT alumni. Students work in groups, led by industry mentors, to improve their resumes and cover letters, interviewing skills, networking abilities, project management, and ability to give and receive feedback. Objective is for students to be able to adapt and contribute effectively to their future employment organizations. A total of two units of credit is awarded for completion of the fall and subsequent spring term offerings. Application required; consult UPOP website for more information.","groups":[{"type":"Lab","options":[{"days":["M"],"start":"13:00","end":"14:00","room":"3-270"},{"days":["M"],"start":"15:00","end":"16:00","room":"4-237"},{"days":["T"],"start":"13:00","end":"14:00","room":"4-149"},{"days":["T"],"start":"15:00","end":"16:00","room":"3-370"},{"days":["F"],"start":"11:00","end":"12:00","room":"1-390"},{"days":["F"],"start":"13:00","end":"14:00","room":"1-190"}]}],"url":"http://student.mit.edu/catalog/m22a.html#22.EPE","terms":["fall","spring"],"rating":5.75,"hours":1.75,"inClassHours":1.0,"outOfClassHours":0.75,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"22.S092","title":"Special Subject in Nuclear Science and Engineering","level":"U","description":"Seminar or lecture on a topic in nuclear science and engineering that is not covered in the regular curriculum.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"24-115"}]}],"url":"http://student.mit.edu/catalog/m22a.html#22.S092-22.S094","terms":["fall"],"rating":6.0,"hours":4.0,"inClassHours":2.0,"outOfClassHours":2.0,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"22.S902","title":"Special Subject in Nuclear Science and Engineering","level":"G","description":"Seminar or lecture on a topic in nuclear science and engineering that is not covered in the regular curriculum. 22.S905 is graded P/D/F.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"24-115"}]}],"url":"http://student.mit.edu/catalog/m22c.html#22.S902-22.S905","terms":["fall"],"rating":6.63,"hours":6.34,"inClassHours":2.48,"outOfClassHours":3.86,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"22.S906","title":"Special Subject in Nuclear Science and Engineering","level":"G","description":"Seminar or lecture on a topic in nuclear science and engineering that is not covered in the regular curriculum.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"24-112"}]}],"url":"http://student.mit.edu/catalog/m22c.html#22.S906","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"22.THT","title":"Undergraduate Thesis Tutorial","level":"U","description":"Tutorial providing guidance on thesis research, including choosing a research topic and research planning, focusing on written presentation. Practice writing research proposals culminates with the preparation of the undergraduate thesis proposal, to be approved by the department.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"26-322"}]}],"url":"http://student.mit.edu/catalog/m22a.html#22.THT","terms":["fall"],"rating":6.57,"hours":4.1,"inClassHours":1.07,"outOfClassHours":3.03,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"24.01","title":"Classics of Western Philosophy","level":"U","description":"Introduction to Western philosophical tradition through the study of selected major thinkers such as Plato, Aristotle, Lucretius, Descartes, Hobbes, Leibniz, Locke, Berkeley, Hume, Kant, Nietzsche and Marx. Emphasis on changes of intellectual outlook over time, and the complex interplay of scientific, religious and political concerns that influence the development of philosophical ideas.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:00","room":"32-141"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"26-142"},{"days":["F"],"start":"11:00","end":"12:00","room":"24-112"},{"days":["F"],"start":"12:00","end":"13:00","room":"24-112"},{"days":["F"],"start":"13:00","end":"14:00","room":"66-156"},{"days":["F"],"start":"10:00","end":"11:00","room":"24-112"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.01","terms":["fall"],"rating":6.25,"hours":6.2,"inClassHours":3.01,"outOfClassHours":3.19,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"24.04","title":"Justice","level":"U","description":"Provides an introduction to contemporary political thought centered around the ideal of justice and the realities of injustice. Examines what a just society might look like and how we should understand various forms of oppression and domination. Studies three theories of justice (utilitarianism, libertarianism, and egalitarian liberalism) and brings them into conversation with other traditions of political thought (critical theory, communitarianism, republicanism, and post-structuralism). Readings cover foundational debates about equality, freedom, recognition, and power.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"15:00","end":"17:00","room":"48-316"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"56-167"},{"days":["F"],"start":"11:00","end":"12:00","room":"56-167"},{"days":["F"],"start":"12:00","end":"13:00","room":"56-167"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.04","terms":["fall"],"rating":5.84,"hours":6.78,"inClassHours":2.91,"outOfClassHours":3.87,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"24.05","title":"Philosophy of Religion","level":"U","description":"Uses key questions in the philosophy of religion to introduce tools of contemporary philosophy. Explores what defines a god, the possibility of the existence of gods, the potential conflict between religion and science, whether morality requires a divine author, and religious tolerance.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:00","room":"56-154"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"56-169"},{"days":["F"],"start":"11:00","end":"12:00","room":"56-169"},{"days":["F"],"start":"10:00","end":"11:00","room":"26-139"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.05","terms":["fall"],"rating":6.18,"hours":6.42,"inClassHours":2.93,"outOfClassHours":3.49,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"24.118","title":"Paradox and Infinity","level":"U","description":"Presents highlights of the more technical side of philosophy. Studies a cluster of puzzles, paradoxes, and intellectual wonders - from the higher infinite to Godel's Theorem - and discusses their philosophical implications. Recommended prerequisites: 6.100A, 18.01. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:00","room":"32-141"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"24-115"},{"days":["F"],"start":"11:00","end":"12:00","room":"48-308"},{"days":["F"],"start":"12:00","end":"13:00","room":"48-308"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.118","terms":["fall"],"rating":6.09,"hours":7.01,"inClassHours":2.7,"outOfClassHours":4.31,"prerequisites":"","corequisites":"","recommendedPreparation":"Recommended prerequisites: 6.100A, 18.01."},{"code":"24.130","title":"Ethics","level":"U","description":"Survey of moral philosophy in the Western tradition, focusing primarily on utilitarian, Kantian, and Aristotelian moral theories, along with selected criticisms of those theories. Explores the questions of what makes right actions right and wrong actions wrong, what a good life consists of, what it takes to be a virtuous person, and what it means to be free and responsible for one's actions. Debates why these ideas are important. Aim is to understand how some of the most influential philosophers have addressed these questions, and by so doing, to better understand and formulate one's own views. Readings from classic and contemporary authors, including Aristotle, Bentham, Kant, Rawls, Nagel, and Korsgaard. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:00","room":"24-121"}]},{"type":"Recitation","options":[{"days":["W"],"start":"14:00","end":"15:00","room":"56-167"},{"days":["F"],"start":"12:00","end":"13:00","room":"56-191"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.130","terms":["fall"],"rating":6.81,"hours":7.39,"inClassHours":2.97,"outOfClassHours":4.42,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"24.137","title":"Feminist Thought","level":"U","description":"Analyzes theories of gender and politics, especially ideologies of gender and their construction; definitions of public and private spheres; gender issues in citizenship, the development of the welfare state, experiences of war and revolution, class formation, and the politics of sexuality. Graduate students are expected to pursue the subject in greater depth through reading and individual research.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"14E-310"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.137","terms":["fall","spring"],"rating":6.5,"hours":7.12,"inClassHours":3.1,"outOfClassHours":4.02,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"24.141","title":"Logic I","level":"U","description":"Introduction to the aims and techniques of formal logic. The logic of truth functions and quantifiers. The concepts of validity and truth and their relation to formal deduction. Applications of logic and the place of logic in philosophy.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"32-144"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.141","terms":["fall"],"rating":5.92,"hours":6.88,"inClassHours":2.75,"outOfClassHours":4.13,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"24.211","title":"Theory of Knowledge","level":"U","description":"Study of problems concerning our concept of knowledge, our knowledge of the past, our knowledge of the thoughts and feelings of ourselves and others, and our knowledge of the existence and properties of physical objects in our immediate environment. Enrollment may be limited; preference to Course 24 majors and minors.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"35-308"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.211","terms":["fall"],"rating":5.42,"hours":6.7,"inClassHours":3.0,"outOfClassHours":3.7,"prerequisites":"''One philosophy subject''","corequisites":"","recommendedPreparation":"Study of problems concerning our concept of knowledge, our knowledge of the past, our knowledge of the thoughts and feelings of ourselves and others, and our knowledge of the existence and properties of physical objects in our immediate environment."},{"code":"24.212","title":"Philosophy of Perception","level":"U","description":"In-depth examination of philosophical issues concerning perception, such as whether we see mind-independent physical objects or, alternatively, mind-dependent representations; whether perception is a source of theory-neutral observations or is affected by the perceiver's beliefs in a way that compromises the objectivity of science. Readings primarily drawn from contemporary literature in both philosophy and psychology. Enrollment may be limited; preference to Course 24 majors and minors.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"36-144"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.212","terms":["fall"],"rating":5.76,"hours":8.58,"inClassHours":3.0,"outOfClassHours":5.58,"prerequisites":"''One philosophy subject''/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"24.234","title":"Global Justice, Gender, and Development","level":"U","description":"Addresses challenges in working towards global justice including poverty, food and water insecurity, healthcare disparities, human rights violations, violence and dislocation, and environmental risk. Focuses on gender and identity, locating the root causes of inequality within cultural, political and economic contexts. Designed to give a framework to understand gender dynamics. Teaches how to integrate gender sensitive strategies into development work. Classes, readings, and final projects illustrate how design and implementation of international development strategies can provide capacity building and income generation opportunities. Meets with EC.718 when offered concurrently. Students taking graduate version complete additional assignments. Limited to 20 total for versions meeting together.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:30","end":"12:30","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.234","terms":["fall"],"rating":5.57,"hours":8.94,"inClassHours":3.62,"outOfClassHours":5.32,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"24.251","title":"Introduction to Philosophy of Language","level":"U","description":"Examines views on the nature of meaning, reference, and truth, and their bearing on the use of language in communication. No knowledge of logic or linguistics presupposed. Instruction and practice in oral and written communication provided. Enrollment may be limited; preference to Course 24 majors and minors.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"66-160"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.251","terms":["fall"],"rating":6.69,"hours":7.39,"inClassHours":3.0,"outOfClassHours":4.39,"prerequisites":"''One philosophy subject''","corequisites":"","recommendedPreparation":"No knowledge of logic or linguistics presupposed."},{"code":"24.260","title":"Topics in Philosophy","level":"U","description":"Close examination of a single book, or group of related essays, with major significance in recent philosophy. Subject matter varies from year to year. Intended primarily for majors and minors in philosophy. Opportunities are provided for oral presentation. Students will be required to revise at least one paper in response to instructor's comments. Enrollment may be limited; preference to Course 24 majors and minors.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"66-148"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.260","terms":["fall"],"rating":5.18,"hours":7.72,"inClassHours":3.0,"outOfClassHours":4.72,"prerequisites":"''Two subjects in philosophy''","corequisites":"","recommendedPreparation":""},{"code":"24.280","title":"Foundations of Probability","level":"U","description":"Topics include probability puzzles, common fallacies in probabilistic reasoning, defenses and criticisms of Kolmogorov's axiomatization, interpretations of probability (including the frequency, logical, propensity, and various subjectivist interpretations), the relation of objective chance to rational subjective credence, conditional probability, rules for updating probability, and proposals for supplementing the probability calculus with further principles. Enrollment may be limited; preference to Course 24 majors and minors.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"66-148"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.280","terms":["fall"],"rating":5.76,"hours":4.85,"inClassHours":2.8,"outOfClassHours":2.05,"prerequisites":"''One philosophy subject''/''one subject on probability''","corequisites":"","recommendedPreparation":""},{"code":"24.400","title":"Proseminar in Philosophy I","level":"G","description":"Advanced study of the basic problems of philosophy. Intended for first-year graduate students in philosophy.","groups":[{"type":"Lecture","options":[{"days":["M","F"],"start":"10:00","end":"13:00","room":"32-D831"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.400","terms":["fall"],"rating":6.77,"hours":13.84,"inClassHours":5.95,"outOfClassHours":7.89,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"24.402","title":"Logic for Philosophers","level":"G","description":"Covers various logical and formal tools most philosophers can benefit from knowing. Topics include: basic concepts in logic, how to translate from natural language into formal languages, how to work with logical systems to prove validity and invalidity of arguments, and how to prove metalogical results about the logical systems most useful to philosophers. Covers aspects of propositional logic, first order logic, modal logic, conditional logic, and basic set theory and model theory.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"32-D918"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.402","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"24.500","title":"Topics in Philosophy of Mind","level":"G","description":"Selected topics in philosophy of mind. Content varies from year to year. Topics may include consciousness, mental representation, perception, and mental causation.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"32-D831"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.500","terms":["fall"],"rating":5.0,"hours":6.0,"inClassHours":3.0,"outOfClassHours":3.0,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"24.601","title":"Topics in Moral Philosophy","level":"G","description":"Systematic examination of selected problems in moral philosophy. Content varies from year to year. Subject may be repeated only with permission of instructor and advisor.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"14:00","end":"17:00","room":"32-D831"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.601","terms":["fall"],"rating":6.05,"hours":7.97,"inClassHours":3.11,"outOfClassHours":4.86,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"24.611","title":"Political Philosophy","level":"G","description":"Systematic examination of selected issues in political philosophy. Topic changes each year and subject may be taken repeatedly with permission of instructor.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"10:00","end":"12:00","room":"E53-485"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.611","terms":["fall","spring"],"rating":6.49,"hours":7.6,"inClassHours":2.1,"outOfClassHours":5.5,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"24.634","title":"Global Justice, Gender, and Development","level":"G","description":"Addresses challenges in working towards global justice including poverty, food and water insecurity, healthcare disparities, human rights violations, violence and dislocation, and environmental risk. Focuses on gender and identity, locating the root causes of inequality within cultural, political and economic contexts. Designed to give a framework to understand gender dynamics. Teaches how to integrate gender sensitive strategies into development work. Classes, readings, and final projects illustrate how design and implementation of international development strategies can provide capacity building and income generation opportunities. Meets with EC.798 when offered concurrently. Students taking graduate version complete additional assignments. Limited to 20 total for versions meeting together.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:30","end":"12:30","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.634","terms":["fall"],"rating":5.57,"hours":8.94,"inClassHours":3.62,"outOfClassHours":5.32,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"24.635","title":"Topics in Critical Social Theory","level":"G","description":"Explores topics arising within critical race theory, feminist theory, queer theory, disability studies, working class studies, and related interdisciplinary efforts - both historical and contemporary - to understand and promote social justice.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"32-D831"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.635","terms":["fall"],"rating":7.0,"hours":8.1,"inClassHours":3.0,"outOfClassHours":5.1,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"24.637","title":"Feminist Thought","level":"G","description":"Analyzes theories of gender and politics, especially ideologies of gender and their construction; definitions of public and private spheres; gender issues in citizenship, the development of the welfare state, experiences of war and revolution, class formation, and the politics of sexuality. Graduate students are expected to pursue the subject in greater depth through reading and individual research.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"14E-310"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.637","terms":["fall","spring"],"rating":6.5,"hours":7.12,"inClassHours":3.1,"outOfClassHours":4.02,"prerequisites":"''Permission of instructor'', based on previous coursework","corequisites":"","recommendedPreparation":""},{"code":"24.893","title":"Dissertation Workshop","level":"G","description":"Workshop for students working on their dissertations. Restricted to Philosophy doctoral students.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"15:00","end":"16:30","room":"32-D769"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.893","terms":["fall","spring"],"rating":6.8,"hours":4.67,"inClassHours":2.67,"outOfClassHours":2.0,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"24.900","title":"Introduction to Linguistics","level":"U","description":"Studies what is language and what does knowledge of a language consist of. It asks how do children learn languages and is language unique to humans; why are there many languages; how do languages change; is any language or dialect superior to another; and how are speech and writing related. Context for these and similar questions provided by basic examination of internal organization of sentences, words, and sound systems. Assumes no prior training in linguistics.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"3-270"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"56-162"},{"days":["F"],"start":"11:00","end":"12:00","room":"56-162"},{"days":["F"],"start":"11:00","end":"12:00","room":"26-322"},{"days":["F"],"start":"12:00","end":"13:00","room":"26-322"},{"days":["F"],"start":"13:00","end":"14:00","room":"26-142"},{"days":["F"],"start":"13:00","end":"14:00","room":"56-162"}]}],"url":"http://student.mit.edu/catalog/m24b.html#24.900","terms":["fall","spring"],"rating":5.57,"hours":7.59,"inClassHours":3.32,"outOfClassHours":4.27,"prerequisites":"","corequisites":"","recommendedPreparation":"Studies what is language and what does knowledge of a language consist of."},{"code":"24.901","title":"Language and Its Structure I: Phonology","level":"U","description":"Introduction to fundamental concepts in phonological theory and their relation to issues in philosophy and cognitive psychology. Articulatory and acoustic phonetics, distinctive features and the structure of feature systems, underlying representations and underspecification, phonological rules and derivations, syllable structure, accentual systems, and the morphology-phonology interface. Examples and exercises from a variety of languages. Students taking graduate version complete different assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"32-D831"}]}],"url":"http://student.mit.edu/catalog/m24b.html#24.901","terms":["fall"],"rating":6.35,"hours":5.63,"inClassHours":2.95,"outOfClassHours":2.68,"prerequisites":"24.900/24.9000","corequisites":"","recommendedPreparation":""},{"code":"24.902","title":"Language and Its Structure II: Syntax","level":"U","description":"Introduction to fundamental concepts in syntactic theory and its relation to issues in philosophy and cognitive psychology. Examples and exercises from a variety of languages. Students taking graduate version complete different assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"36-156"}]}],"url":"http://student.mit.edu/catalog/m24b.html#24.902","terms":["fall"],"rating":6.37,"hours":7.53,"inClassHours":3.0,"outOfClassHours":4.53,"prerequisites":"24.900/24.9000","corequisites":"","recommendedPreparation":""},{"code":"24.917","title":"ConLangs: How to Construct a Language","level":"U","description":"Explores languages that have been deliberately constructed (ConLangs), including Esperanto, Klingon, and Tolkien's Elvish. Students construct their own languages while considering phenomena from a variety of languages of the world. Topics include writing systems, phonology (basic units of speech and how they combine), morphology (structure of words), syntax (how words are put together), and semantics (the expression of meaning, and what language leaves unexpressed). Through regular assignments, students describe their constructed language in light of the topics discussed. Final assignment is a grammatical description of the new language.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"32-144"}]}],"url":"http://student.mit.edu/catalog/m24b.html#24.917","terms":["fall"],"rating":6.42,"hours":6.3,"inClassHours":2.8,"outOfClassHours":3.5,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"24.931","title":"Language and Its Structure I: Phonology","level":"G","description":"Introduction to fundamental concepts in phonological theory and their relation to issues in philosophy and cognitive psychology. Articulatory and acoustic phonetics, distinctive features and the structure of feature systems, underlying representations and underspecification, phonological rules and derivations, syllable structure, accentual systems, and the morphology-phonology interface. Examples and exercises from a variety of languages. Students taking graduate version complete different assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"32-D831"}]}],"url":"http://student.mit.edu/catalog/m24b.html#24.931","terms":["fall"],"rating":6.35,"hours":5.63,"inClassHours":2.95,"outOfClassHours":2.68,"prerequisites":"24.900/24.9000/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"24.932","title":"Language and Its Structure II: Syntax","level":"G","description":"Introduction to fundamental concepts in syntactic theory and its relation to issues in philosophy and cognitive psychology. Examples and exercises from a variety of languages. Students taking graduate version complete different assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"36-156"}]}],"url":"http://student.mit.edu/catalog/m24b.html#24.932","terms":["fall"],"rating":6.37,"hours":7.53,"inClassHours":3.0,"outOfClassHours":4.53,"prerequisites":"24.900/24.9000/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"24.949","title":"Language Acquisition I","level":"G","description":"Lectures, reading, and discussion of current theory and data concerning the psychology and biology of language acquisition. Emphasizes learning of syntax, semantics, and morphology, together with some discussion of phonology, and especially research relating grammatical theory and learnability theory to empirical studies of children.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"09:30","end":"11:00","room":"32-D461"}]}],"url":"http://student.mit.edu/catalog/m24b.html#24.949","terms":["fall"],"rating":6.97,"hours":6.88,"inClassHours":3.05,"outOfClassHours":3.83,"prerequisites":"24.952, 24.970, 24.973","corequisites":"","recommendedPreparation":""},{"code":"24.951","title":"Introduction to Syntax","level":"G","description":"Introduction to theories of syntax underlying work currently being done within the lexical-functional and government-binding frameworks. Organized into three interrelated parts, each focused upon a particular area of concern: phrase structure; the lexicon; and principles and parameters. Grammatical rules and processes constitute a focus of attention throughout the course that serve to reveal both modular structure of grammar and interaction of grammatical components.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"36-372"}]}],"url":"http://student.mit.edu/catalog/m24b.html#24.951","terms":["fall"],"rating":6.17,"hours":11.45,"inClassHours":3.96,"outOfClassHours":7.49,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"24.955","title":"More Advanced Syntax","level":"G","description":"An advanced-level survey of topics in syntax.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"14:00","end":"17:00","room":"32-D461"}]}],"url":"http://student.mit.edu/catalog/m24b.html#24.955","terms":["fall"],"rating":6.99,"hours":6.04,"inClassHours":3.0,"outOfClassHours":3.04,"prerequisites":"24.951, 24.952","corequisites":"","recommendedPreparation":""},{"code":"24.961","title":"Introduction to Phonology","level":"G","description":"First half of a year-long introduction to the phonological component of grammar. Introduces the major research results, questions, and analytic techniques in the field of phonology. Focuses on segmental feature structure and prosodic structure while the sequel (24.962) considers the interfaces of phonology with morphology, syntax, and the lexicon. Students should have basic knowledge of articulatory phonetic description and phonetic transcription.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"36-156"}]}],"url":"http://student.mit.edu/catalog/m24b.html#24.961","terms":["fall"],"rating":6.28,"hours":12.96,"inClassHours":3.79,"outOfClassHours":9.17,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":"Students should have basic knowledge of articulatory phonetic description and phonetic transcription."},{"code":"24.964","title":"Topics in Phonology","level":"G","description":"In-depth study of a topic in current phonological theory.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"09:00","end":"12:00","room":"32-D461"}]}],"url":"http://student.mit.edu/catalog/m24b.html#24.964","terms":["fall"],"rating":7.0,"hours":10.42,"inClassHours":3.0,"outOfClassHours":7.42,"prerequisites":"24.961","corequisites":"","recommendedPreparation":""},{"code":"24.970","title":"Introduction to Semantics","level":"G","description":"Basic issues of form and meaning in formalized and natural languages. Conceptual, logical, and linguistic questions about truth. Reference, modal, and intensional notions. The role of grammar in language use and context-dependency. Ambiguities of structure and meaning, and dimensions of semantic variation in syntax and the lexicon.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"26-322"}]}],"url":"http://student.mit.edu/catalog/m24b.html#24.970","terms":["fall"],"rating":6.66,"hours":11.28,"inClassHours":3.97,"outOfClassHours":7.31,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"24.979","title":"Topics in Semantics","level":"G","description":"Seminar on current research in semantics and generative grammar. Topics may vary from year to year.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"10:00","end":"13:00","room":"32-D461"}]}],"url":"http://student.mit.edu/catalog/m24b.html#24.979","terms":["fall"],"rating":5.19,"hours":7.88,"inClassHours":3.02,"outOfClassHours":4.86,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"24.981","title":"Topics in Computational Phonology","level":"G","description":"Exploration of issues in the computational modeling of phonology: finding generalizations in data, formalisms for representing phonological knowledge, modeling grammar acquisition, and testing phonological theories by means of implemented models. Experience using and developing models, including preparing training data, running simulations, and interpreting their results. No background in programming or machine learning is assumed.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"10:00","end":"13:00","room":"32-D831"}]}],"url":"http://student.mit.edu/catalog/m24b.html#24.981","terms":["fall"],"rating":6.21,"hours":8.05,"inClassHours":3.02,"outOfClassHours":5.03,"prerequisites":"24.961/''permission of instructor''","corequisites":"","recommendedPreparation":"No background in programming or machine learning is assumed."},{"code":"24.991","title":"Workshop in Linguistics","level":"G","description":"An intensive group tutorial/seminar for discussion of research being conducted by participants. No listeners.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"32-D769"}]}],"url":"http://student.mit.edu/catalog/m24b.html#24.991","terms":["fall","spring"],"rating":6.58,"hours":6.35,"inClassHours":2.78,"outOfClassHours":3.57,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"24.992","title":"Advanced Workshop in Linguistics","level":"G","description":"Intensive group tutorial/seminar for discussion of dissertation research being conducted by participants. Students who have finished both of their generals papers and who are actively working on their dissertations are expected to enroll. A special focus on either P-side or S-side research is determined by group membership. No listeners.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"32-D461"}]}],"url":"http://student.mit.edu/catalog/m24b.html#24.992","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"24.C40","title":"Ethics of Computing","level":"U","description":"Explores ethical questions raised by the potentially transformative power of computing technologies. Topics include: lessons from the history of transformative technologies; the status of property and privacy rights in the digital realm; effective accelerationism, AI alignment, and existential risk; algorithmic bias and algorithmic fairness; and free speech, disinformation, and polarization on online platforms.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:00","room":"32-155"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"56-180"},{"days":["F"],"start":"11:00","end":"12:00","room":"56-180"}]}],"url":"http://student.mit.edu/catalog/m24a.html#24.C40","terms":["fall"],"rating":5.83,"hours":6.63,"inClassHours":3.13,"outOfClassHours":3.5,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"24.S95","title":"Special Seminar: Linguistics","level":"G","description":"Graduate subject that covers topics not offered in the regular curriculum. Consult department to learn of offerings for a particular term.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"32-D461"}]}],"url":"http://student.mit.edu/catalog/m24b.html#24.S95","terms":["fall"],"rating":6.71,"hours":5.86,"inClassHours":3.0,"outOfClassHours":2.86,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"3.002","title":"Materials for Energy and Sustainability","level":"U","description":"Materials play a central role in the ongoing global transformation towards more sustainable means of harvesting, storing, and conserving energy, through better batteries, fuel cells, hydrogen electrolyzers, photovoltaics, and the like. Methods for producing materials such as cement, steel, ammonia, and ethylene, which rank amongst today's largest industrial emitters of greenhouse gases, are being re-invented. Much of this work is taking place at MIT and surrounding cleantech startups. This class discusses the underlying science of selected new technologies, the challenges which must be overcome, and the magnitude of their potential impact. Visits to the startups behind each case study and meetings with the scientists and engineers creating these technologies are included. Subject can count toward 6-unit discovery-focused credit limit for first-year students. Preference to first-year students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:30","end":"17:00","room":"6-120"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.002","terms":["fall"],"rating":6.24,"hours":1.97,"inClassHours":1.91,"outOfClassHours":0.06,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"3.006","title":"NEET Seminar: Advanced Materials Machines","level":"U","description":"Seminar for students enrolled in the Advanced Materials Machines NEET thread. Focuses on topics around innovative materials manufacturing via guest lectures and research discussions.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"19:00","end":"20:00","room":"3-001"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.006","terms":["fall","spring"],"rating":5.86,"hours":1.77,"inClassHours":1.11,"outOfClassHours":0.66,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"3.0061","title":"Introduction to Design Thinking and Rapid Prototyping","level":"U","description":"Focuses on design thinking, an iterative process that uses divergent and convergent thinking to approach design problems and prototype and test solutions. Includes experiences in creativity, problem scoping, and rapid prototyping skills. Skills are built over the course of the semester through design exercises and projects. Enrollment limited; preference to Course 22 & Course 3 majors and minors, and NEET students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:00","end":"17:00","room":"N52-342B"}]},{"type":"Lab","options":[{"days":["W"],"start":"15:00","end":"17:00","room":"N52-342B"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.0061","terms":["fall"],"rating":6.66,"hours":7.05,"inClassHours":4.3,"outOfClassHours":2.75,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"3.010","title":"Structure of Materials","level":"U","description":"Describes the fundamentals of bonding and structure that underpin materials science. Structure of noncrystalline, crystalline, and liquid-crystalline states across length scales including short and long range ordering. Point, line, and surface imperfections in materials. Diffraction and structure determination. Covers molecular geometry and levels of structure in biological materials. Includes experimental and computational exploration of the connections between structure, properties, processing, and performance of materials. Covers methodology of technical communication (written/oral) with a view to integrate experimental design, execution, and analysis.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:00","room":"4-231"}]},{"type":"Lab","options":[{"days":["F"],"start":"09:00","end":"12:00","room":"4-261"},{"days":["F"],"start":"14:00","end":"17:00","room":"4-153"}]},{"type":"Recitation","options":[{"days":["T"],"start":"10:00","end":"11:00","room":"26-204"},{"days":["T"],"start":"11:00","end":"12:00","room":"26-204"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.010","terms":["fall"],"rating":5.35,"hours":9.42,"inClassHours":4.38,"outOfClassHours":5.04,"prerequisites":"GIR:CHEM","corequisites":"18.03/18.032/18.06","recommendedPreparation":""},{"code":"3.013","title":"Mechanics of Materials","level":"U","description":"Basic concepts of solid mechanics and mechanical behavior of materials: elasticity, stress-strain relationships, stress transformation, viscoelasticity, plasticity, and fracture. Continuum behavior as well as atomistic explanations of the observed behavior are described. Examples from engineering as well as biomechanics. Lab experiments, computational exercises, and demonstrations give hands-on experience of the physical concepts.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:00","room":"4-231"}]},{"type":"Lab","options":[{"days":["F"],"start":"09:00","end":"12:00","room":"4-261"},{"days":["F"],"start":"14:00","end":"17:00","room":"4-153"}]},{"type":"Recitation","options":[{"days":["R"],"start":"10:00","end":"11:00","room":"8-119"},{"days":["R"],"start":"11:00","end":"12:00","room":"8-119"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.013","terms":["fall"],"rating":4.95,"hours":10.27,"inClassHours":4.21,"outOfClassHours":6.06,"prerequisites":"GIR:PHY1","corequisites":"(18.03/18.06)/''permission of instructor''","recommendedPreparation":""},{"code":"3.016","title":"Computational Methods for Materials Scientists and Engineers","level":"U","description":"Computational and analytical techniques necessary for materials science and engineering topics, such as material structure, symmetry, and thermodynamics, materials response to applied fields, mechanics and physics of solids and soft materials. Presents mathematical concepts and materials-related problem solving skills alongside symbolic programming techniques. Symbolic algebraic computational methods, programming, and visualization techniques; topics include linear algebra, quadratic forms, tensor operations, symmetry operations, calculus of several variables, eigensystems, systems of ordinary and partial differential equations, beam theory, resonance phenomena, special functions, numerical solutions, statistical analysis, Fourier analysis, and random walks.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"16:00","end":"17:00","room":"32-082"}]},{"type":"Lab","options":[{"days":["R"],"start":"19:30","end":"20:30","room":"4-231"}]},{"type":"Recitation","options":[{"days":["T"],"start":"11:00","end":"12:00","room":"4-146"},{"days":["R"],"start":"14:00","end":"15:00","room":"4-146"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.016","terms":["fall"],"rating":5.69,"hours":14.82,"inClassHours":4.32,"outOfClassHours":10.5,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"3.030","title":"Microstructural Evolution in Materials","level":"U","description":"Covers microstructures, defects, and structural evolution in all classes of materials. Topics include solution kinetics, interface stability, dislocations and point defects, diffusion, surface energetics, grains and grain boundaries, grain growth, nucleation and precipitation, and electrochemical reactions. Lectures illustrate a range of examples and applications based on metals, ceramics, electronic materials, polymers, and biomedical materials. Explores the evolution of microstructure through experiments involving optical and electron microscopy, calorimetry, electrochemical characterization, surface roughness measurements, and other characterization methods. Investigates structural transitions and structure-property relationships through practical materials examples.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"12:00","end":"13:00","room":"4-231"}]},{"type":"Lab","options":[{"days":["T"],"start":"09:00","end":"12:00","room":"8-107"},{"days":["T"],"start":"14:00","end":"17:00","room":"8-107"}]},{"type":"Recitation","options":[{"days":["R"],"start":"11:00","end":"12:00","room":"4-144"},{"days":["R"],"start":"15:00","end":"16:00","room":"4-144"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.030","terms":["fall"],"rating":4.57,"hours":11.49,"inClassHours":5.15,"outOfClassHours":6.34,"prerequisites":"3.010, 3.020","corequisites":"","recommendedPreparation":""},{"code":"3.033","title":"Electronic, Optical and Magnetic Properties of Materials","level":"U","description":"Uses fundamental principles of quantum mechanics, solid state physics, electricity and magnetism to describe how the electronic, optical and magnetic properties of materials originate. Illustrates how these properties can be designed for particular applications, such as diodes, solar cells, optical fibers, and magnetic data storage. Involves experimentation using spectroscopy, resistivity, impedance and magnetometry measurements, behavior of light in waveguides, and other characterization methods. Uses practical examples to investigate structure-property relationships.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"13:00","end":"14:00","room":"4-231"}]},{"type":"Lab","options":[{"days":["T"],"start":"09:00","end":"12:00","room":"8-107"},{"days":["T"],"start":"14:00","end":"17:00","room":"8-107"}]},{"type":"Recitation","options":[{"days":["R"],"start":"10:00","end":"11:00","room":"4-144"},{"days":["R"],"start":"14:00","end":"15:00","room":"4-144"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.033","terms":["fall"],"rating":4.31,"hours":13.95,"inClassHours":5.35,"outOfClassHours":8.6,"prerequisites":"3.010, 3.020","corequisites":"","recommendedPreparation":""},{"code":"3.042","title":"Materials Project Laboratory","level":"U","description":"Serves as the capstone design course in the DMSE curriculum. Working in groups, students explore the research and design processes necessary to build prototype materials and devices. Instruction focuses on how to conceive, design, and execute a materials development research plan, on developing competence in the fundamental laboratory and materials processing skills introduced in earlier course work, and on the preparation required for personal success in a team-based professional environment. Selected topics are covered in manufacturing, statistics, intellectual property, and ethics. Instruction and practice in oral and written communication provided. Limited to 25 due to space constraints.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"13:00","end":"14:00","room":"4-013"}]},{"type":"Lab","options":[{"days":["T","R"],"start":"14:00","end":"17:00","room":"4-131B"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.042","terms":["fall","spring"],"rating":6.48,"hours":11.36,"inClassHours":6.76,"outOfClassHours":4.6,"prerequisites":"3.030/3.033","corequisites":"","recommendedPreparation":""},{"code":"3.051","title":"Biomaterials Design and Development","level":"U","description":"Explores the molecular design, structure?property relationships, and performance of a comprehensive range of materials for biomedical applications. Covers metals/ceramics, polymers, protein- and peptide-based materials, natural biomaterials, and biohybrid systems. Emphasizes rational material selection and engineering design based on the chemical, mechanical, and biological requirements of tissues and specific medical applications. Topics include: emerging strategies for designing new materials, understanding material-tissue integration, host immune responses, immunomodulation, mechanobiology, and the development of stimuli-responsive and biomimetic strategies to improve material performance. Project-based, with students developing a biomaterial platform that addresses a critical health challenge. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"5-217"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.051","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"GIR:BIOL, GIR:CHEM","corequisites":"","recommendedPreparation":""},{"code":"3.063","title":"Polymer Physics","level":"U","description":"The mechanical, optical, electrical, and transport properties of polymers and other types of 'soft matter' are presented with respect to the underlying physics and physical chemistry of polymers and colloids in solution, and solid states. Topics include how enthalpy and entropy determine conformation, molecular dimensions and packing of polymer chains and colloids and supramolecular materials. Examination of the structure of glassy, crystalline, and rubbery elastic states of polymers; thermodynamics of solutions, blends, crystallization; liquid crystallinity, microphase separation, and self-assembled organic-inorganic nanocomposites. Case studies of relationships between structure and function in technologically important polymeric systems. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"66-160"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.063","terms":["fall"],"rating":6.1,"hours":11.75,"inClassHours":3.1,"outOfClassHours":8.65,"prerequisites":"3.010","corequisites":"","recommendedPreparation":""},{"code":"3.091","title":"Introduction to Solid-State Chemistry","level":"U","description":"Basic principles of chemistry and their application to engineering systems. The relationship between electronic structure, chemical bonding, and atomic order. Characterization of atomic arrangements in crystalline and amorphous solids: metals, ceramics, semiconductors, and polymers. Topical coverage of organic chemistry, solution chemistry, acid-base equilibria, electrochemistry, biochemistry, chemical kinetics, diffusion, and phase diagrams. Examples from industrial practice (including the environmental impact of chemical processes), from energy generation and storage (e.g., batteries and fuel cells), and from emerging technologies (e.g., photonic and biomedical devices).","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"11:00","end":"12:00","room":"10-250"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"09:00","end":"10:00","room":"13-1143"},{"days":["T","R"],"start":"09:00","end":"10:00","room":"13-4101"},{"days":["T","R"],"start":"09:00","end":"10:00","room":"13-5101"},{"days":["T","R"],"start":"10:00","end":"11:00","room":"13-1143"},{"days":["T","R"],"start":"10:00","end":"11:00","room":"13-3101"},{"days":["T","R"],"start":"10:00","end":"11:00","room":"13-4101"},{"days":["T","R"],"start":"10:00","end":"11:00","room":"13-5101"},{"days":["T","R"],"start":"10:00","end":"11:00","room":"2-142"},{"days":["T","R"],"start":"10:00","end":"11:00","room":"4-145"},{"days":["T","R"],"start":"10:00","end":"11:00","room":"24-112"},{"days":["T","R"],"start":"10:00","end":"11:00","room":"24-307"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"13-1143"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"13-3101"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"13-4101"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"13-5101"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"8-205"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"24-121"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"38-166"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"13-3101"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"13-4101"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"13-5101"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"2-132"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"13-1143"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"13-3101"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"13-4101"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"13-5101"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"8-119"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"26-142"},{"days":["T","R"],"start":"15:00","end":"16:00","room":"13-1143"},{"days":["T","R"],"start":"15:00","end":"16:00","room":"13-5101"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.091","terms":["fall","spring"],"rating":5.05,"hours":7.31,"inClassHours":4.12,"outOfClassHours":3.19,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"3.093","title":"Metalsmithing: Objects and Power","level":"U","description":"Introduces traditional metalsmithing techniques to students in a studio environment. Project-based coursework investigates metalsmithing through the convergent lenses of art, science, and spirituality. Focuses on hand-crafted metal objects as historical signifiers of cultural values, power, and protection. Techniques covered vary each term and may include construction and fabrication, copper electroforming, oxy-acetylene welding, chasing and repousse, embossing, hollowware, casting, and more. Supplemented by visiting artists and arts sector field trips. Field trips are mandatory but are local and occur during class time. Limited to 9 due to space and equipment constraints.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"10:00","end":"11:00","room":"4-006"}]},{"type":"Lab","options":[{"days":["T"],"start":"11:00","end":"13:00","room":"4-006"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.093","terms":["fall"],"rating":6.87,"hours":8.1,"inClassHours":6.43,"outOfClassHours":1.67,"prerequisites":"3.095/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"3.096","title":"Architectural Ironwork","level":"U","description":"Explores the use of iron in the built environment throughout history and the world, with an emphasis on traditional European and American design and connections to contemporary movements in art and architecture. Discusses influence of technology on design and fabrication, spanning both ancient and modern developments. Cultivates the ability to design iron in architecture and criticize ironwork as art. Includes laboratory exercises that teach a variety of basic and advanced iron-working techniques such as hand forging and CNC machining. The project-based curriculum begins with art criticism of Cambridge-area ironwork, progresses to practical studies of iron architectural elements, and finishes with creation of an architectural object of the student's design. Associated writing assignments for in-lab projects hone criticism and analysis skills. Limited to 6.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:00","room":"8-119"}]},{"type":"Lab","options":[{"days":["W"],"start":"14:00","end":"17:00","room":"4-006"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.096","terms":["fall"],"rating":6.87,"hours":8.19,"inClassHours":5.96,"outOfClassHours":2.23,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"3.098","title":"Ancient Engineering: Ceramic Technologies","level":"U","description":"Explores human interaction with ceramic materials over a considerable span of time, from 25,000 years ago to the 16th century AD. Through the lens of modern materials science combined with evidence from archaeological investigations, examines ancient ceramic materials — from containers to architecture to art — to better understand our close relationship with this important class of material culture. Examines ceramics structure, properties, and processing. Introduces archaeological perspectives and discusses how research into historical changes in ancient ceramic technologies has led to a deeper comprehension of past human behavior and societal development. Concludes by considering how studies of ancient technologies and techniques are leading modern materials scientists to engineer designs of modern ceramic materials, including glasses, concretes, and pigments. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"15:00","end":"16:00","room":"56-154"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.098","terms":["fall"],"rating":6.26,"hours":8.17,"inClassHours":2.95,"outOfClassHours":5.22,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"3.14","title":"Modern Physical Metallurgy","level":"U","description":"Focuses on the links between the processing, structure, and properties of metals and alloys. First, the physical bases for strength, stiffness, and ductility are discussed with reference to crystallography, defects, and microstructure. Second, phase transformations and microstructural evolution are studied in the context of alloy thermodynamics and kinetics. Together, these components comprise the modern paradigm for designing metallic microstructures for optimized properties. Concludes with a focus on processing-microstructure-property relationships in structural engineering alloys. Students taking the graduate version explore the subject in greater depth.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:30","end":"17:00","room":"4-261"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.14","terms":["fall"],"rating":6.15,"hours":8.66,"inClassHours":3.06,"outOfClassHours":5.6,"prerequisites":"3.013","corequisites":"3.030/''permission of instructor''","recommendedPreparation":""},{"code":"3.173","title":"Computing Fabrics","level":"U","description":"Highlights connections between industrialization, products, and advances in fibers and fabrics. Discusses the evolution of technologies in their path from basic scientific research to scaled production and global markets, with the ultimate objective of identifying and investigating the degrees of freedom that make fabrics such a powerful form of synthetic engineering and product expression. Topics explored, in part through interactions with industry speakers, include: fiber, yarn, textiles and fabric materials, structure-property relations, and practical demonstrations to anticipate future textile products. Students taking graduate version complete additional assignments. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"15:00","end":"17:00","room":"2-139"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.173","terms":["fall","spring"],"rating":4.33,"hours":15.46,"inClassHours":2.29,"outOfClassHours":13.17,"prerequisites":"3.013/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"3.201","title":"Introduction to DMSE","level":"G","description":"Introduces new DMSE graduate students to DMSE research groups and the departmental spaces available for research. Guides students in joining a research group. Registration limited to students enrolled in DMSE graduate programs.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"12:30","end":"14:00","room":"4-153"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.201","terms":["fall"],"rating":5.8,"hours":1.98,"inClassHours":1.75,"outOfClassHours":0.23,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"3.25","title":"Physical Chemistry of Materials","level":"G","description":"Covers the fundamental chemical and physical principles governing material behavior across atomic and macroscopic scales. Introduces the laws of thermodynamics, state functions, and Maxwell relations, along with phases, phase equilibria, and phase diagrams. Presents statistical mechanics as a framework for connecting atomic-scale phenomena to macroscopic properties. Includes chemical thermodynamics, chemical potentials, energy of mixing, and kinetic rate theory describing atomic-scale reaction processes.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"09:30","end":"11:00","room":"32-144"}]},{"type":"Recitation","options":[{"days":["R"],"start":"15:00","end":"16:00","room":"13-3101"},{"days":["F"],"start":"11:00","end":"12:00","room":"13-5101"},{"days":["F"],"start":"12:00","end":"13:00","room":"13-4101"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.25","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"3.26","title":"Structure of Materials","level":"G","description":"Covers qualitative and quantitative descriptors of atomic- and nanoscale structure in ordered and disordered materials. Introduces crystalline lattices and crystal notation, as well as the structure of glasses and amorphous solids. Examines defects, microstructure, and their influence on material properties. Includes structural concepts in soft matter, emphasizing molecular and macromolecular organization.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:30","room":"36-156"}]},{"type":"Recitation","options":[{"days":["W"],"start":"14:00","end":"15:00","room":"13-4101"},{"days":["W"],"start":"15:00","end":"16:00","room":"13-4101"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.26","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"3.27","title":"Quantum Mechanics","level":"G","description":"Covers the fundamental physics and solid-state principles governing the electronic structure and properties of materials. Introduces key concepts in quantum mechanics and their application to electronic structure in solids. Examines the relationship between electronic structure and material properties. Includes relevant mathematical concepts and tools used in solid-state physics of materials.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"32-144"}]},{"type":"Recitation","options":[{"days":["M"],"start":"16:00","end":"17:00","room":"66-168"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.27","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"3.373","title":"Computing Fabrics","level":"G","description":"Highlights connections between industrialization, products, and advances in fibers and fabrics. Discusses the evolution of technologies in their path from basic scientific research to scaled production and global markets, with the ultimate objective of identifying and investigating the degrees of freedom that make fabrics such a powerful form of synthetic engineering and product expression. Topics explored, in part through interactions with industry speakers, include: fiber, yarn, textiles and fabric materials, structure-property relations, and practical demonstrations to anticipate future textile products. Students taking graduate version complete additional assignments. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"15:00","end":"17:00","room":"2-139"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.373","terms":["fall","spring"],"rating":4.33,"hours":15.24,"inClassHours":2.22,"outOfClassHours":13.02,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"3.40","title":"Modern Physical Metallurgy","level":"G","description":"Focuses on the links between the processing, structure, and properties of metals and alloys. First, the physical bases for strength, stiffness, and ductility are discussed with reference to crystallography, defects, and microstructure. Second, phase transformations and microstructural evolution are studied in the context of alloy thermodynamics and kinetics. Together, these components comprise the modern paradigm for designing metallic microstructures for optimized properties. Concludes with a focus on processing-microstructure-property relationships in structural engineering alloys. Students taking the graduate version explore the subject in greater depth.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:30","end":"17:00","room":"4-261"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.40","terms":["fall"],"rating":6.15,"hours":8.66,"inClassHours":3.06,"outOfClassHours":5.6,"prerequisites":"(3.20, 3.22)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"3.41","title":"Colloids, Surfaces, Absorption, Capillarity, and Wetting Phenomena","level":"G","description":"Integrates elements of physics and chemistry toward the study of material surfaces. Begins with classical colloid phenomena and the interaction between surfaces in different media. Discusses the mechanisms of surface charge generation as well as how dispersion forces are created and controlled. Continues with exploration of chemical absorption processes and surface design of inorganic and organic materials. Includes examples in which such surface design can be used to control critical properties of materials in applications. Addresses lastly how liquids interact with solids as viewed by capillarity and wetting phenomena. Studies how materials are used in processes and applications that are intended to control liquids, and how the surface chemistry and structure of those materials makes such applications possible.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"2-131"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.41","terms":["fall"],"rating":6.22,"hours":7.46,"inClassHours":3.04,"outOfClassHours":4.42,"prerequisites":"3.20, 3.21","corequisites":"","recommendedPreparation":""},{"code":"3.43","title":"Integrated Microelectronic Devices","level":"G","description":"Covers physics of microelectronic semiconductor devices for integrated circuit applications. Topics include semiconductor fundamentals, p-n junction, metal-oxide semiconductor structure, metal-semiconductor junction, MOS field-effect transistor, and bipolar junction transistor.  Emphasizes physical understanding of device operation through energy band diagrams and short-channel MOSFET device design and modern device scaling. Familiarity with MATLAB recommended.","groups":[{"type":"Lecture","options":[{"days":["M","T","W","R"],"start":"10:00","end":"11:00","room":"36-153"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.43","terms":["fall"],"rating":6.64,"hours":13.96,"inClassHours":4.2,"outOfClassHours":9.76,"prerequisites":"3.42/6.2500","corequisites":"","recommendedPreparation":"Familiarity with MATLAB recommended."},{"code":"3.44","title":"Materials Processing for Micro- and Nano-Systems","level":"G","description":"Processing of bulk, thin film, and nanoscale materials for applications in electronic, magnetic, electromechanical, and photonic devices and microsystems. Topics include growth of bulk, thin-film, nanoscale single crystals via vapor and liquid phase processes; formation, patterning and processing of thin films, with an emphasis on relationships among processing, structure, and properties; and processing of systems of nanoscale materials. Examples from materials processing for applications in high-performance integrated electronic circuits, micro-/nano-electromechanical devices and systems and integrated sensors.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"1-150"}]}],"url":"http://student.mit.edu/catalog/m3a.html#3.44","terms":["fall"],"rating":5.3,"hours":6.57,"inClassHours":3.0,"outOfClassHours":3.57,"prerequisites":"3.20, 3.21","corequisites":"","recommendedPreparation":""},{"code":"3.63","title":"Biomaterials Design and Development","level":"G","description":"Explores the molecular design, structure-property relationships, and performance of a comprehensive range of materials for biomedical applications. Covers metals/ceramics, polymers, and protein- and peptide-based materials, natural biomaterials, and biohybrid systems. Emphasizes rational material selection and engineering design based on the chemical, mechanical, and biological requirements of tissues and specific medical applications. Topics include emerging strategies for designing new materials, understanding material-tissue integration, host immune responses, immunomodulaton, mechanobiology, and the development of stimuli-responsive and biomimetic strategies to improve material performance. Project-based, with students developing a biomaterial platform that addresses a critical health challenge. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"5-217"}]}],"url":"http://student.mit.edu/catalog/m3b.html#3.63","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"3.903","title":"Seminar in Polymers and Soft Matter","level":"G","description":"A series of seminars covering a broad spectrum of topics in polymer science and engineering, featuring both on- and off-campus speakers.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"17:00","room":"56-114"}]}],"url":"http://student.mit.edu/catalog/m3b.html#3.903","terms":["fall","spring"],"rating":6.16,"hours":1.23,"inClassHours":1.1,"outOfClassHours":0.13,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"3.942","title":"Polymer Physics","level":"G","description":"The mechanical, optical, electrical, and transport properties of polymers and other types of 'soft matter' are presented with respect to the underlying physics and physical chemistry of polymers and colloids in solution, and solid states. Topics include how enthalpy and entropy determine conformation, molecular dimensions and packing of polymer chains and colloids and supramolecular materials. Examination of the structure of glassy, crystalline, and rubbery elastic states of polymers; thermodynamics of solutions, blends, crystallization; liquid crystallinity, microphase separation, and self-assembled organic-inorganic nanocomposites. Case studies of relationships between structure and function in technologically important polymeric systems. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"66-160"}]}],"url":"http://student.mit.edu/catalog/m3b.html#3.942","terms":["fall"],"rating":6.06,"hours":11.98,"inClassHours":3.11,"outOfClassHours":8.87,"prerequisites":"3.013/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"3.984","title":"Materials in Ancient Societies I","level":"G","description":"Seminars and labs provide in-depth study of the technologies ancient societies used to produce objects from raw materials. Seminars cover basic materials science and engineering concepts and techniques that can be used to understand how materials were produced and used in the past. The materials selection and processing are then linked to the environment, exchange, political power, and cultural values. The specific material covered each year rotates and may include ceramics, metals, stone, glass, or bones/organic materials. Contact the instructor for more information about the material covered each year.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"11:00","end":"14:00","room":"4-265"}]}],"url":"http://student.mit.edu/catalog/m3b.html#3.984","terms":["fall"],"rating":6.89,"hours":9.84,"inClassHours":7.0,"outOfClassHours":2.84,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"3.986","title":"The Human Past: Introduction to Archaeology","level":"U","description":"From an archaeological perspective, examines ancient human activities and the forces that shaped them. Draws on case studies from the Old and/or New World. Exposes students to various classes of archaeological data, such as stone, bone, and ceramics, that help reconstruct the past.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:00","room":"4-231"}]},{"type":"Recitation","options":[{"days":["T"],"start":"16:00","end":"17:00","room":"4-261"},{"days":["R"],"start":"16:00","end":"17:00","room":"4-261"}]}],"url":"http://student.mit.edu/catalog/m3b.html#3.986","terms":["fall"],"rating":6.59,"hours":6.8,"inClassHours":3.03,"outOfClassHours":3.77,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"3.991","title":"Ancient Engineering: Ceramic Technologies","level":"G","description":"Explores human interaction with ceramic materials over a considerable span of time, from 25,000 years ago to the 16th century AD. Through the lens of modern materials science combined with evidence from archaeological investigations, examines ancient ceramic materials — from containers to architecture to art — to better understand our close relationship with this important class of material culture. Examines ceramics structure, properties, and processing. Introduces archaeological perspectives and discusses how research into historical changes in ancient ceramic technologies has led to a deeper comprehension of past human behavior and societal development. Concludes by considering how studies of ancient technologies and techniques are leading modern materials scientists to engineer designs of modern ceramic materials, including glasses, concretes, and pigments. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"15:00","end":"16:00","room":"56-154"}]}],"url":"http://student.mit.edu/catalog/m3b.html#3.991","terms":["fall"],"rating":6.26,"hours":8.17,"inClassHours":2.95,"outOfClassHours":5.22,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"3.C27","title":"Computational Imaging: Physics and Algorithms","level":"U","description":"Explores the contemporary computational understanding of imaging: encoding information about a physical object onto a form of radiation, transferring the radiation through an imaging system, converting it to a digital signal, and computationally decoding and presenting the information to the user. Introduces a unified formulation of computational imaging systems as a three-round 'learning spiral': the first two rounds describe the physical and algorithmic parts in two exemplary imaging systems. The third round involves a class project on an imaging system chosen by students. Undergraduate and graduate versions share lectures but have different recitations. Involves optional 'clinics' to even out background knowledge of linear algebra, optimization, and computational imaging-related programming best practices for students of diverse disciplinary backgrounds. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"24-121"}]}],"url":"http://student.mit.edu/catalog/m3b.html#3.C27","terms":["fall"],"rating":6.43,"hours":12.4,"inClassHours":3.14,"outOfClassHours":9.26,"prerequisites":"18.C06, (1.00/1.000/2.086/3.019/6.100A)","corequisites":"","recommendedPreparation":"Involves optional 'clinics' to even out background knowledge of linear algebra, optimization, and computational imaging-related programming best practices for students of diverse disciplinary backgrounds."},{"code":"3.C67","title":"Computational Imaging: Physics and Algorithms","level":"G","description":"Contemporary understanding of imaging is computational: encoding onto a form of radiation the information about a physical object, transferring the radiation through the imaging system, converting it to a digital signal, and computationally decoding and presenting the information to the user. This class introduces a unified formulation of computational imaging systems as a three-round 'learning spiral': the first two rounds, instructors describe the physical and algorithmic parts in two exemplary imaging systems. The third round, students conduct themselves as the class project on an imaging system of their choice. The undergraduate and graduate versions share lectures but have different recitations. Throughout the term, we also conduct optional 'clinics' to even out background knowledge of linear algebra, optimization, and computational imaging-related programming best practices for students of diverse disciplinary backgrounds.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"24-121"}]}],"url":"http://student.mit.edu/catalog/m3b.html#3.C67","terms":["fall"],"rating":6.43,"hours":12.4,"inClassHours":3.14,"outOfClassHours":9.26,"prerequisites":"18.C06, (1.00/1.000/2.086/3.019/6.100A)","corequisites":"","recommendedPreparation":"Throughout the term, we also conduct optional 'clinics' to even out background knowledge of linear algebra, optimization, and computational imaging-related programming best practices for students of diverse disciplinary backgrounds."},{"code":"3.EPE","title":"UPOP Engineering Practice Experience","level":"U","description":"Provides students with skills to prepare for and excel in the world of industry. Emphasizes practical application of career theory and professional development concepts. Introduces students to relevant and timely resources for career development, provides students with tools to embark on a successful internship search, and offers networking opportunities with employers and MIT alumni. Students work in groups, led by industry mentors, to improve their resumes and cover letters, interviewing skills, networking abilities, project management, and ability to give and receive feedback. Objective is for students to be able to adapt and contribute effectively to their future employment organizations. A total of two units of credit is awarded for completion of the fall and subsequent spring term offerings. Application required; consult UPOP website for more information.","groups":[{"type":"Lab","options":[{"days":["M"],"start":"13:00","end":"14:00","room":"3-270"},{"days":["M"],"start":"15:00","end":"16:00","room":"4-237"},{"days":["T"],"start":"13:00","end":"14:00","room":"4-149"},{"days":["T"],"start":"15:00","end":"16:00","room":"3-370"},{"days":["F"],"start":"11:00","end":"12:00","room":"1-390"},{"days":["F"],"start":"13:00","end":"14:00","room":"1-190"}]}],"url":"http://student.mit.edu/catalog/m3b.html#3.EPE","terms":["fall","spring"],"rating":5.75,"hours":1.75,"inClassHours":1.0,"outOfClassHours":0.75,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"3.S08","title":"Special Subject in Materials Science and Engineering","level":"U","description":"Lecture, seminar, or laboratory consisting of material not offered in regularly scheduled subjects. Can be repeated for credit only for completely different subject matter.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"15:00","room":"6-104"}]}],"url":"http://student.mit.edu/catalog/m3b.html#3.S08","terms":["fall","spring"],"rating":5.7,"hours":1.66,"inClassHours":1.33,"outOfClassHours":0.33,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"3.S73","title":"Special Subject in Materials Science and Engineering","level":"G","description":"Covers advanced topics in Materials Science and Engineering that are not included in the permanent curriculum.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"15:00","end":"17:00","room":"VIRTUAL"}]}],"url":"http://student.mit.edu/catalog/m3b.html#3.S70-3.S75","terms":["fall"],"rating":6.0,"hours":6.5,"inClassHours":2.5,"outOfClassHours":4.0,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.021","title":"Design Studio: How to Design","level":"U","description":"Introduces fundamental design principles as a way to demystify design and provide a basic introduction to all aspects of the process. Stimulates creativity, abstract thinking, representation, iteration, and design development. Equips students with skills to have more effective communication with designers, and develops their ability to apply the foundations of design to any discipline. Limited to 25; preference to Course 4 and 4B majors and Design and Architecture minors, and first- and second-year students.","groups":[{"type":"Design","options":[{"days":["M","W"],"start":"14:00","end":"17:00","room":"W41-3219"}]}],"url":"http://student.mit.edu/catalog/m4a.html#4.021","terms":["fall","spring"],"rating":5.69,"hours":10.95,"inClassHours":6.18,"outOfClassHours":4.77,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.023","title":"Architecture Design Studio I","level":"U","description":"Provides instruction in architectural design and project development within design constraints including architectural program and site. Students engage the design process through various 2-dimensional and 3-dimensional media. Working directly with representational and model making techniques, students gain experience in the conceptual, formal, spatial and material aspects of architecture. Instruction and practice in oral and written communication provided. Preference to Course 4 majors and minors.","groups":[{"type":"Design","options":[{"days":["T","R","F"],"start":"13:00","end":"17:00","room":"W41-3219"}]}],"url":"http://student.mit.edu/catalog/m4a.html#4.023","terms":["fall"],"rating":6.14,"hours":27.88,"inClassHours":11.74,"outOfClassHours":16.14,"prerequisites":"4.022","corequisites":"","recommendedPreparation":""},{"code":"4.031","title":"Design Studio: Objects and Interaction","level":"U","description":"Overview of design as the giving of form, order, and interactivity to the objects that define our daily life. Follows the path from project to interactive product. Covers the overall design process, preparing students for work in a hands-on studio learning environment. Emphasizes design development and constraints. Topics include the analysis of objects; interaction design and user experience; design methodologies, current dialogues in design; economies of scale vs. means; and the role of technology in design. Provides a foundation in prototyping skills such as carpentry, casting, digital fabrication, electronics, and coding. Limited to 15; preference to Course 4-B majors and Design Minors.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"17:00","room":"W41-3509"}]},{"type":"Recitation","options":[{"days":["F"],"start":"14:00","end":"17:00","room":"W41-3509"}]}],"url":"http://student.mit.edu/catalog/m4a.html#4.031","terms":["fall"],"rating":5.79,"hours":16.44,"inClassHours":5.1,"outOfClassHours":11.34,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.053","title":"Visual Communication Fundamentals","level":"U","description":"Provides an introduction to visual communication, emphasizing the development of a visual and verbal vocabulary. Presents the fundamentals of line, shape, color, composition, visual hierarchy, word/image relationships and typography as building blocks for communicating with clarity, emotion, and meaning. Students develop their ability to analyze, discuss and critique their work and the work of the designed world.  Limited to 18; preference to Course 4-B majors and Design minors.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"10:00","end":"13:00","room":"W41-3509"}]},{"type":"Recitation","options":[{"days":["R"],"start":"14:00","end":"17:00","room":"W41-3509"}]}],"url":"http://student.mit.edu/catalog/m4a.html#4.053","terms":["fall"],"rating":6.4,"hours":11.53,"inClassHours":6.16,"outOfClassHours":5.37,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.105","title":"Fundamentals of Computation Design and Fabrication","level":"G","description":"Introduction to cultures of form in architectural design, representation, and production, including material cultures, geometric discourse and analysis, Western and non-Western modes of perception and representation. Through a series of acts of forming and making, provides a primer and venue to rehearse skills such as 3D modeling and the reciprocity between representation and materialization. Exercises accompanied by lectures from practitioners, who each represent a highly articulated relationship between form and material in a body of design research or built work. Restricted to first-year MArch students.","groups":[{"type":"Design","options":[{"days":["T"],"start":"09:00","end":"12:00","room":"W41-1402"}]}],"url":"http://student.mit.edu/catalog/m4a.html#4.105","terms":["fall"],"rating":5.13,"hours":9.4,"inClassHours":3.2,"outOfClassHours":6.2,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.130","title":"Architectural Design Theory and Methodologies","level":"G","description":"Studies design as an interrogative technique to examine material sciences, media arts and technology, cultural studies, computation and emerging fabrication protocols. Provides in-depth, theoretical grounding to the notion of 'design' in architecture, and to the consideration of contemporary design methodologies, while encouraging speculation on emerging design thinking. Topical focus varies with instructor. May be repeated for credit with permission of department.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"09:00","end":"12:00","room":"W41-1119"}]}],"url":"http://student.mit.edu/catalog/m4a.html#4.130","terms":["fall"],"rating":6.27,"hours":8.44,"inClassHours":2.99,"outOfClassHours":5.45,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.140","title":"How to Make (Almost) Anything","level":"G","description":"Provides a practical hands-on introduction to digital fabrication, including CAD/CAM/CAE, NC machining, 3-D printing and scanning, molding and casting, composites, laser and waterjet cutting, PCB design and fabrication; sensors and actuators; mixed-signal instrumentation, embedded processing, and wired and wireless communications. Develops an understanding of these capabilities through projects using them individually and jointly to create functional systems.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"16:00","room":"E14-633"}]},{"type":"Recitation","options":[{"days":["R"],"start":"17:00","end":"19:00","room":"E14-633"}]}],"url":"http://student.mit.edu/catalog/m4a.html#4.140","terms":["fall"],"rating":6.52,"hours":22.18,"inClassHours":4.96,"outOfClassHours":17.22,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.151","title":"Architecture Design Core Studio I","level":"G","description":"Explores the foundations of design through a series of bracketed methods of production. These methods exercise topics such as form, space, organization, structure, circulation, use, tectonics, temporality, and experience. Students develop methods of representation that span from manual to virtual and from canonical to experimental. Each method is evaluated for what it offers and privileges, supplying a survey of approaches for design exercises to follow. First in a sequence of design subjects, which must be taken in order. Limited to first-year MArch students.","groups":[{"type":"Design","options":[{"days":["T","R","F"],"start":"13:00","end":"17:00","room":"W41-4319"}]}],"url":"http://student.mit.edu/catalog/m4a.html#4.151","terms":["fall"],"rating":5.75,"hours":38.4,"inClassHours":10.76,"outOfClassHours":27.64,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.153","title":"Architecture Design Core Studio III","level":"G","description":"Interdisciplinary approach to design through studio design problems that engage the domains of building technology, computation, and the cultural/historical geographies of energy. Uses different modalities of thought to examine architectural agendas for 'sustainability'; students position their work with respect to a broader understanding of the environment and its relationship to society and technology. Students develop a project with a comprehensive approach to programmatic organization, energy load considerations, building material assemblies, exterior envelope and structure systems. Limited to second-year MArch students.","groups":[{"type":"Design","options":[{"days":["T","R","F"],"start":"13:00","end":"17:00","room":"W41-4419"}]}],"url":"http://student.mit.edu/catalog/m4a.html#4.153","terms":["fall"],"rating":4.88,"hours":34.49,"inClassHours":12.33,"outOfClassHours":22.16,"prerequisites":"4.152","corequisites":"","recommendedPreparation":""},{"code":"4.154","title":"Architecture Design Option Studio","level":"G","description":"Offers a broad range of advanced-level investigations in architectural design in various contexts, including international sites. Integrates theoretical and technological discourses into specific topics. Studio problems may include urbanism and city scale strategies, habitation and urban housing systems, architecture in landscapes, material investigations and new production technologies, programmatic and spatial complex building typologies, and research centered studies. Mandatory lottery process.","groups":[{"type":"Design","options":[{"days":["T","R","F"],"start":"13:00","end":"17:00","room":"W41-4419"}]}],"url":"http://student.mit.edu/catalog/m4a.html#4.154","terms":["fall","spring"],"rating":5.6,"hours":22.5,"inClassHours":7.56,"outOfClassHours":14.94,"prerequisites":"4.153","corequisites":"","recommendedPreparation":""},{"code":"4.163","title":"Urban Design Studio","level":"G","description":"The design of urban environments. Strategies for change in large areas of cities, to be developed over time, involving different actors. Fitting forms into natural, man-made, historical, and cultural contexts; enabling desirable activity patterns; conceptualizing built form; providing infrastructure and service systems; guiding the sensory character of development. Involves architecture and planning students in joint work; requires individual designs or design and planning guidelines.","groups":[{"type":"Design","options":[{"days":["T","F"],"start":"13:00","end":"17:00","room":"W41-4419"}]}],"url":"http://student.mit.edu/catalog/m4a.html#4.163","terms":["fall"],"rating":3.8,"hours":22.3,"inClassHours":8.14,"outOfClassHours":14.16,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.181","title":"Architectural Design Workshop","level":"G","description":"Addresses design inquiry in a studio format. In-depth consideration of selected issues of the built world. The problem may be prototypical or a particular aspect of a whole project, but is always interdisciplinary in nature.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"W41-4101"}]}],"url":"http://student.mit.edu/catalog/m4a.html#4.181","terms":["fall"],"rating":6.14,"hours":9.42,"inClassHours":3.14,"outOfClassHours":6.28,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.210","title":"Positions: Cultivating Critical Practice","level":"G","description":"Through formal analysis and discussion of historical and theoretical texts, seminar produces a map of contemporary architectural practice. Examines six pairs of themes in terms of their recent history: city and global economy, urban plan and map of operations, program and performance, drawing and scripting, image and surface, and utopia and projection. Restricted to year-one MArch students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"W41-1101"}]}],"url":"http://student.mit.edu/catalog/m4b.html#4.210","terms":["fall"],"rating":6.49,"hours":8.61,"inClassHours":3.19,"outOfClassHours":5.42,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.215","title":"Sensing Place: Photography as Inquiry","level":"G","description":"Explores photography as a disciplined way of seeing, and as a medium of inquiry and of expressing ideas. Readings, observations, and photographs form the basis of discussions on landscape, light, significant detail, place, poetics, narrative, and how photography can inform research, design and planning, among other issues. Recommended for students who want to employ visual methods in their theses.  Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"17:00","room":"W41-1303"}]}],"url":"http://student.mit.edu/catalog/m4b.html#4.215","terms":["fall"],"rating":6.15,"hours":8.38,"inClassHours":3.09,"outOfClassHours":5.29,"prerequisites":"","corequisites":"","recommendedPreparation":"Recommended for students who want to employ visual methods in their theses."},{"code":"4.221","title":"Architecture Studies Colloquium","level":"G","description":"Aims to create a discourse across the various SMArchS discipline groups that reflects current Institute-wide initiatives; introduce SMarchS students to the distinct perspective of the different SMarchS discipline groups; and provide a forum for debate and discussion in which the SMarchS cohort can explore, develop and share ideas. Engages with interdisciplinary thinking, research, and innovation that is characteristic of MIT's culture and can form a basis for their future work. Limited to first-year SMArchS students.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:00","end":"11:00","room":"W41-3511"}]}],"url":"http://student.mit.edu/catalog/m4b.html#4.221","terms":["fall"],"rating":5.7,"hours":3.32,"inClassHours":2.29,"outOfClassHours":1.03,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.222","title":"Professional Practice","level":"G","description":"Gives a critical orientation towards a career in architectural practice. Uses historical and current examples to illustrate the legal, ethical and management concepts underlying the practice of architecture. Emphasis on facilitating design excellence and strengthening connections between the profession and academia. Restricted to MArch students.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"09:00","end":"12:00","room":"W41-1305"}]}],"url":"http://student.mit.edu/catalog/m4b.html#4.222","terms":["fall"],"rating":4.8,"hours":5.22,"inClassHours":3.06,"outOfClassHours":2.16,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.228","title":"Urbanism Proseminar: Theory and Representation","level":"G","description":"Critical introduction to key contemporary positions in urbanism to the ends of researching, representing, and designing territories that respond to the challenges of the 21st century. Provides an overview of contemporary urban issues, situates them in relation to a genealogy of urban precedents, and constructs a theoretical framework that engages the allied fields of architecture, landscape architecture, political ecology, geography, territorial planning, and environmental humanities. Comprised of three sections, first section articulates a framework on the urban as both process and form, shifting the emphasis from city to territory. Second section engages a series of related urban debates, such as density/sprawl, growth/shrinkage, and codes/exception. Third section calls upon urban agency in the age of environment through the object of infrastructures of trash, water, oil, and food. Limited to 12.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"17:30","room":"W41-1101"}]}],"url":"http://student.mit.edu/catalog/m4b.html#4.228","terms":["fall"],"rating":6.3,"hours":14.58,"inClassHours":3.08,"outOfClassHours":11.5,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.238","title":"The Role of History in Planning the Just City","level":"G","description":"Explores a series of diverse urban landscapes as public history, with a focus on cases of African-American landscapes and landscapes of other racial or ethnic minorities and the stories they hold. To deepen an understanding and discussion of these cases, an author/leader of each case joins the class session. Topics include: the relationship between history and memory; as well as how overlooked or silenced histories can be unearthed, honored, and told through urban design and planning.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"W41-4214"}]}],"url":"http://student.mit.edu/catalog/m4b.html#4.238","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.240","title":"Urban Design Skills: Observing, Interpreting, and Representing the City","level":"G","description":"Introduces methods for observing, interpreting, and representing the urban environment. Students draw on their senses and develop their ability to deduce, question, and test conclusions about how the built environment is designed, used, and valued. The interrelationship of built form, circulation networks, open space, and natural systems are a key focus. Supplements existing classes that cover theory and history of city design and urban planning and prepares students without design backgrounds with the fundamentals of physical planning. Intended as a foundation for 11.329.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"09:00","end":"13:00","room":"W41-3102"}]},{"type":"Recitation","options":[{"days":["W"],"start":"17:00","end":"19:30","room":"W41-3102"}]}],"url":"http://student.mit.edu/catalog/m4b.html#4.240","terms":["fall"],"rating":5.7,"hours":15.38,"inClassHours":6.76,"outOfClassHours":8.62,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.248","title":"Advanced Urban Design Skills: Observing, Interpreting, and Representing the City","level":"G","description":"Through a studio-based course in planning and urban design, builds on the foundation acquired in 11.328 to engage in creative exploration of how design contributes to resilient, just, and vibrant urban places. Through the planning and design of two projects, students creatively explore spatial ideas and utilize various digital techniques to communicate their design concepts, giving form to strategic thinking. Develops approaches and techniques to evaluate the plural structure of the built environment and offer propositions that address policies and regulations as well as the values, behaviors, and wishes of the different users.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"09:00","end":"13:00","room":"W41-3102"}]},{"type":"Recitation","options":[{"days":["W"],"start":"17:00","end":"19:30","room":"W41-3102"}]}],"url":"http://student.mit.edu/catalog/m4b.html#4.248","terms":["fall"],"rating":6.1,"hours":15.37,"inClassHours":6.81,"outOfClassHours":8.56,"prerequisites":"11.328/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.250","title":"Introduction to Urban Design and Development","level":"U","description":"Examines the evolving structure of cities and the way that cities, suburbs, and metropolitan areas can be designed and developed. Surveys the ideas of a wide range of people who have addressed urban problems. Stresses the connection between values and design. Demonstrates how physical, social, political and economic forces interact to shape and reshape cities over time. Introduces links between urban design and urban science.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"W41-3102"}]}],"url":"http://student.mit.edu/catalog/m4b.html#4.250","terms":["fall","spring"],"rating":5.93,"hours":6.77,"inClassHours":3.05,"outOfClassHours":3.72,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.275","title":"Advanced Urbanism Colloquium","level":"G","description":"Introduces critical theories and contemporary practices in the field of urbanism that challenge its paradigms and advance its future. Includes theoretical linkages between ideas about the cultures of urbanization, social and political processes of development, environmental tradeoffs of city making, and the potential of design disciplines to intervene to change the future of built forms. Events and lecture series co-organized by faculty and doctoral students further engage and inform research. Preference to doctoral students in the Advanced Urbanism concentration.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"12:00","end":"13:30","room":"W41-4101"}]}],"url":"http://student.mit.edu/catalog/m4b.html#4.275","terms":["fall","spring"],"rating":6.79,"hours":4.29,"inClassHours":2.08,"outOfClassHours":2.21,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.301","title":"Introduction to Artistic Experimentation","level":"U","description":"Introduces artistic practice and critical visual thinking through three studio-based projects using different scales and media, for instance, 'Body Extension,' 'Shaping Time,' 'Public Making,' and/or 'Networked Cultures.' Each project concludes with a final presentation and critique. Students explore sculptural, architectural, performative artistic methods; video and sound art; site interventions and strategies for artistic engagement in the public realm. Lectures, screenings, guest presentations, field trips, readings, and debates supplement studio practice. Also introduces students to the historic, cultural, and environmental forces affecting both the development of an artistic vision and the reception of a work of art. Lab fee required. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["T","W"],"start":"09:30","end":"12:30","room":"E15-235"}]}],"url":"http://student.mit.edu/catalog/m4c.html#4.301","terms":["fall"],"rating":6.49,"hours":9.52,"inClassHours":5.95,"outOfClassHours":3.57,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.314","title":"Advanced Workshop in Artistic Practice and Transdisciplinary Research","level":"U","description":"Examines artistic practice as a form of critical inquiry and knowledge production. Offers opportunity to develop art as a means for addressing the social, cultural, and ecological consequences of technology, to build bridges between industry and culture, and to challenge the boundaries between public and private, and human and non-human. Provides instruction in evaluating models of experimentation, individual research, and collaboration with other disciplines in the arts, culture, science, and technology. Supports the development of individual and collective artistic research projects. Additional work required of students taking the graduate version. Lab fee required. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"12:30","room":"E15-207"}]}],"url":"http://student.mit.edu/catalog/m4c.html#4.314","terms":["fall"],"rating":5.37,"hours":11.17,"inClassHours":5.49,"outOfClassHours":5.68,"prerequisites":"4.301/4.302/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.315","title":"Advanced Workshop in Artistic Practice and Transdisciplinary Research","level":"G","description":"Examines artistic practice as a form of critical inquiry and knowledge production. Offers opportunity to develop art as a means for addressing the social, cultural, and ecological consequences of technology, to build bridges between industry and culture, and to challenge the boundaries between public and private, and human and non-human. Provides instruction in evaluating models of experimentation, individual research, and collaboration with other disciplines in the arts, culture, science, and technology. Supports the development of individual and collective artistic research projects. Additional work required of students taking the graduate version. Lab fee required. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"12:30","room":"E15-207"}]}],"url":"http://student.mit.edu/catalog/m4c.html#4.315","terms":["fall"],"rating":5.37,"hours":11.17,"inClassHours":5.49,"outOfClassHours":5.68,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.324","title":"Artist, Architect, Tinkerer, Engineer: How to Collaborate Across Disciplines","level":"U","description":"Seminar connecting the arts and sciences by exploring methodological similarities and differences across the arts, architecture, engineering, and social sciences. Through targeted reading and exercises, each student develops a collaborative project that engages directly with another discipline. Projects are iterated over the course of the term. Readings, visitors, and lectures expose students to a wide range of practitioners across different fields. Students interrogate the underlying methodologies that unite and separate their disciplines. Presents best-practice models for cultivating collaboration through the use of case studies. Additional work required of students taking the graduate version. Lab fee required. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"E15-207"}]}],"url":"http://student.mit.edu/catalog/m4c.html#4.324","terms":["fall"],"rating":5.53,"hours":9.07,"inClassHours":3.2,"outOfClassHours":5.87,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.325","title":"Artist, Architect, Tinkerer, Engineer: How to Collaborate Across Disciplines","level":"G","description":"Seminar connecting the arts and sciences by exploring methodological similarities and differences across the arts, architecture, engineering, and social sciences. Through targeted reading and exercises, each student develops a collaborative project that engages directly with another discipline. Projects are iterated over the course of the term. Readings, visitors, and lectures expose students to a wide range of practitioners across different fields. Students interrogate the underlying methodologies that unite and separate their disciplines. Presents best-practice models for cultivating collaboration through the use of case studies. Additional work required of students taking the graduate version. Lab fee required. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"E15-207"}]}],"url":"http://student.mit.edu/catalog/m4c.html#4.325","terms":["fall"],"rating":5.53,"hours":9.07,"inClassHours":3.2,"outOfClassHours":5.87,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.341","title":"Introduction to Photography and Related Media","level":"U","description":"Introduces history and contemporary practices in artistic photography through projects, lectures, artist visits, group discussions, readings, and field trips. Fosters visual literacy and aesthetic appreciation of photography/digital imaging, as well as critical awareness of how images in our culture are produced and constructed. Provides instruction in the fundamentals of different camera formats, film exposure and development, lighting, black and white darkroom printing, and digital imaging. Assignments allow for incorporation of a range of traditional and experimental techniques, development of technical skills, and personal exploration. Throughout the term, present and discuss projects in a critical forum. Additional work required of students taking the graduate version. Lab fee required. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"17:00","room":"E15-054"},{"days":["T","R"],"start":"09:30","end":"12:30","room":"E15-054"}]}],"url":"http://student.mit.edu/catalog/m4c.html#4.341","terms":["fall","spring"],"rating":6.48,"hours":11.11,"inClassHours":5.97,"outOfClassHours":5.14,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.342","title":"Introduction to Photography and Related Media","level":"G","description":"Introduces history and contemporary practices in artistic photography through projects, lectures, artist visits, group discussions, readings, and field trips. Fosters visual literacy and aesthetic appreciation of photography/digital imaging, as well as critical awareness of how images in our culture are produced and constructed. Provides instruction in the fundamentals of different camera formats, film exposure and development, lighting, black and white darkroom printing, and digital imaging. Assignments allow for incorporation of a range of traditional and experimental techniques, development of technical skills, and personal exploration. Throughout the term, present and discuss projects in a critical forum. Additional work required of students taking the graduate version. Lab fee required. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"17:00","room":"E15-054"},{"days":["T","R"],"start":"09:30","end":"12:30","room":"E15-054"}]}],"url":"http://student.mit.edu/catalog/m4c.html#4.342","terms":["fall","spring"],"rating":6.48,"hours":11.11,"inClassHours":5.97,"outOfClassHours":5.14,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.354","title":"Introduction to Video and Related Media","level":"U","description":"Examines the technical and conceptual variables and strategies inherent in contemporary video art practice. Analyzes structural concepts of time, space, perspective, and sound within the art form. Building upon the historical legacy of the moving the image, students render self-exploration, performance, social critique, and manipulation of raw experience into an aesthetic form. Emphasizes practical knowledge of lighting, video capturing and editing, and montage. Presentation and critique of student work, technical workshops, screenings, and reading discussions assist students with final project. Additional work required of students taking the graduate version. Lab fee required.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"12:30","room":"E15-070"}]}],"url":"http://student.mit.edu/catalog/m4c.html#4.354","terms":["fall"],"rating":6.57,"hours":11.81,"inClassHours":6.34,"outOfClassHours":5.47,"prerequisites":"","corequisites":"","recommendedPreparation":"Emphasizes practical knowledge of lighting, video capturing and editing, and montage."},{"code":"4.355","title":"Introduction to Video and Related Media","level":"G","description":"Examines the technical and conceptual variables and strategies inherent in contemporary video art practice. Analyzes structural concepts of time, space, perspective, and sound within the art form. Building upon the historical legacy of film and other time-based image media, students render self-exploration, performance, social critique, and manipulation of raw experience into an aesthetic form. Emphasizes practical knowledge of lighting, video capturing and editing, and montage. Includes presentation and critique of student work, technical workshops, screenings, and readings with the objective of a final creative project. Additional work required of students taking the graduate version. Lab fee required.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"12:30","room":"E15-070"}]}],"url":"http://student.mit.edu/catalog/m4c.html#4.355","terms":["fall"],"rating":6.57,"hours":11.81,"inClassHours":6.34,"outOfClassHours":5.47,"prerequisites":"","corequisites":"","recommendedPreparation":"Emphasizes practical knowledge of lighting, video capturing and editing, and montage."},{"code":"4.359","title":"Synchronizations of Senses","level":"G","description":"Focused on the practices of varied practitioners — film directors, artists, musicians, composers, architects, designers — whose writings relay a process of thinking and feeling integral to their forms of material production. Testing various ways aesthetic forms and their shifts — historic and contemporary — have relations to still emerging contemporary subjectivities (felt emotion in a human body), the class studies productions created by participants and case studies of varied producers, and generates new work individually and/or collaboratively via diverse media explorations. Includes reading, writing, drawing, and publishing, as well as photographic, cinematic, spatial, and audio operations and productions. Activities include screenings, listening assignments, and guest visits, in addition to readings, discussions, and presentations. Lab fee required. Limited to 12.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"09:30","end":"12:30","room":"E15-207"}]}],"url":"http://student.mit.edu/catalog/m4c.html#4.359","terms":["fall"],"rating":6.05,"hours":7.27,"inClassHours":3.08,"outOfClassHours":4.19,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.390","title":"Art, Culture, and Technology Studio and Thesis Colloquium","level":"G","description":"Explores the theory and criticism of intersections between art, culture, and technology in relation to contemporary artistic practice, critical design, and media. Students consider methods of investigation, documentation, and display and explore modes of communication. Students develop projects in which they organize research goals, engage in production, cultivate a context for practice, and explore how to communicate, display, and document work, with artistic practice as a method of critical inquiry/knowledge dissemination. Regular presentation and peer-critiques, reviews with ACT faculty and fellows, and external guest reviewers provide feedback as projects develop. Simultaneously, students prepare for thesis through both foundational texts in contemporary theory and criticism and artist writings, alongside presentations and discussions on methodological perspectives required of interdisciplinary approaches. Restricted to SMACT students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"E15-001"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"12:00","room":"E15-001"}]}],"url":"http://student.mit.edu/catalog/m4c.html#4.390","terms":["fall","spring"],"rating":4.72,"hours":17.0,"inClassHours":3.37,"outOfClassHours":13.63,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.401","title":"Environmental Technologies in Buildings","level":"U","description":"Introduction to the study of the thermal and luminous behavior of buildings. Examines the basic scientific principles underlying these phenomena and introduces students to a range of technologies and analysis techniques for designing comfortable indoor environments. Challenges students to apply these techniques and explore the role energy and light can play in shaping architecture. Additional work required of students taking the graduate version.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"3-133"}]},{"type":"Lab","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"W41-1119"}]}],"url":"http://student.mit.edu/catalog/m4d.html#4.401","terms":["fall"],"rating":6.23,"hours":11.88,"inClassHours":4.91,"outOfClassHours":6.97,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.450","title":"Computational Structural Design and Optimization","level":"G","description":"Research seminar focusing on emerging applications of computation for creative, early-stage structural design and optimization for architecture. Incorporates computational design fundamentals, including problem parameterization and formulation; design space exploration strategies, including interactive, heuristic, and gradient-based optimization; and computational structural analysis methods, including the finite element method, graphic statics, and approximation techniques. Programing experience and familiarity with structural mechanics necessary. Additional work required of students taking graduate version. Limited to 25 total for versions meeting together.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"17:00","room":"W41-1216"}]}],"url":"http://student.mit.edu/catalog/m4d.html#4.450","terms":["fall"],"rating":6.41,"hours":13.65,"inClassHours":3.0,"outOfClassHours":10.65,"prerequisites":"((1.000/(6.100A, 6.100B)), (1.050/2.001/4.462))/''permission of instructor''","corequisites":"","recommendedPreparation":"Programing experience and familiarity with structural mechanics necessary."},{"code":"4.451","title":"Computational Structural Design and Optimization","level":"U","description":"Research seminar focusing on emerging applications of computation for creative, early-stage structural design and optimization for architecture. Incorporates computational design fundamentals, including problem parameterization and formulation; design space exploration strategies, including interactive, heuristic, and gradient-based optimization; and computational structural analysis methods, including the finite element method, graphic statics, and approximation techniques. Programing experience and familiarity with structural mechanics necessary. Additional work required of students taking graduate version. Limited to 25 total for versions meeting together.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"17:00","room":"W41-1216"}]}],"url":"http://student.mit.edu/catalog/m4d.html#4.451","terms":["fall"],"rating":6.41,"hours":13.65,"inClassHours":3.0,"outOfClassHours":10.65,"prerequisites":"((1.000/(6.100A, 6.100B)), (1.050/2.001/4.440))/''permission of instructor''","corequisites":"","recommendedPreparation":"Programing experience and familiarity with structural mechanics necessary."},{"code":"4.463","title":"Building Technology Systems: Structures and Envelopes","level":"G","description":"Addresses advanced structures, exterior envelopes, and contemporary production technologies. Continues the exploration of structural elements and systems, expanding to include more complex determinate, indeterminate, long-span, and high-rise systems. Topics include reinforced concrete, steel and engineered-wood design, and an introduction to tensile systems. The contemporary exterior envelope is discussed with an emphasis on the classification of systems, performance attributes, and analysis techniques, material specifications and novel construction technologies.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"W41-3101"}]},{"type":"Lab","options":[{"days":["F"],"start":"10:00","end":"12:00","room":"45-102"}]}],"url":"http://student.mit.edu/catalog/m4d.html#4.463","terms":["fall"],"rating":6.53,"hours":10.92,"inClassHours":5.22,"outOfClassHours":5.7,"prerequisites":"4.440/4.462/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.464","title":"Environmental Technologies in Buildings","level":"G","description":"Introduction to the study of the thermal and luminous behavior of buildings. Examines the basic scientific principles underlying these phenomena and introduces students to a range of technologies and analysis techniques for designing comfortable indoor environments. Challenges students to apply these techniques and explore the role energy and light can play in shaping architecture. Additional work required of students taking the graduate version.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"3-133"}]},{"type":"Lab","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"W41-1402"}]}],"url":"http://student.mit.edu/catalog/m4d.html#4.464","terms":["fall"],"rating":6.23,"hours":11.88,"inClassHours":4.91,"outOfClassHours":6.97,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.481","title":"Building Technology Seminar","level":"G","description":"Fundamental research methodologies and ongoing investigations in building tehnology to support the development of student research projects. Topics drawn from low energy building design and thermal comfort, building systems analysis and control, daylighting, structural design and analysis, novel building materials and construction techniques and resource dynamics. Organized as a series of two- and three-week sessions that consider topics through readings, discussions, design and analysis projects, and student presentations.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"15:00","end":"17:00","room":"W41-5510"}]}],"url":"http://student.mit.edu/catalog/m4d.html#4.481","terms":["fall"],"rating":6.51,"hours":9.03,"inClassHours":2.33,"outOfClassHours":6.7,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.500","title":"Design Through Computation and Making","level":"U","description":"Introduces 3D CAD modeling to students with little or no experience in design or computation. Teaches surface, solid and mesh modeling techniques combined with a variety of modeling applications, from 3D printing to CNC fabrication and 3D rendering. Includes weekly modeling assignments leading up to a final project. Students taking graduate version complete additional assignments. Lab fee required. Limited to 12 for versions meeting together; preference to Course 4 majors and design minors.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"09:00","end":"12:00","room":"W41-1402"}]}],"url":"http://student.mit.edu/catalog/m4e.html#4.500","terms":["fall"],"rating":5.12,"hours":9.67,"inClassHours":2.48,"outOfClassHours":7.19,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.502","title":"Advanced Visualization: Architecture in Motion Graphics","level":"U","description":"Advanced projects in architectural visualization with an emphasis on the use of computer graphics animation, interactive media, and video production tools. Introduces advanced visualization software and teaches exploration of spatial expressions in motion graphics format. Review and discussion of selected literature and video materials on architecture and film. Additional work required of students taking the graduate version. Preference to Course 4 and 4-B majors and Design and Architecture minors.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"12:30","end":"15:00","room":"W41-1219"}]},{"type":"Recitation","options":[{"days":["M"],"start":"19:00","end":"20:30","room":"W41-1219"}]}],"url":"http://student.mit.edu/catalog/m4e.html#4.502","terms":["fall"],"rating":6.07,"hours":9.93,"inClassHours":4.09,"outOfClassHours":5.84,"prerequisites":"4.500/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.505","title":"Design Through Computation and Making","level":"G","description":"Introduces 3-D CAD modeling to students with little or no experience in design or computation. Teaches surface, solid, and mesh modeling techniques combined with a variety of modeling applications ? from 3D printing to CNC fabrication and 3D rendering. Includes weekly modeling assignments leading up to a final project. Students taking graduate version complete additional assignments. Lab fee required. Limited to 12 for versions meeting together; preference to Course 4 majors and design minors.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"09:00","end":"12:00","room":"W41-1402"}]}],"url":"http://student.mit.edu/catalog/m4e.html#4.505","terms":["fall"],"rating":5.09,"hours":9.57,"inClassHours":2.44,"outOfClassHours":7.13,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.557","title":"City Science","level":"G","description":"Focuses on innovative propositions for shaping the cities of tomorrow, responding to emerging trends, technologies, and ecological imperatives. Students take part in 'what-if?' scenarios to tackle real-world challenges. Through collaborative, project-based learning in small teams, students are mentored by researchers from the City Science group. Projects focus on the application of these ideas to case study cities and may include travel. Invited guests from academia and industry participate. Repeatable for credit with permission of instructor.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"16:00","room":"E15-341"}]}],"url":"http://student.mit.edu/catalog/m4e.html#4.557","terms":["fall","spring"],"rating":4.34,"hours":7.8,"inClassHours":3.22,"outOfClassHours":4.58,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.562","title":"Advanced Visualization: Architecture in Motion Graphics","level":"G","description":"Advanced projects in architectural visualization with an emphasis on the use of computer graphics animation, interactive media, and video production tools. Introduces advanced visualization software and teaches exploration of spatial expressions in motion graphics format. Review and discussion of selected literature and video materials on architecture and film. Additional work required of students taking the graduate version. Preference to Course 4 and 4-B majors and Design and Architecture minors.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"12:30","end":"15:00","room":"W41-1219"}]},{"type":"Recitation","options":[{"days":["M"],"start":"19:00","end":"20:30","room":"W41-1219"}]}],"url":"http://student.mit.edu/catalog/m4e.html#4.562","terms":["fall"],"rating":6.07,"hours":9.93,"inClassHours":4.09,"outOfClassHours":5.84,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.566","title":"Advanced Projects in Digital Media","level":"G","description":"Develop independent projects in the study of digital media as it relates to architectural design. Students propose a project topic such as digital design tool, modeling and visualization, motion graphics, interactive design, design knowledge representation, and media interface. Limited to 5.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"17:00","end":"19:00","room":"W41-5520"}]}],"url":"http://student.mit.edu/catalog/m4e.html#4.566","terms":["fall"],"rating":6.95,"hours":11.86,"inClassHours":2.91,"outOfClassHours":8.95,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.580","title":"Inquiry into Computation and Design","level":"G","description":"Explores the varied nature, history and practice of computation in design through lectures, readings, small projects, discussions, and guest visits by Computation group faculty and others. Topics may vary from year to year. Aims to help students develop a critical awareness of different approaches to and assumptions about computation in design beyond the specifics of techniques and tools, and to open avenues for further research.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"09:30","end":"12:30","room":"W41-5520"}]}],"url":"http://student.mit.edu/catalog/m4e.html#4.580","terms":["fall"],"rating":5.91,"hours":12.04,"inClassHours":2.98,"outOfClassHours":9.06,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.581","title":"Proseminar in Computation","level":"G","description":"Introduction to traditions of research in design and computation scholarship.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"09:30","end":"12:30","room":"W41-1119"}]}],"url":"http://student.mit.edu/catalog/m4e.html#4.581","terms":["fall"],"rating":7.0,"hours":6.5,"inClassHours":2.6,"outOfClassHours":3.9,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.583","title":"Forum in Computation","level":"G","description":"Group discussions and presentation of ongoing graduate student research in the Computation program.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"17:30","end":"19:00","room":"W41-1101"}]}],"url":"http://student.mit.edu/catalog/m4e.html#4.583","terms":["fall"],"rating":6.84,"hours":2.97,"inClassHours":2.05,"outOfClassHours":0.92,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.588","title":"Preparation for SMArchS Computation Thesis","level":"G","description":"Students select thesis topic, define method of approach, and prepare thesis proposal for SMArchS Computation degree. Faculty supervision on a group basis. Intended for SMArchS Computation program students, prior to registration for 4.ThG. Limited to SMArchS Computation students.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"W41-5520"}]}],"url":"http://student.mit.edu/catalog/m4e.html#4.588","terms":["fall","spring"],"rating":5.0,"hours":13.0,"inClassHours":3.0,"outOfClassHours":10.0,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.603","title":"Understanding Modern Architecture","level":"U","description":"Examines modern architecture, art, and design in the context of the political, economic, aesthetic, and cultural changes that occurred in the twentieth century. Presents foundational debates about social and technological aspects of modern architecture and the continuation of those debates into contemporary architecture. Incorporates varied techniques of historical and theoretical analysis to interpret exemplary objects, buildings, and cities of modernity. Additional work required of students taking the graduate version. Preference to Course 4 majors and minors.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"W41-2302"}]}],"url":"http://student.mit.edu/catalog/m4f.html#4.603","terms":["fall"],"rating":5.81,"hours":8.31,"inClassHours":3.15,"outOfClassHours":5.16,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.604","title":"Understanding Modern Architecture","level":"G","description":"Examines modern architecture, art, and design in the context of the political, economic, aesthetic, and cultural changes that occurred in the twentieth century. Presents foundational debates about social and technological aspects of modern architecture and the continuation of those debates into contemporary architecture. Incorporates varied techniques of historical and theoretical analysis to interpret exemplary objects, buildings, and cities of modernity. Additional work required of students taking the graduate version. Preference to Course 4 majors.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"W41-2302"}]}],"url":"http://student.mit.edu/catalog/m4f.html#4.604","terms":["fall"],"rating":5.81,"hours":8.31,"inClassHours":3.15,"outOfClassHours":5.16,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.607","title":"Thinking About Architecture: In History and At Present","level":"G","description":"Studies the interrelationship of theory, history, and practice. Looks at theory not as specialized discourse relating only to architecture, but as touching on many issues, whether they be cultural, aesthetic, philosophical, or professional. Topics and examples are chosen from a wide range of materials, from classical antiquity to today.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"W41-1303"}]}],"url":"http://student.mit.edu/catalog/m4f.html#4.607","terms":["fall"],"rating":5.42,"hours":6.46,"inClassHours":3.06,"outOfClassHours":3.4,"prerequisites":"4.645/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.614","title":"Introduction to Islamic Architecture","level":"U","description":"Examines the history of Islamic architecture spanning fifteen centuries on three continents – Asia, Africa, Europe. Students study representative examples from the 7th century House of the Prophet to the current high-rises of Dubai, in conjunction with their religious, urban, social, political, and intellectual environments. Crosscultural exchanges are highlighted from late Antique Arabia down to the interaction with the West in the age of colonialism and the consequent revival of Islamic architecture today.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"5-216"}]}],"url":"http://student.mit.edu/catalog/m4f.html#4.614","terms":["fall"],"rating":6.33,"hours":8.55,"inClassHours":3.0,"outOfClassHours":5.55,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.617","title":"Topics in Islamic Urbanism","level":"G","description":"Seminar on selected topics from the history of Islamic urbanism. Examines patterns of settlement, urbanization, and architectural production in various places and periods, ranging from the formative period in the 7th century to the new cities emerging today in Asia and Africa. Discusses the leading factors in shaping and transforming urban forms, design imperatives, cultural and economic structures, and social and civic attitudes. Critically analyzes the body of literature on Islamic urbanism. Research paper required.  Limited to 12.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"17:00","room":"5-216"}]}],"url":"http://student.mit.edu/catalog/m4f.html#4.617","terms":["fall"],"rating":6.94,"hours":12.76,"inClassHours":2.97,"outOfClassHours":9.79,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.640","title":"Advanced Study in Critical Theory of Architecture","level":"G","description":"Seminar on a selected topic in critical theory. Requires original research and presentation of oral and written report.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:30","end":"12:30","room":"W41-2302"}]}],"url":"http://student.mit.edu/catalog/m4f.html#4.640","terms":["fall"],"rating":6.77,"hours":11.65,"inClassHours":3.0,"outOfClassHours":8.65,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.646","title":"Advanced Study in the History of Modern Architecture and Urbanism","level":"G","description":"Seminar in a selected topic in the history of modern architecture and urbanism. Oral presentations and research paper required.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"17:00","room":"W41-1119"}]}],"url":"http://student.mit.edu/catalog/m4f.html#4.646","terms":["fall","spring"],"rating":6.8,"hours":8.84,"inClassHours":3.0,"outOfClassHours":5.84,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.651","title":"Art Since 1940","level":"U","description":"Critical examination of major developments in European, Asian, and American art from 1940 to the present. Surveys the mainstream of art production but also examines marginal phenomena (feminism, identity politics, AIDS activism, net art) that come to change the terms of art's engagements with civic culture. Visits to area art museums and writing assignments develop skills for visual analysis and critical writing.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"W41-1101"}]}],"url":"http://student.mit.edu/catalog/m4f.html#4.651","terms":["fall"],"rating":5.9,"hours":7.9,"inClassHours":3.0,"outOfClassHours":4.9,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.661","title":"Theory and Method in the Study of Architecture and Art","level":"G","description":"Studies theoretical and historiographical works pertaining to the fields of art and architectural history. Members of seminar pursue work designed to examine their own presuppositions and methods. Preference to PhD and other advanced students.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"10:00","end":"13:00","room":"W41-2319"}]}],"url":"http://student.mit.edu/catalog/m4f.html#4.661","terms":["fall"],"rating":6.57,"hours":11.93,"inClassHours":3.3,"outOfClassHours":8.63,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.677","title":"Advanced Study in the History of Art","level":"G","description":"Seminar in a selected topic in the history of art, with a particular emphasis on artistic production from the 17th century to the present. Includes visits to area art museums and collections. Requires original research and presentation of oral and written reports, varying at the discretion of the instructor. Offered for 9 or 12 units. Limited to 12.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"14:00","end":"17:00","room":"W41-1119"}]}],"url":"http://student.mit.edu/catalog/m4f.html#4.677","terms":["fall"],"rating":6.98,"hours":11.31,"inClassHours":3.0,"outOfClassHours":8.31,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.S22","title":"Special Subject: Architecture Studies","level":"G","description":"Seminar or lecture on a topic in architecture studies that is not covered in the regular curriculum. Requires original research and presentation of oral and written reports and/or design projects, varying at the discretion of the instructor.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"W41-1219"}]}],"url":"http://student.mit.edu/catalog/m4b.html#4.S22","terms":["fall"],"rating":5.94,"hours":6.13,"inClassHours":2.16,"outOfClassHours":3.97,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.S24","title":"Special Subject: Architecture Studies","level":"G","description":"Seminar or lecture on a topic in architecture studies that is not covered in the regular curriculum. Requires original research and presentation of oral and written reports and/or design projects, varying at the discretion of the instructor.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"09:00","end":"11:00","room":"W41-5510"}]}],"url":"http://student.mit.edu/catalog/m4b.html#4.S24","terms":["fall"],"rating":5.41,"hours":7.52,"inClassHours":2.75,"outOfClassHours":4.77,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.S60","title":"Special Subject: History, Theory and Criticism of Architecture and Art","level":"G","description":"Seminar or lecture on a topic in the history, theory and criticism of architecture and art that is not covered in the regular curriculum. Requires original research and presentation of oral and written reports and/or design projects, varying at the discretion of the instructor.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"W41-2319"}]}],"url":"http://student.mit.edu/catalog/m4f.html#4.S60","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"4.S62","title":"Special Subject: History, Theory and Criticism of Architecture and Art","level":"G","description":"Seminar or lecture on a topic in the history, theory and criticism of architecture and art that is not covered in the regular curriculum. Requires original research and presentation of oral and written reports and/or design projects, varying at the discretion of the instructor.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"W41-1101"}]}],"url":"http://student.mit.edu/catalog/m4f.html#4.S62","terms":["fall"],"rating":6.48,"hours":9.38,"inClassHours":3.0,"outOfClassHours":6.38,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.S65","title":"Special Subject: Advanced Study in Islamic Architecture","level":"G","description":"Seminar or lecture on a topic in Islamic or non-western architecture that is not covered in the regular curriculum. Requires original research and presentation of oral and written reports, varying at the discretion of the instructor.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"14:00","end":"17:00","room":"W41-2319"}]}],"url":"http://student.mit.edu/catalog/m4f.html#4.S65","terms":["fall"],"rating":5.54,"hours":10.47,"inClassHours":3.0,"outOfClassHours":7.47,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"4.THT","title":"Thesis Research Design Seminar","level":"U","description":"Designed for students writing a thesis in Urban Studies and Planning or Architecture. Develop research topics, review relevant research and scholarship, frame research questions and arguments, choose an appropriate methodology for analysis, and draft introductory and methodology sections.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"W41-3102"}]}],"url":"http://student.mit.edu/catalog/m4g.html#4.THT","terms":["fall"],"rating":3.75,"hours":10.11,"inClassHours":2.92,"outOfClassHours":7.19,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"5.04","title":"Principles of Inorganic Chemistry II","level":"U","description":"Systematic presentation of the chemical applications of group theory. Emphasis on the formal development of the subject and its applications to the physical methods of inorganic chemical compounds. Against the backdrop of electronic structure, the electronic, vibrational, and magnetic properties of transition metal complexes are presented and their investigation by the appropriate spectroscopy described. Expectations differ for students taking the graduate version.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"2-105"}]},{"type":"Recitation","options":[{"days":["F"],"start":"14:00","end":"15:00","room":"4-257"}]}],"url":"http://student.mit.edu/catalog/m5a.html#5.04","terms":["fall"],"rating":6.34,"hours":8.48,"inClassHours":3.43,"outOfClassHours":5.05,"prerequisites":"5.03","corequisites":"","recommendedPreparation":""},{"code":"5.041","title":"Principles of Inorganic Chemistry II","level":"G","description":"Systematic presentation of the chemical applications of group theory. Emphasis on the formal development of the subject and its applications to the physical methods of inorganic chemical compounds. Against the backdrop of electronic structure, the electronic, vibrational, and magnetic properties of transition metal complexes are presented and their investigation by the appropriate spectroscopy described. Expectations differ for students taking the graduate version. Limited to graduate students; undergraduate students must take 5.04.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"2-105"}]},{"type":"Recitation","options":[{"days":["F"],"start":"14:00","end":"15:00","room":"4-257"}]}],"url":"http://student.mit.edu/catalog/m5a.html#5.041","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"5.03","corequisites":"","recommendedPreparation":""},{"code":"5.05","title":"Principles of Inorganic Chemistry III","level":"G","description":"Principles of main group (s and p block) element chemistry with an emphasis on synthesis, structure, bonding, and reaction mechanisms.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:00","end":"10:30","room":"4-153"}]}],"url":"http://student.mit.edu/catalog/m5a.html#5.05","terms":["fall"],"rating":5.38,"hours":7.84,"inClassHours":2.96,"outOfClassHours":4.88,"prerequisites":"5.03","corequisites":"5.04","recommendedPreparation":""},{"code":"5.067","title":"Crystal Structure Refinement","level":"G","description":"Practical aspects of crystal structure determination from data collection strategies to data reduction and basic and advanced refinement problems of organic and inorganic molecules.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"16:00","room":"26-322"}]},{"type":"Lab","options":[{"days":["R"],"start":"13:00","end":"16:00","room":"26-322"}]}],"url":"http://student.mit.edu/catalog/m5a.html#5.067","terms":["fall"],"rating":6.21,"hours":6.69,"inClassHours":5.74,"outOfClassHours":0.95,"prerequisites":"5.069/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"5.07","title":"Introduction to Biological Chemistry","level":"U","description":"Chemical and physical properties of the cell and its building blocks. Structures of proteins and principles of catalysis. The chemistry of organic/inorganic cofactors required for chemical transformations within the cell. Basic principles of metabolism and regulation in pathways, including glycolysis, gluconeogenesis, fatty acid synthesis/degradation, pentose phosphate pathway, Krebs cycle and oxidative phosphorylation, DNA replication, and transcription and translation.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"09:00","end":"10:00","room":"2-105"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"13:00","end":"14:00","room":"36-112"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"36-144"}]}],"url":"http://student.mit.edu/catalog/m5a.html#5.07","terms":["fall"],"rating":5.56,"hours":9.93,"inClassHours":4.26,"outOfClassHours":5.67,"prerequisites":"5.12","corequisites":"","recommendedPreparation":""},{"code":"5.111","title":"Principles of Chemical Science","level":"U","description":"Introduction to chemistry, with emphasis on basic principles of atomic and molecular electronic structure, thermodynamics, acid-base and redox equilibria, chemical kinetics, and catalysis. Introduction to the chemistry of biological, inorganic, and organic molecules.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"12:00","end":"13:00","room":"26-100"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"10:00","end":"11:00","room":"36-112"},{"days":["T","R"],"start":"10:00","end":"11:00","room":"36-155"},{"days":["T","R"],"start":"10:00","end":"11:00","room":"36-144"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"36-112"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"36-155"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"36-144"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"26-168"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"36-112"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"36-155"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"36-144"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"26-168"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"36-112"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"36-112"}]}],"url":"http://student.mit.edu/catalog/m5a.html#5.111","terms":["fall","spring"],"rating":4.82,"hours":9.65,"inClassHours":4.31,"outOfClassHours":5.34,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"5.112","title":"Principles of Chemical Science","level":"U","description":"Introduction to chemistry for students who have taken two or more years of high school chemistry or who have earned a score of at least 4 on the ETS Advanced Placement Exam.  Emphasis on basic principles of atomic and molecular electronic structure, thermodynamics, acid-base and redox equilibria, chemical kinetics, and catalysis. Applications of basic principles to problems in metal coordination chemistry, organic chemistry, and biological chemistry.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"11:00","end":"12:00","room":"4-237"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"11:00","end":"12:00","room":"26-328"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"36-372"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"36-372"}]}],"url":"http://student.mit.edu/catalog/m5a.html#5.112","terms":["fall"],"rating":4.64,"hours":10.95,"inClassHours":4.44,"outOfClassHours":6.51,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"5.12","title":"Organic Chemistry I","level":"U","description":"Introduction to organic chemistry. Development of basic principles to understand the structure and reactivity of organic molecules. Emphasis on substitution and elimination reactions and chemistry of the carbonyl group. Introduction to the chemistry of aromatic compounds.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"12:00","end":"13:00","room":"32-123"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"09:00","end":"10:00","room":"56-169"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"13-1143"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"13-1143"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"4-257"},{"days":["T","R"],"start":"09:00","end":"10:00","room":"26-142"},{"days":["M","W"],"start":"14:00","end":"15:00","room":"8-119"}]}],"url":"http://student.mit.edu/catalog/m5a.html#5.12","terms":["fall","spring"],"rating":4.98,"hours":12.47,"inClassHours":4.83,"outOfClassHours":7.64,"prerequisites":"GIR:CHEM","corequisites":"","recommendedPreparation":""},{"code":"5.13","title":"Organic Chemistry II","level":"U","description":"Focuses on synthesis, structure determination, mechanism, and the relationships between structure and reactivity. Selected topics illustrate the role of organic chemistry in biological systems and in the chemical industry.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"12:00","end":"13:00","room":"2-190"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"09:00","end":"10:00","room":"36-112"},{"days":["M","W"],"start":"15:00","end":"16:00","room":"36-153"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"4-159"},{"days":["T","R"],"start":"09:00","end":"10:00","room":"36-372"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"38-166"},{"days":["T","R"],"start":"15:00","end":"16:00","room":"38-166"},{"days":["T","R"],"start":"09:00","end":"10:00","room":"36-155"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"8-119"}]}],"url":"http://student.mit.edu/catalog/m5a.html#5.13","terms":["fall"],"rating":5.67,"hours":10.75,"inClassHours":4.53,"outOfClassHours":6.22,"prerequisites":"5.12","corequisites":"","recommendedPreparation":""},{"code":"5.310","title":"Laboratory Chemistry","level":"U","description":"Introduces experimental chemistry for students who are not majoring in Course 5. Principles and applications of chemical laboratory techniques, including preparation and analysis of chemical materials, measurement of pH, gas and liquid chromatography, visible-ultraviolet spectrophotometry, infrared spectroscopy, kinetics, data analysis, and elementary synthesis, are described, in addition to experimental design principles. Includes instruction and practice in written and oral communication to multiple audiences. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:00","end":"13:00","room":"4-370"}]},{"type":"Lab","options":[{"days":["M","W"],"start":"13:00","end":"17:00","room":"12-5170B"},{"days":["T","R"],"start":"13:00","end":"17:00","room":"12-5170B"}]}],"url":"http://student.mit.edu/catalog/m5a.html#5.310","terms":["fall","spring"],"rating":4.28,"hours":17.8,"inClassHours":9.79,"outOfClassHours":8.01,"prerequisites":"","corequisites":"5.12","recommendedPreparation":""},{"code":"5.351","title":"Fundamentals of Spectroscopy","level":"U","description":"Students carry out an experiment that introduces fundamental principles of the most common types of spectroscopy, including UV-visible absorption and fluorescence, infrared, and nuclear magnetic resonance. Emphasizes principles of how light interacts with matter, a fundamental and hands-on understanding of how spectrometers work, and what can be learned through spectroscopy about prototype molecules and materials. Students record and analyze spectra of small organic molecules, native and denatured proteins, semiconductor quantum dots, and laser crystals. Satisfies 4 units of Institute Laboratory credit.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:00","end":"13:00","room":"4-231"}]},{"type":"Lab","options":[{"days":["M","W"],"start":"13:00","end":"17:00","room":"12-5170B"},{"days":["T","R"],"start":"13:00","end":"17:00","room":"12-5170B"}]}],"url":"http://student.mit.edu/catalog/m5a.html#5.351","terms":["fall","spring"],"rating":4.65,"hours":15.12,"inClassHours":7.89,"outOfClassHours":7.23,"prerequisites":"GIR:CHEM","corequisites":"","recommendedPreparation":""},{"code":"5.352","title":"Synthesis of Coordination Compounds and Kinetics","level":"U","description":"Students carry out an experiment that provides an introduction to the synthesis of simple coordination compounds and chemical kinetics. Illustrates cobalt coordination chemistry and its transformations as detected by visible spectroscopy. Students observe isosbestic points in visible spectra, determine the rate and rate law, measure the rate constant at several temperatures, and derive the activation energy for the aquation reaction. Satisfies 5 units of Institute Laboratory credit.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:00","end":"13:00","room":"4-231"}]},{"type":"Lab","options":[{"days":["M","W"],"start":"13:00","end":"17:00","room":"12-5170B"},{"days":["T","R"],"start":"13:00","end":"17:00","room":"12-5170B"}]}],"url":"http://student.mit.edu/catalog/m5a.html#5.352","terms":["fall","spring"],"rating":4.64,"hours":14.54,"inClassHours":8.51,"outOfClassHours":6.03,"prerequisites":"","corequisites":"5.351","recommendedPreparation":""},{"code":"5.353","title":"Macromolecular Prodrugs","level":"U","description":"Students carry out an experiment that builds skills in how to rationally design macromolecules for drug delivery based on fundamental principles of physical organic chemistry. Begins with conjugation of a drug molecule to a polymerizable group through a cleavable linker to generate a prodrug monomer. Continues with polymerization of monomer to produce macromolecular (i.e., polymer) prodrug; monomer and polymer prodrugs are fully characterized. Rate of drug release is measured and correlated to the size of the macromolecule as well as the structure of the cleavable linker. Satisfies 4 units of Institute Laboratory credit.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:00","end":"13:00","room":"4-231"}]},{"type":"Lab","options":[{"days":["M","W"],"start":"13:00","end":"17:00","room":"12-5170B"},{"days":["T","R"],"start":"13:00","end":"17:00","room":"12-5170B"}]}],"url":"http://student.mit.edu/catalog/m5a.html#5.353","terms":["fall","spring"],"rating":4.85,"hours":16.37,"inClassHours":9.41,"outOfClassHours":6.96,"prerequisites":"","corequisites":"5.12, 5.352","recommendedPreparation":""},{"code":"5.363","title":"Organic Structure Determination","level":"U","description":"Introduces modern methods for the elucidation of the structure of organic compounds. Students carry out transition metal-catalyzed coupling reactions, based on chemistry developed in the Buchwald laboratory, using reactants of unknown structure. Students also perform full spectroscopic characterization - by proton and carbon NMR, IR, and mass spectrometry of the reactants - and carry out coupling products in order to identify the structures of each compound. Other techniques include transfer and manipulation of organic and organometallic reagents and compounds, separation by extraction, and purification by column chromatography. Satisfies 4 units of Institute Laboratory credit.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:00","end":"13:00","room":"2-105"}]},{"type":"Lab","options":[{"days":["M","W"],"start":"13:00","end":"17:00","room":"12-5170B"},{"days":["T","R"],"start":"13:00","end":"17:00","room":"12-5170B"}]}],"url":"http://student.mit.edu/catalog/m5a.html#5.363","terms":["fall"],"rating":6.03,"hours":12.86,"inClassHours":8.72,"outOfClassHours":4.14,"prerequisites":"5.12, 5.353","corequisites":"5.13","recommendedPreparation":""},{"code":"5.372","title":"Chemistry of Renewable Energy","level":"U","description":"Introduces the electrochemical processes that underlie renewable energy storage and recovery. Students investigate charge transfer reactions at electrode surfaces that are critical to the operation of advanced batteries, fuel cells, and electrolyzers. Develops basic theory behind inner- and outer-sphere charge transfer reactions at interfaces and applies this theory to construct mechanistic models for important energy conversion reactions including the reduction of O2 to water and the reduction of protons to H2. Students will also synthesize new catalytic materials for these reactions and investigate their relative performance.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:00","end":"13:00","room":"2-105"}]},{"type":"Lab","options":[{"days":["M","W"],"start":"13:00","end":"17:00","room":"12-5170B"},{"days":["T","R"],"start":"13:00","end":"17:00","room":"12-5170B"}]}],"url":"http://student.mit.edu/catalog/m5a.html#5.372","terms":["fall"],"rating":5.59,"hours":12.12,"inClassHours":7.32,"outOfClassHours":4.8,"prerequisites":"5.310/(5.03, 5.352)","corequisites":"","recommendedPreparation":""},{"code":"5.373","title":"Synthesis of Boron Heterocycles","level":"U","description":"Experimental module focused on the synthesis and characterization of boron heterocycles, which are used as chemical synthons for metal complexes, small-molecule activation (e.g., carbon dioxide), catalysis mediators, components of optoelectronic materials, monomers for polymeric systems, and molecular building blocks for photochemistry. Covers techniques such as glovebox and Schlenk line methods for synthesis in the absence of oxygen and water; ligand effects, filtration, reaction mixture concentration, and recrystallization under an inert atmosphere. Characterization methods include proton and boron NMR spectroscopy, UV-Vis spectroscopy, and fluorescence measurements.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:00","end":"13:00","room":"2-105"}]},{"type":"Lab","options":[{"days":["M","W"],"start":"13:00","end":"17:00","room":"12-5170B"},{"days":["T","R"],"start":"13:00","end":"17:00","room":"12-5170B"}]}],"url":"http://student.mit.edu/catalog/m5a.html#5.373","terms":["fall"],"rating":6.73,"hours":11.1,"inClassHours":8.8,"outOfClassHours":2.3,"prerequisites":"5.03, 5.363","corequisites":"","recommendedPreparation":""},{"code":"5.47","title":"Tutorial in Organic Chemistry","level":"G","description":"Systematic review of fundamental concepts concerned with the structure and transformations of organic molecules. Problem-solving workshop format. The program is intended primarily for first-year graduate students with a strong interest in organic chemistry. Meets during the month of September.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"09:00","end":"11:00","room":"18-278"}]}],"url":"http://student.mit.edu/catalog/m5a.html#5.47","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"5.43, ''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"5.511","title":"Synthetic Organic Chemistry I","level":"G","description":"Presents and discusses important topics in modern synthetic organic chemistry, with the objective of developing problem-solving skills for the design of synthetic routes to complex molecules.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:30","room":"4-257"}]}],"url":"http://student.mit.edu/catalog/m5b.html#5.511","terms":["fall"],"rating":6.39,"hours":8.4,"inClassHours":3.01,"outOfClassHours":5.39,"prerequisites":"5.43, ''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"5.53","title":"Molecular Structure and Reactivity","level":"G","description":"Reaction mechanisms in organic chemistry: methods of investigation, relation of structure to reactivity, and reactive intermediates.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"2-105"}]}],"url":"http://student.mit.edu/catalog/m5b.html#5.53","terms":["fall"],"rating":5.49,"hours":10.42,"inClassHours":3.53,"outOfClassHours":6.89,"prerequisites":"5.43, 5.601, 5.602","corequisites":"","recommendedPreparation":""},{"code":"5.54","title":"Advances in Chemical Biology","level":"G","description":"Introduction to current research at the interface of chemistry, biology, and bioengineering. Topics include imaging of biological processes, metabolic pathway engineering, protein engineering, mechanisms of DNA damage, RNA structure and function, macromolecular machines, protein misfolding and disease, metabolomics, and methods for analyzing signaling network dynamics. Lectures are interspersed with class discussions and student presentations based on current literature.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:00","end":"10:30","room":"4-261"}]}],"url":"http://student.mit.edu/catalog/m5b.html#5.54","terms":["fall"],"rating":4.92,"hours":11.14,"inClassHours":3.19,"outOfClassHours":7.95,"prerequisites":"5.07, 5.13, 7.06, ''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"5.601","title":"Thermodynamics I","level":"U","description":"Basic thermodynamics: state of a system, state variables. Work, heat, first law of thermodynamics, thermochemistry. Second and third law of thermodynamics: entropy and free energy, including the molecular basis for these thermodynamic functions. Equilibrium properties of macroscopic systems. Special attention to thermodynamics related to global energy issues and biological systems. Combination of 5.601 and 5.602 counts as a REST subject.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"4-270"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"12:00","end":"13:00","room":"1-242"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"1-242"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"1-242"}]}],"url":"http://student.mit.edu/catalog/m5b.html#5.601","terms":["fall","spring"],"rating":4.59,"hours":10.34,"inClassHours":4.52,"outOfClassHours":5.82,"prerequisites":"GIR:CAL2, GIR:CHEM","corequisites":"","recommendedPreparation":""},{"code":"5.602","title":"Thermodynamics II and Kinetics","level":"U","description":"Free energy and chemical potential. Phase equilibrium and properties of solutions. Chemical equilibrium of reactions. Rates of chemical reactions. Special attention to thermodynamics related to global energy issues and biological systems. Combination of 5.601 and 5.602 counts as a REST subject.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"4-270"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"12:00","end":"13:00","room":"1-242"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"1-242"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"1-242"}]}],"url":"http://student.mit.edu/catalog/m5b.html#5.602","terms":["fall","spring"],"rating":6.1,"hours":11.17,"inClassHours":5.33,"outOfClassHours":5.84,"prerequisites":"5.601","corequisites":"","recommendedPreparation":""},{"code":"5.611","title":"Introduction to Spectroscopy","level":"U","description":"Introductory quantum chemistry; particles and waves; wave mechanics; harmonic oscillator; applications to IR, Microwave and NMR spectroscopy. Combination of 5.611 and 5.612 counts as a REST subject.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"11:00","end":"12:00","room":"4-149"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"12:00","end":"13:00","room":"4-261"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"4-159"}]}],"url":"http://student.mit.edu/catalog/m5b.html#5.611","terms":["fall"],"rating":5.41,"hours":11.66,"inClassHours":4.65,"outOfClassHours":7.01,"prerequisites":"GIR:CAL2, GIR:CHEM, GIR:PHY2","corequisites":"","recommendedPreparation":""},{"code":"5.612","title":"Electronic Structure of Molecules","level":"U","description":"Introductory electronic structure; atomic structure and the Periodic Table; valence and molecular orbital theory; molecular structure, and photochemistry. Combination of 5.611 and 5.612 counts as a REST subject.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"11:00","end":"12:00","room":"4-149"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"12:00","end":"13:00","room":"4-261"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"4-159"}]}],"url":"http://student.mit.edu/catalog/m5b.html#5.612","terms":["fall"],"rating":4.68,"hours":12.35,"inClassHours":4.32,"outOfClassHours":8.03,"prerequisites":"5.611","corequisites":"","recommendedPreparation":""},{"code":"5.70","title":"Statistical Thermodynamics","level":"G","description":"Develops classical equilibrium statistical mechanical concepts for application to chemical physics problems. Basic concepts of ensemble theory formulated on the basis of thermodynamic fluctuations. Examples of applications include Ising models, lattice models of binding, ionic and non-ionic solutions, liquid theory, polymer and protein conformations, phase transition, and pattern formation. Introduces computational techniques with examples of liquid and polymer simulations.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"4-159"}]}],"url":"http://student.mit.edu/catalog/m5b.html#5.70","terms":["fall"],"rating":5.08,"hours":10.46,"inClassHours":3.06,"outOfClassHours":7.4,"prerequisites":"5.601/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"5.73","title":"Introductory Quantum Mechanics I","level":"G","description":"Presents the fundamental concepts of quantum mechanics: wave properties, uncertainty principles, Schrodinger equation, and operator and matrix methods. Includes applications to one-dimensional potentials (harmonic oscillator), three-dimensional centrosymetric potentials (hydrogen atom), and angular momentum and spin. Approximation methods include WKB, variational principle, and perturbation theory.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"09:00","end":"10:00","room":"4-153"}]}],"url":"http://student.mit.edu/catalog/m5b.html#5.73","terms":["fall"],"rating":6.35,"hours":11.06,"inClassHours":3.04,"outOfClassHours":8.02,"prerequisites":"5.611, 5.612, 8.03, 18.03","corequisites":"","recommendedPreparation":""},{"code":"5.91","title":"Teaching Experience in the Chemical Sciences","level":"G","description":"For students in the chemistry graduate program while teaching. Classroom or laboratory teaching under the supervision of a faculty member and classroom-based instruction on timely topics related to education and modern teaching practices. Limited to chemistry graduate students who are teaching the same term.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"13:00","end":"14:30","room":"3-270"}]}],"url":"http://student.mit.edu/catalog/m5b.html#5.91","terms":["fall","spring"],"rating":3.66,"hours":2.64,"inClassHours":1.21,"outOfClassHours":1.43,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"5.913","title":"Seminar in Organic Chemistry","level":"G","description":"Discusses current journal publications in organic chemistry.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"16:00","end":"18:00","room":"6-120"}]}],"url":"http://student.mit.edu/catalog/m5b.html#5.913","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"5.921","title":"Seminar in Chemical Biology","level":"G","description":"Discusses topics of current interest in chemical biology.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"16:00","end":"18:00","room":"4-270"}]}],"url":"http://student.mit.edu/catalog/m5b.html#5.921","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"5.931","title":"Seminar in Physical Chemistry","level":"G","description":"Discusses topics of current interest in physical chemistry.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"16:00","end":"18:00","room":"6-120"}]}],"url":"http://student.mit.edu/catalog/m5b.html#5.931","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"5.60","corequisites":"","recommendedPreparation":""},{"code":"5.941","title":"Seminar in Inorganic Chemistry","level":"G","description":"Discusses current research in inorganic chemistry.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"16:00","end":"18:00","room":"4-370"}]}],"url":"http://student.mit.edu/catalog/m5b.html#5.941","terms":["fall","spring"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"5.03","corequisites":"","recommendedPreparation":""},{"code":"5.S52","title":"Special Subject in Chemistry","level":"G","description":"Organized lecture consisting of material in the broadly-defined field of chemistry not offered in regularly scheduled subjects.","groups":[{"type":"Lab","options":[{"days":["M","W"],"start":"14:00","end":"16:00","room":"2-146"}]}],"url":"http://student.mit.edu/catalog/m5b.html#5.S52","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"6.00","title":"Introduction to Computer Science and Programming","level":"U","description":"","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"16:30","room":"26-100"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.00","terms":["fall","spring"],"rating":5.09,"hours":11.72,"inClassHours":2.86,"outOfClassHours":8.86,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"6.041A","title":"Introduction to Probability I","level":"U","description":"Provides an introduction to probability theory and the modeling and analysis of probabilistic systems. Probabilistic models, conditional probability. Discrete and continuous random variables. Expectation and conditional expectation. Limit Theorems. Students taking graduate version complete additional assignments. Combination of 6.041A and 6.041B counts as a REST subject.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"12:00","end":"13:00","room":"2-190"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"11:00","end":"12:00","room":"24-121"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"24-121"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"1-150"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"1-150"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.041A","terms":["fall","spring"],"rating":5.24,"hours":9.65,"inClassHours":3.91,"outOfClassHours":5.74,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"6.041B","title":"Introduction to Probability II","level":"U","description":"Continuation of 6.041A. Further topics about random variables. Bayesian estimation and hypothesis testing. Elements of statistical inference. Bernoulli and Poisson processes. Markov chains. Students taking graduate version complete additional assignments.  Combination of 6.041A and 6.041B counts as a REST subject.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"12:00","end":"13:00","room":"2-190"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"11:00","end":"12:00","room":"24-121"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"24-121"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"1-150"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"1-150"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.041B","terms":["fall","spring"],"rating":5.39,"hours":10.93,"inClassHours":4.04,"outOfClassHours":6.89,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"6.1000","title":"Introduction to Programming and Computer Science","level":"U","description":"Develops foundational skills in programming and in computational modeling. Covers widely used programming concepts in Python, including mutability, function objects, and object-oriented programming. Introduces algorithmic complexity and some common libraries. Throughout, demonstrates using computation to help understand real-world phenomena; topics include optimization problems, building simulations, and statistical modeling. Intended for students with at least some prior exposure to programming. Students with no programming experience are encouraged to take 6.100A and 6.100B (or 16.C20) over two terms.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"16:30","room":"54-100"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"37-212"},{"days":["F"],"start":"10:00","end":"11:00","room":"6-120"},{"days":["F"],"start":"11:00","end":"12:00","room":"6-120"},{"days":["F"],"start":"13:00","end":"14:00","room":"6-120"},{"days":["F"],"start":"14:00","end":"15:00","room":"6-120"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.1000","terms":["fall","spring"],"rating":5.0,"hours":12.2,"inClassHours":3.6,"outOfClassHours":8.6,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"6.100A","title":"Introduction to Computer Science Programming in Python","level":"U","description":"Introduction to computer science and programming. Students develop skills to program and use computational techniques to solve problems. Topics include: the notion of computation, Python, simple algorithms and data structures, object-oriented programming, testing and debugging, and algorithmic complexity. Lectures are viewed outside of class; in-class time is dedicated to problem-solving and discussion. Combination of 6.100A and 6.100B (or 16.C20) counts as REST subject.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"16:30","room":"26-100"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.100A","terms":["fall","spring"],"rating":5.28,"hours":9.52,"inClassHours":3.4,"outOfClassHours":6.12,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"6.100B","title":"Introduction to Computational Thinking and Data Science","level":"U","description":"Provides an introduction to using computation to build models that can be used to help understand real-world phenomena. Topics include optimization problems, simulation models, and statistical models. Requires experience programming in Python as a prerequisite. Combination of 6.100A and 6.100B counts as REST subject.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"34-101"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"26-314"},{"days":["F"],"start":"10:00","end":"11:00","room":"26-322"},{"days":["F"],"start":"11:00","end":"12:00","room":"26-328"},{"days":["F"],"start":"13:00","end":"14:00","room":"26-328"},{"days":["F"],"start":"14:00","end":"15:00","room":"26-328"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.100B","terms":["fall","spring"],"rating":4.98,"hours":8.97,"inClassHours":2.73,"outOfClassHours":6.24,"prerequisites":"6.100A/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.1010","title":"Fundamentals of Programming","level":"U","description":"Introduces fundamental concepts of programming. Designed to develop skills in applying basic methods from programming languages to abstract problems. Topics include programming and Python basics, computational concepts, software engineering, algorithmic techniques, data types, and recursion. Lab component consists of software design, construction, and implementation of design. Enrollment may be limited.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"09:30","end":"11:00","room":"34-501"},{"days":["R"],"start":"11:00","end":"12:30","room":"34-501"},{"days":["R"],"start":"13:00","end":"14:30","room":"34-501"},{"days":["R"],"start":"14:30","end":"16:00","room":"34-501"}]},{"type":"Lab","options":[{"days":["T"],"start":"09:30","end":"11:00","room":"34-501"},{"days":["T"],"start":"11:00","end":"12:30","room":"34-501"},{"days":["T"],"start":"13:00","end":"14:30","room":"34-501"},{"days":["T"],"start":"14:30","end":"16:00","room":"34-501"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.1010","terms":["fall","spring"],"rating":5.87,"hours":10.48,"inClassHours":2.11,"outOfClassHours":8.37,"prerequisites":"6.1000/(6.100A, (6.100B/16.C20))","corequisites":"","recommendedPreparation":""},{"code":"6.1040","title":"Software Design","level":"U","description":"Provides design-focused instruction on how to build complex software applications. Presents key skills in product design and human-computer interaction (identifying authentic demand, prototyping, visual design, and user testing), software concept design (achieving clarity, modularity, and focus in structuring functionality), and analyzing social and ethical implications. Implementation topics include client/server web apps, reactive front-ends, and databases. Students work on both individual projects and a larger team project, and are taught to make effective and intentional use of LLMs in design and coding.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"1-190"}]},{"type":"Recitation","options":[{"days":["R"],"start":"10:00","end":"11:00","room":"34-301"},{"days":["R"],"start":"13:00","end":"14:00","room":"34-302"},{"days":["R"],"start":"14:00","end":"15:00","room":"34-302"},{"days":["R"],"start":"15:00","end":"16:00","room":"34-304"},{"days":["R"],"start":"12:00","end":"13:00","room":"26-314"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.1040","terms":["fall"],"rating":5.11,"hours":15.9,"inClassHours":3.59,"outOfClassHours":12.31,"prerequisites":"6.1020, 6.1200","corequisites":"","recommendedPreparation":""},{"code":"6.1120","title":"Dynamic Computer Language Engineering","level":"U","description":"Studies the design and implementation of modern, dynamic programming languages. Topics include fundamental approaches for parsing, semantics and interpretation, virtual machines, garbage collection, just-in-time machine code generation, and optimization. Includes a semester-long, group project that delivers a virtual machine that spans all of these topics.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"13:00","end":"14:00","room":"56-114"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"13:00","end":"14:00","room":"36-155"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.1120","terms":["fall"],"rating":6.52,"hours":12.7,"inClassHours":3.04,"outOfClassHours":9.66,"prerequisites":"6.1020/6.1910","corequisites":"","recommendedPreparation":""},{"code":"6.1200","title":"Mathematics for Computer Science","level":"U","description":"Elementary discrete mathematics for science and engineering, with a focus on mathematical tools and proof techniques useful in computer science. Topics include logical notation, sets, relations, elementary graph theory, state machines and invariants, induction and proofs by contradiction, recurrences, asymptotic notation, elementary analysis of algorithms, elementary number theory and cryptography, permutations and combinations, counting tools, and discrete probability.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"26-100"}]},{"type":"Recitation","options":[{"days":["W","F"],"start":"10:00","end":"11:00","room":"26-168"},{"days":["W","F"],"start":"13:00","end":"14:00","room":"38-166"},{"days":["W","F"],"start":"13:00","end":"14:00","room":"36-153"},{"days":["W","F"],"start":"14:00","end":"15:00","room":"26-168"},{"days":["W","F"],"start":"14:00","end":"15:00","room":"38-166"},{"days":["W","F"],"start":"14:00","end":"15:00","room":"24-307"},{"days":["W","F"],"start":"15:00","end":"16:00","room":"26-168"},{"days":["W","F"],"start":"15:00","end":"16:00","room":"38-166"},{"days":["W","F"],"start":"15:00","end":"16:00","room":"26-204"},{"days":["W","F"],"start":"16:00","end":"17:00","room":"26-168"},{"days":["W","F"],"start":"10:00","end":"11:00","room":"36-144"},{"days":["W","F"],"start":"11:00","end":"12:00","room":"26-168"},{"days":["W","F"],"start":"11:00","end":"12:00","room":"36-144"},{"days":["W","F"],"start":"11:00","end":"12:00","room":"13-3101"},{"days":["W","F"],"start":"12:00","end":"13:00","room":"26-168"},{"days":["W","F"],"start":"12:00","end":"13:00","room":"36-144"},{"days":["W","F"],"start":"12:00","end":"13:00","room":"13-3101"},{"days":["W","F"],"start":"13:00","end":"14:00","room":"26-168"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.1200","terms":["fall","spring"],"rating":5.6,"hours":11.28,"inClassHours":4.5,"outOfClassHours":6.78,"prerequisites":"GIR:CAL1","corequisites":"","recommendedPreparation":""},{"code":"6.1210","title":"Introduction to Algorithms","level":"U","description":"Introduction to mathematical modeling of computational problems, as well as common algorithms, algorithmic paradigms, and data structures used to solve these problems. Emphasizes the relationship between algorithms and programming, and introduces basic performance measures and analysis techniques for these problems. Enrollment may be limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"26-100"}]},{"type":"Recitation","options":[{"days":["W","F"],"start":"10:00","end":"11:00","room":"34-304"},{"days":["W","F"],"start":"10:00","end":"11:00","room":"35-310"},{"days":["W","F"],"start":"10:00","end":"11:00","room":"34-303"},{"days":["W","F"],"start":"11:00","end":"12:00","room":"34-304"},{"days":["W","F"],"start":"11:00","end":"12:00","room":"35-310"},{"days":["W","F"],"start":"11:00","end":"12:00","room":"34-303"},{"days":["W","F"],"start":"12:00","end":"13:00","room":"4-159"},{"days":["W","F"],"start":"12:00","end":"13:00","room":"34-304"},{"days":["W","F"],"start":"13:00","end":"14:00","room":"34-304"},{"days":["W","F"],"start":"15:00","end":"16:00","room":"35-308"},{"days":["W","F"],"start":"14:00","end":"15:00","room":"35-310"},{"days":["W","F"],"start":"14:00","end":"15:00","room":"36-155"},{"days":["W","F"],"start":"15:00","end":"16:00","room":"36-155"},{"days":["W","F"],"start":"16:00","end":"17:00","room":"36-155"},{"days":["W","F"],"start":"12:00","end":"13:00","room":"3-442"},{"days":["W","F"],"start":"13:00","end":"14:00","room":"3-442"},{"days":["W","F"],"start":"13:00","end":"14:00","room":"35-310"},{"days":["W","F"],"start":"12:00","end":"13:00","room":"34-301"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.1210","terms":["fall","spring"],"rating":4.89,"hours":11.72,"inClassHours":4.11,"outOfClassHours":7.61,"prerequisites":"6.100A, (6.1200/(6.120A, (6.3700/6.3800/18.05/18.600)))","corequisites":"","recommendedPreparation":""},{"code":"6.1220","title":"Design and Analysis of Algorithms","level":"U","description":"Techniques for the design and analysis of efficient algorithms, emphasizing methods useful in practice. Topics include sorting; search trees, heaps, and hashing; divide-and-conquer; dynamic programming; greedy algorithms; amortized analysis; graph algorithms; and shortest paths. Advanced topics may include network flow; computational geometry; number-theoretic algorithms; polynomial and matrix calculations; caching; and parallel computing.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"34-101"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"36-155"},{"days":["F"],"start":"13:00","end":"14:00","room":"26-210"},{"days":["F"],"start":"13:00","end":"14:00","room":"36-156"},{"days":["F"],"start":"15:00","end":"16:00","room":"34-301"},{"days":["F"],"start":"09:00","end":"10:00","room":"34-301"},{"days":["F"],"start":"14:00","end":"15:00","room":"36-153"},{"days":["F"],"start":"14:00","end":"15:00","room":"36-112"},{"days":["F"],"start":"15:00","end":"16:00","room":"36-153"},{"days":["F"],"start":"10:00","end":"11:00","room":"36-156"},{"days":["F"],"start":"11:00","end":"12:00","room":"36-155"},{"days":["F"],"start":"11:00","end":"12:00","room":"36-156"},{"days":["F"],"start":"12:00","end":"13:00","room":"26-210"},{"days":["F"],"start":"12:00","end":"13:00","room":"36-156"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.1220","terms":["fall","spring"],"rating":5.33,"hours":10.98,"inClassHours":3.25,"outOfClassHours":7.73,"prerequisites":"6.1200, 6.1210","corequisites":"","recommendedPreparation":""},{"code":"6.1600","title":"Foundations of Computer Security","level":"U","description":"Fundamental notions and big ideas for achieving security in computer systems. Topics include cryptographic foundations (pseudorandomness, collision-resistant hash functions, authentication codes, signatures, authenticated encryption, public-key encryption), systems ideas (isolation, non-interference, authentication, access control, delegation, trust), and implementation techniques (privilege separation, fuzzing, symbolic execution, runtime defenses, side-channel attacks). Case studies of how these ideas are realized in deployed systems. Lab assignments apply ideas from lectures to learn how to build secure systems and how they can be attacked.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"4-163"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"2-105"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.1600","terms":["fall"],"rating":6.37,"hours":9.55,"inClassHours":3.09,"outOfClassHours":6.46,"prerequisites":"(6.1210, (6.1800/6.1810))/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.1810","title":"Operating System Engineering","level":"U","description":"Design and implementation of operating systems, and their use as a foundation for systems programming. Topics include virtual memory, file systems, threads, context switches, kernels, interrupts, system calls, interprocess communication, coordination, and interaction between software and hardware. A multi-processor operating system for RISC-V, xv6, is used to illustrate these topics. Individual laboratory assignments involve extending the xv6 operating system, for example to support sophisticated virtual memory features and networking.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"45-230"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.1810","terms":["fall"],"rating":5.93,"hours":11.33,"inClassHours":2.87,"outOfClassHours":8.46,"prerequisites":"6.1910","corequisites":"","recommendedPreparation":""},{"code":"6.1850","title":"Computer Systems and Society","level":"U","description":"Explores the impact of computer systems on individual humans, society, and the environment. Examines large- and small-scale power structures that stem from low-level technical design decisions, the consequences of those structures on society, and how they can limit or provide access to certain technologies. Students assess design decisions within an ethical framework and consider the impact of their decisions on non-users. Case studies of working systems and readings from the current literature provide comparisons and contrasts. Possible topics include the implications of hierarchical designs (e.g., DNS) for scale; how layered models influence what parts of a network have the power to take certain actions; and the environmental impact of proof-of-work-based systems such as Bitcoin. Students taking graduate version complete additional assignments. Enrollment may be limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"34-301"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.1850","terms":["fall"],"rating":6.65,"hours":8.53,"inClassHours":3.0,"outOfClassHours":5.53,"prerequisites":"6.1800","corequisites":"","recommendedPreparation":""},{"code":"6.1852","title":"Computer Systems and Society","level":"G","description":"Explores the impact of computer systems on individual humans, society, and the environment. Examines large- and small-scale power structures that stem from low-level technical design decisions, the consequences of those structures on society, and how they can limit or provide access to certain technologies. Students assess design decisions within an ethical framework and consider the impact of their decisions on non-users. Case studies of working systems and readings from the current literature provide comparisons and contrasts. Possible topics include the implications of hierarchical designs (e.g., DNS) for scale; how layered models influence what parts of a network have the power to take certain actions; and the environmental impact of proof-of-work-based systems such as Bitcoin. Students taking graduate version complete different assignments. Enrollment may be limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"34-301"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.1852","terms":["fall"],"rating":6.6,"hours":8.8,"inClassHours":3.0,"outOfClassHours":5.8,"prerequisites":"6.1800","corequisites":"","recommendedPreparation":""},{"code":"6.1903","title":"Introduction to Low-level Programming in C and Assembly","level":"U","description":"Introduction to C and assembly language for students coming from a Python background (6.100A). Studies the C language, focusing on memory and associated topics including pointers, how different data structures are stored in memory, the stack, and the heap in order to build a strong understanding of the constraints involved in manipulating complex data structures in modern computational systems. Studies assembly language to facilitate a firm understanding of how high-level languages are translated to machine-level instructions.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"09:30","end":"11:00","room":"32-123"}]},{"type":"Lab","options":[{"days":["W"],"start":"09:30","end":"12:00","room":"38-530"},{"days":["W"],"start":"12:00","end":"14:30","room":"38-530"},{"days":["W"],"start":"14:30","end":"17:00","room":"38-530"},{"days":["W"],"start":"19:30","end":"22:00","room":"38-530"}]},{"type":"Recitation","options":[{"days":["T"],"start":"13:00","end":"14:30","room":"4-270"},{"days":["T"],"start":"14:30","end":"16:00","room":"4-270"},{"days":["T"],"start":"09:30","end":"11:00","room":"E25-117"},{"days":["T"],"start":"11:00","end":"12:30","room":"E25-117"},{"days":["T"],"start":"13:00","end":"14:30","room":"24-115"},{"days":["T"],"start":"14:30","end":"16:00","room":"24-115"},{"days":["T"],"start":"09:30","end":"11:00","room":"66-168"},{"days":["T"],"start":"11:00","end":"12:30","room":"66-168"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.1903","terms":["fall","spring"],"rating":5.64,"hours":11.44,"inClassHours":5.39,"outOfClassHours":6.05,"prerequisites":"6.100A","corequisites":"","recommendedPreparation":""},{"code":"6.1910","title":"Computation Structures","level":"U","description":"Provides an introduction to the design of digital systems and computer architecture. Emphasizes expressing all hardware designs in a high-level hardware description language and synthesizing the designs. Topics include combinational and sequential circuits, instruction set abstraction for programmable hardware, single-cycle and pipelined processor implementations, multi-level memory hierarchies, virtual memory, exceptions and I/O, and parallel systems.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:00","room":"32-123"}]},{"type":"Recitation","options":[{"days":["W","F"],"start":"10:00","end":"11:00","room":"34-301"},{"days":["W","F"],"start":"11:00","end":"12:00","room":"34-301"},{"days":["W","F"],"start":"10:00","end":"11:00","room":"34-302"},{"days":["W","F"],"start":"11:00","end":"12:00","room":"34-302"},{"days":["W","F"],"start":"12:00","end":"13:00","room":"34-302"},{"days":["W","F"],"start":"13:00","end":"14:00","room":"34-302"},{"days":["W","F"],"start":"14:00","end":"15:00","room":"34-302"},{"days":["W","F"],"start":"15:00","end":"16:00","room":"34-302"},{"days":["W","F"],"start":"12:00","end":"13:00","room":"34-303"},{"days":["W","F"],"start":"13:00","end":"14:00","room":"34-303"},{"days":["W","F"],"start":"14:00","end":"15:00","room":"34-303"},{"days":["W","F"],"start":"15:00","end":"16:00","room":"34-303"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.1910","terms":["fall","spring"],"rating":5.58,"hours":11.91,"inClassHours":3.53,"outOfClassHours":8.38,"prerequisites":"(GIR:PHY2, 6.100A, (6.1903/6.1904))/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.2000","title":"Electrical Circuits: Modeling and Design of Physical Systems","level":"U","description":"Fundamentals of linear systems, and abstraction modeling of multi-physics lumped and distributed systems using lumped electrical circuits. Linear networks involving independent and dependent sources, resistors, capacitors, and inductors. Extensions to include operational amplifiers and transducers. Dynamics of first- and second-order networks; analysis and design in the time and frequency domains; signal and energy processing applications. Design exercises. Weekly laboratory with microcontroller and transducers.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:00","room":"4-370"}]},{"type":"Lab","options":[{"days":["F"],"start":"10:00","end":"13:00","room":"34-501"},{"days":["F"],"start":"14:00","end":"17:00","room":"34-501"}]},{"type":"Recitation","options":[{"days":["W"],"start":"12:00","end":"13:00","room":"4-265"},{"days":["W"],"start":"13:00","end":"14:00","room":"4-265"},{"days":["W"],"start":"14:00","end":"15:00","room":"4-265"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.2000","terms":["fall","spring"],"rating":5.93,"hours":11.47,"inClassHours":5.2,"outOfClassHours":6.27,"prerequisites":"GIR:PHY2","corequisites":"","recommendedPreparation":""},{"code":"6.2020","title":"Electronics Project Laboratory","level":"U","description":"Intuition-based introduction to electronics, electronic components, and test equipment such as oscilloscopes, multimeters, and signal generators. Key components studied and used are op-amps, comparators, bi-polar transistors, and diodes (including LEDs). Students design, build, and debug small electronics projects (often featuring sound and light) to put their new knowledge into practice. Upon completing the class, students can take home a kit of components. Intended for students with little or no previous background in electronics. Enrollment may be limited.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"4-409"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.2020","terms":["fall","spring"],"rating":6.5,"hours":4.48,"inClassHours":2.91,"outOfClassHours":1.57,"prerequisites":"","corequisites":"","recommendedPreparation":"Intended for students with little or no previous background in electronics."},{"code":"6.2050","title":"Digital Systems Laboratory","level":"U","description":"Lab-intensive subject that investigates digital systems with a focus on FPGAs. Lectures and labs cover logic, flip flops, counters, timing, synchronization, finite-state machines, digital signal processing, communication protocols, and modern sensors. Prepares students for the design and implementation of a large-scale final project of their choice: games, music, digital filters, wireless communications, video, or graphics. Extensive use of System/Verilog for describing and implementing and verifying digital logic designs.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"45-230"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.2050","terms":["fall"],"rating":6.74,"hours":13.5,"inClassHours":3.61,"outOfClassHours":9.89,"prerequisites":"6.1910/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.2090","title":"Solid-State Circuits","level":"U","description":"Fosters deep understanding and intuition that is crucial in innovating analog circuits and optimizing the whole system in bipolar junction transistor (BJT) and metal oxide semiconductor (MOS) technologies. Covers both theory and real-world applications of basic amplifier structures, operational amplifiers, temperature sensors, bandgap references. Covers topics such as noise, linearity and stability. Homework and labs give students access to CAD/EDA tools to design and analyze analog circuits. Provides practical experience through lab exercises, including a broadband amplifier design and characterization. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"36-156"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.2090","terms":["fall"],"rating":6.24,"hours":11.58,"inClassHours":3.08,"outOfClassHours":8.5,"prerequisites":"6.2040/6.2080/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.2092","title":"Solid-State Circuits","level":"G","description":"Fosters deep understanding and intuition that is crucial in innovating analog circuits and optimizing the whole system in bipolar junction transistor (BJT) and metal oxide semiconductor (MOS) technologies. Covers both theory and real-world applications of basic amplifier structures, operational amplifiers, temperature sensors, bandgap references. Covers topics such as noise, linearity and stability. Homework and labs give students access to CAD/EDA tools to design and analyze analog circuits. Provides practical experience through lab exercises, including a broadband amplifier design and characterization. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"36-156"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.2092","terms":["fall"],"rating":6.24,"hours":11.58,"inClassHours":3.08,"outOfClassHours":8.5,"prerequisites":"6.2040/6.2080/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.2200","title":"Electric Energy Systems","level":"U","description":"Analysis and design of modern power and energy systems. Provides a holistic overview of how electricity is produced, delivered, and managed, including power electronics, machines and supply technologies, grid optimization and control, grid planning, markets, and regulation. Students apply the material covered to consider critical challenges associated with global energy systems, including electrification, decarbonization, resilience, and load growth. Students taking graduate version complete different assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"4-261"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"4-257"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.2200","terms":["fall"],"rating":6.35,"hours":9.11,"inClassHours":3.15,"outOfClassHours":5.96,"prerequisites":"6.2000","corequisites":"","recommendedPreparation":""},{"code":"6.2202","title":"Electric Energy Systems","level":"G","description":"Analysis and design of modern power and energy systems. Provides a holistic overview of how electricity is produced, delivered, and managed, including power electronics, machines and supply technologies, grid optimization and control, grid planning, markets, and regulation. Students apply the material covered to consider critical challenges associated with global energy systems, including electrification, decarbonization, resilience, and load growth. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"4-261"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"4-257"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.2202","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"6.2000","corequisites":"","recommendedPreparation":""},{"code":"6.2210","title":"Electromagnetic Fields, Forces and Motion","level":"U","description":"Study of electromagnetics and electromagnetic energy conversion leading to an understanding of devices, including electromagnetic sensors, actuators, motors and generators. Quasistatic Maxwell's equations and the Lorentz force law. Studies of the quasistatic fields and their sources through solutions of Poisson's and Laplace's equations. Boundary conditions and multi-region boundary-value problems. Steady-state conduction, polarization, and magnetization. Charge conservation and relaxation, and magnetic induction and diffusion. Extension to moving materials. Electric and magnetic forces and force densities derived from energy, and stress tensors. Extensive use of engineering examples. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"32-124"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"2-136"},{"days":["F"],"start":"11:00","end":"12:00","room":"2-136"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.2210","terms":["fall"],"rating":6.5,"hours":12.43,"inClassHours":4.41,"outOfClassHours":8.02,"prerequisites":"GIR:PHY2, 18.03","corequisites":"","recommendedPreparation":""},{"code":"6.2220","title":"Power Electronics Laboratory","level":"U","description":"Introduces the design and construction of power electronic circuits and motor drives. Laboratory exercises include the construction of drive circuitry for an electric go-cart, flash strobes, computer power supplies, three-phase inverters for AC motors, and resonant drives for lamp ballasts and induction heating. Basic electric machines introduced include DC, induction, and permanent magnet motors, with drive considerations. Provides instruction in written and oral communication. Students taking independent inquiry version 6.2221 expand the scope of their laboratory project. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:00","room":"4-370"}]},{"type":"Recitation","options":[{"days":["W"],"start":"15:00","end":"16:00","room":"3-270"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.2220","terms":["fall"],"rating":6.56,"hours":22.38,"inClassHours":7.93,"outOfClassHours":14.45,"prerequisites":"6.2000/6.3100","corequisites":"","recommendedPreparation":""},{"code":"6.2221","title":"Power Electronics Laboratory - Independent Inquiry","level":"U","description":"Introduces the design and construction of power electronic circuits and motor drives. Laboratory exercises include the construction of drive circuitry for an electric go-cart, flash strobes, computer power supplies, three-phase inverters for AC motors, and resonant drives for lamp ballasts and induction heating. Basic electric machines introduced include DC, induction, and permanent magnet motors, with drive considerations. Provides instruction in written and oral communication. To satisfy the independent inquiry component of this subject, students expand the scope of their laboratory project. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:00","room":"4-370"}]},{"type":"Recitation","options":[{"days":["W"],"start":"15:00","end":"16:00","room":"3-270"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.2221","terms":["fall"],"rating":6.56,"hours":22.38,"inClassHours":7.93,"outOfClassHours":14.45,"prerequisites":"6.2000/6.3000","corequisites":"","recommendedPreparation":""},{"code":"6.2222","title":"Power Electronics Laboratory","level":"G","description":"Hands-on introduction to the design and construction of power electronic circuits and motor drives. Laboratory exercises (shared with 6.131 and 6.1311) include the construction of drive circuitry for an electric go-cart, flash strobes, computer power supplies, three-phase inverters for AC motors, and resonant drives for lamp ballasts and induction heating. Basic electric machines introduced including DC, induction, and permanent magnet motors, with drive considerations. Students taking graduate version complete additional assignments and an extended final project. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:00","room":"4-370"}]},{"type":"Recitation","options":[{"days":["W"],"start":"15:00","end":"16:00","room":"3-270"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.2222","terms":["fall"],"rating":6.55,"hours":22.34,"inClassHours":7.93,"outOfClassHours":14.41,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.2540","title":"Nanotechnology: From Atoms to Systems","level":"U","description":"Introduces the fundamentals of applied quantum mechanics, materials science, and fabrication skills needed to design, engineer, and build emerging nanodevices with diverse applications in energy, memory, display, communications, and sensing. Focuses on the application and outlines the full progression from the fundamentals to the implemented device and functional technology. Closely integrates lectures with design-oriented laboratory modules.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:00","end":"11:00","room":"4-270"}]},{"type":"Lab","options":[{"days":["F"],"start":"09:00","end":"12:00","room":"36-372"},{"days":["F"],"start":"12:00","end":"15:00","room":"4-265"},{"days":["F"],"start":"14:00","end":"17:00","room":"36-156"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.2540","terms":["fall"],"rating":6.7,"hours":10.44,"inClassHours":4.9,"outOfClassHours":5.54,"prerequisites":"GIR:PHY2","corequisites":"","recommendedPreparation":""},{"code":"6.260","title":"Advanced Topics in Communications","level":"G","description":"Advanced study of topics in communications. Specific focus varies from year to year.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"16:00","room":"36-112"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.261","terms":["fall","spring"],"rating":5.31,"hours":5.53,"inClassHours":3.0,"outOfClassHours":2.53,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.3000","title":"Signal Processing","level":"U","description":"Fundamentals of signal processing, focusing on the use of Fourier methods to analyze and process signals such as sounds and images. Topics include Fourier series, Fourier transforms, the Discrete Fourier Transform, sampling, convolution, deconvolution, filtering, noise reduction, and compression. Applications draw broadly from areas of contemporary interest with emphasis on both analysis and design.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:00","room":"4-370"}]},{"type":"Lab","options":[{"days":["T","R"],"start":"16:00","end":"17:00","room":"4-370"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"15:00","end":"16:00","room":"4-370"},{"days":["T","R"],"start":"15:00","end":"16:00","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.3000","terms":["fall","spring"],"rating":5.61,"hours":10.82,"inClassHours":3.93,"outOfClassHours":6.89,"prerequisites":"6.100A","corequisites":"","recommendedPreparation":""},{"code":"6.3100","title":"Dynamical System Modeling and Control Design","level":"U","description":"A learn-by-design introduction to modeling and control of discrete- and continuous-time systems, from intuition-building analytical techniques to more computational and data-centric strategies. Topics include: linear difference/differential equations (natural frequencies, transfer functions); controller metrics (stability, tracking, disturbance rejection); analytical techniques (PID, root-loci, lead-lag, phase margin); computational strategies (state-space, eigen-placement, LQR); and data-centric approaches (state estimation, regression, and identification). Concepts are introduced with lectures and online problems, and then mastered during weekly labs. In lab, students model, design, test, and explain systems and controllers involving sensors, actuators, and a microcontroller (e.g., optimizing thrust-driven positioners or stabilizing magnetic levitators). Students taking graduate version complete additional problems and labs.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"16:00","room":"2-190"}]},{"type":"Lab","options":[{"days":["F"],"start":"10:00","end":"13:00","room":"38-545"},{"days":["F"],"start":"14:00","end":"17:00","room":"38-545"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.3100","terms":["fall","spring"],"rating":5.73,"hours":9.17,"inClassHours":4.81,"outOfClassHours":4.36,"prerequisites":"GIR:PHY2, (18.06/18.C06)","corequisites":"","recommendedPreparation":""},{"code":"6.3102","title":"Dynamical System Modeling and Control Design","level":"G","description":"A learn-by-design introduction to modeling and control of discrete- and continuous-time systems, from intuition-building analytical techniques to more computational and data-centric strategies. Topics include: linear difference/differential equations (natural frequencies, transfer functions); controller metrics (stability, tracking, disturbance rejection); analytical techniques (PID, root-loci, lead-lag, phase margin); computational strategies (state-space, eigen-placement, LQR); and data-centric approaches (state estimation, regression and identification). Concepts are introduced with lectures and on-line problems, and then mastered during weekly labs. In lab, students model, design, test and explain systems and controllers involving sensors, actuators, and a microcontroller (e.g. optimizing thrust-driven positioners or stabilizing magnetic levitators). Students in the graduate version complete additional problems and labs.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"16:00","room":"2-190"}]},{"type":"Lab","options":[{"days":["F"],"start":"10:00","end":"13:00","room":"38-545"},{"days":["F"],"start":"14:00","end":"17:00","room":"38-545"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.3102","terms":["fall","spring"],"rating":5.73,"hours":9.17,"inClassHours":4.81,"outOfClassHours":4.36,"prerequisites":"GIR:PHY2, (18.06/18.C06)","corequisites":"","recommendedPreparation":""},{"code":"6.3260","title":"Networks","level":"U","description":"Highlights common principles that permeate the functioning of diverse technological, economic and social networks. Utilizes three sets of tools for analyzing networks -- random graph models, optimization, and game theory -- to study informational and learning cascades; economic and financial networks; social influence networks; formation of social groups; communication networks and the Internet; consensus and gossiping; spread and control of epidemics; control and use of energy networks; and biological networks. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:30","end":"12:00","room":"E51-149"}]},{"type":"Recitation","options":[{"days":["F"],"start":"15:00","end":"16:00","room":"E51-149"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.3260","terms":["fall"],"rating":5.0,"hours":7.38,"inClassHours":2.83,"outOfClassHours":4.55,"prerequisites":"6.3700/14.30","corequisites":"","recommendedPreparation":""},{"code":"6.3700","title":"Introduction to Probability","level":"U","description":"An introduction to probability theory, the modeling and analysis of probabilistic systems, and elements of statistical inference. Probabilistic models, conditional probability. Discrete and continuous random variables. Expectation and conditional expectation, and further topics about random variables. Limit Theorems. Bayesian estimation and hypothesis testing. Elements of classical statistical inference. Bernoulli and Poisson processes. Markov chains. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"54-100"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"12:00","end":"13:00","room":"66-144"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"66-168"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.3700","terms":["fall","spring"],"rating":5.43,"hours":10.42,"inClassHours":3.7,"outOfClassHours":6.72,"prerequisites":"GIR:CAL2","corequisites":"","recommendedPreparation":""},{"code":"6.3702","title":"Introduction to Probability","level":"G","description":"An introduction to probability theory, the modeling and analysis of probabilistic systems, and elements of statistical inference. Probabilistic models, conditional probability. Discrete and continuous random variables. Expectation and conditional expectation, and further topics about random variables. Limit Theorems. Bayesian estimation and hypothesis testing. Elements of classical statistical inference. Bernoulli and Poisson processes. Markov chains. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"54-100"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"12:00","end":"13:00","room":"66-144"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"66-168"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.3702","terms":["fall","spring"],"rating":5.43,"hours":10.42,"inClassHours":3.7,"outOfClassHours":6.72,"prerequisites":"GIR:CAL2","corequisites":"","recommendedPreparation":""},{"code":"6.3800","title":"Introduction to Inference","level":"U","description":"Introduces probabilistic modeling for problems of inference and machine learning from data, emphasizing analytical and computational aspects. Distributions, marginalization, conditioning, and structure, including graphical and neural network representations. Belief propagation, decision-making, classification, estimation, and prediction. Sampling methods and analysis. Introduces asymptotic analysis and information measures. Computational laboratory component explores the concepts introduced in class in the context of contemporary applications. Students design inference algorithms, investigate their behavior on real data, and discuss experimental results.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:00","room":"32-141"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"13:00","end":"14:00","room":"2-105"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"2-105"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.3800","terms":["fall"],"rating":5.37,"hours":11.54,"inClassHours":3.61,"outOfClassHours":7.93,"prerequisites":"GIR:CAL2/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.3900","title":"Introduction to Machine Learning","level":"U","description":"Introduction to the principles and algorithms of machine learning from an optimization perspective. Topics include linear and non-linear models for supervised, unsupervised, and reinforcement learning, with a focus on gradient-based methods and neural-network architectures. Previous experience with algorithms may be helpful.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"14:30","end":"16:00","room":"10-250"}]},{"type":"Lab","options":[{"days":["W"],"start":"09:30","end":"11:00","room":"34-501"},{"days":["W"],"start":"11:00","end":"12:30","room":"34-501"},{"days":["W"],"start":"13:00","end":"14:30","room":"34-501"},{"days":["W"],"start":"14:30","end":"16:00","room":"34-501"},{"days":["W"],"start":"11:00","end":"12:30","room":"32-044"},{"days":["W"],"start":"13:00","end":"14:30","room":"32-044"}]},{"type":"Recitation","options":[{"days":["R"],"start":"11:00","end":"12:30","room":"32-044"},{"days":["R"],"start":"13:00","end":"14:30","room":"32-044"},{"days":["F"],"start":"09:30","end":"11:00","room":"32-044"},{"days":["F"],"start":"11:00","end":"12:30","room":"32-044"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.3900","terms":["fall","spring"],"rating":5.79,"hours":8.77,"inClassHours":3.51,"outOfClassHours":5.26,"prerequisites":"(6.1000/6.1210), (18.03/18.06)","corequisites":"","recommendedPreparation":"Previous experience with algorithms may be helpful."},{"code":"6.3930","title":"AI and Decision Making in Medicine: From Disease to Therapy","level":"U","description":"Introduction to fundamental principles and applications of artificial intelligence (AI) in medicine and medical research. Introduces foundational concepts in machine learning as they pertain to clinical decision support systems, personalized medicine, and advanced computational methods for drug optimization and protein folding. Stresses the interplay of clinical reasoning, risk stratification, and the design of novel therapeutics. Problem sets integrate theoretical knowledge and practical applications based on concrete problems in both medical and pharmaceutical science. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"56-114"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.3930","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"6.100A, 6.C01","corequisites":"","recommendedPreparation":""},{"code":"6.3932","title":"AI and Decision Making in Medicine: From Disease to Therapy","level":"G","description":"Introduction to fundamental principles and applications of artificial intelligence (AI) in medicine and medical research. Introduces foundational concepts in machine learning as they pertain to clinical decision support systems, personalized medicine, and advanced computational methods for drug optimization and protein folding. Stresses the interplay of clinical reasoning, risk stratification, and the design of novel therapeutics. Problem sets integrate theoretical knowledge and practical applications based on concrete problems in both medical and pharmaceutical science. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"56-114"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.3932","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"6.100A, 6.C01","corequisites":"","recommendedPreparation":""},{"code":"6.3950","title":"AI, Decision Making, and Society","level":"U","description":"Introduction to fundamentals of modern data-driven decision-making frameworks, such as causal inference and hypothesis testing in statistics as well as supervised and reinforcement learning in machine learning. Explores how these frameworks are being applied in various societal contexts, including criminal justice, healthcare, finance, and social media. Emphasis on pinpointing the non-obvious interactions, undesirable feedback loops, and unintended consequences that arise in such settings. Enables students to develop their own principled perspective on the interface of data-driven decision making and society. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"45-230"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"8-205"},{"days":["F"],"start":"11:00","end":"12:00","room":"8-205"},{"days":["F"],"start":"11:00","end":"12:00","room":"8-119"},{"days":["F"],"start":"12:00","end":"13:00","room":"8-205"},{"days":["F"],"start":"12:00","end":"13:00","room":"8-119"},{"days":["F"],"start":"13:00","end":"14:00","room":"8-205"},{"days":["F"],"start":"13:00","end":"14:00","room":"8-119"},{"days":["F"],"start":"14:00","end":"15:00","room":"8-205"},{"days":["F"],"start":"14:00","end":"15:00","room":"8-119"},{"days":["F"],"start":"15:00","end":"16:00","room":"8-205"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.3950","terms":["fall"],"rating":5.37,"hours":9.51,"inClassHours":3.46,"outOfClassHours":6.05,"prerequisites":"","corequisites":"6.1200/6.3700/6.3800/18.05/18.600","recommendedPreparation":""},{"code":"6.3952","title":"AI, Decision Making, and Society","level":"G","description":"Introduction to fundamentals of modern data-driven decision-making frameworks, such as causal inference and hypothesis testing in statistics as well as supervised and reinforcement learning in machine learning. Explores how these frameworks are being applied in various societal contexts, including criminal justice, healthcare, finance, and social media. Emphasis on pinpointing the non-obvious interactions, undesirable feedback loops, and unintended consequences that arise in such settings. Enables students to develop their own principled perspective on the interface of data-driven decision making and society. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"45-230"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"8-205"},{"days":["F"],"start":"11:00","end":"12:00","room":"8-205"},{"days":["F"],"start":"11:00","end":"12:00","room":"8-119"},{"days":["F"],"start":"12:00","end":"13:00","room":"8-205"},{"days":["F"],"start":"12:00","end":"13:00","room":"8-119"},{"days":["F"],"start":"13:00","end":"14:00","room":"8-205"},{"days":["F"],"start":"13:00","end":"14:00","room":"8-119"},{"days":["F"],"start":"14:00","end":"15:00","room":"8-205"},{"days":["F"],"start":"14:00","end":"15:00","room":"8-119"},{"days":["F"],"start":"15:00","end":"16:00","room":"8-205"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.3952","terms":["fall"],"rating":5.37,"hours":9.51,"inClassHours":3.46,"outOfClassHours":6.05,"prerequisites":"","corequisites":"6.1200/6.3700/6.3800/18.05","recommendedPreparation":""},{"code":"6.4120","title":"Computational Cognitive Science","level":"U","description":"Introduction to computational theories of human cognition. Focus on principles of inductive learning and inference, and the representation of knowledge. Computational frameworks covered include Bayesian and hierarchical Bayesian models; probabilistic graphical models; nonparametric statistical models and the Bayesian Occam's razor; sampling algorithms for approximate learning and inference; and probabilistic models defined over structured representations such as first-order logic, grammars, or relational schemas. Applications to understanding core aspects of cognition, such as concept learning and categorization, causal reasoning, theory formation, language acquisition, and social inference. Graduate students complete a final project.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"46-3002"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.4120","terms":["fall"],"rating":6.35,"hours":7.53,"inClassHours":3.21,"outOfClassHours":4.32,"prerequisites":"6.3700/6.3800/9.40/18.05/6.3900/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.4130","title":"Principles of Autonomy and Decision Making","level":"U","description":"Surveys decision making methods used to create highly autonomous systems and decision aids. Applies models, principles and algorithms taken from artificial intelligence and operations research. Focuses on planning as state-space search, including uninformed, informed and sampling-based search, activity and motion planning, probabilistic and adversarial planning, Markov models and decision processes, Bayesian filtering, reinforcement learning, and machine learning. Includes methods for satisfiability and optimization of logical and finite domain constraints, graphical models, and methods for search, inference, and conflict-learning. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"4-163"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"33-319"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.4130","terms":["fall"],"rating":5.54,"hours":12.83,"inClassHours":3.57,"outOfClassHours":9.26,"prerequisites":"6.100B/6.1010/6.9080/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.4132","title":"Principles of Autonomy and Decision Making","level":"G","description":"Surveys decision making methods used to create highly autonomous systems and decision aids. Applies models, principles and algorithms taken from artificial intelligence and operations research. Focuses on planning as state-space search, including uninformed, informed and sampling-based search, activity and motion planning, probabilistic and adversarial planning, Markov models and decision processes, Bayesian filtering, reinforcement learning, and machine learning. Includes methods for satisfiability and optimization of logical and finite domain constraints, graphical models, and methods for search, inference, and conflict-learning. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"4-163"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.4132","terms":["fall"],"rating":5.54,"hours":12.83,"inClassHours":3.57,"outOfClassHours":9.26,"prerequisites":"6.100B/6.9080/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.4150","title":"Artificial Intelligence for Business","level":"G","description":"Explores how to design and evaluate products and policy based on artificial intelligence. Provides a functional (as opposed to mechanistic) understanding of the emerging technologies underlying AI. Presents AI's opportunities and risks and how to create conditions under which its deployment can succeed. No technical background required.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"E51-345"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.4150","terms":["fall"],"rating":6.3,"hours":6.0,"inClassHours":3.0,"outOfClassHours":3.0,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"6.4210","title":"Robotic Manipulation","level":"U","description":"Introduces the fundamental algorithmic approaches for creating robot systems that can autonomously manipulate physical objects in unstructured environments such as homes and restaurants. Topics include perception (including approaches based on deep learning and approaches based on 3D geometry), planning (robot kinematics and trajectory generation, collision-free motion planning, task-and-motion planning, and planning under uncertainty), as well as dynamics and control (both model-based and learning-based). Students taking graduate version complete additional assignments. Students engage in extensive written and oral communication exercises.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"45-230"}]},{"type":"Lab","options":[{"days":["F"],"start":"12:00","end":"13:00","room":"4-149"},{"days":["F"],"start":"13:00","end":"14:00","room":"4-149"},{"days":["F"],"start":"13:00","end":"14:00","room":"66-168"},{"days":["F"],"start":"14:00","end":"15:00","room":"66-168"}]},{"type":"Recitation","options":[{"days":["F"],"start":"12:00","end":"13:00","room":"36-112"},{"days":["F"],"start":"13:00","end":"14:00","room":"36-112"},{"days":["F"],"start":"13:00","end":"14:00","room":"36-144"},{"days":["F"],"start":"13:00","end":"14:00","room":"34-301"},{"days":["F"],"start":"14:00","end":"15:00","room":"36-144"},{"days":["F"],"start":"14:00","end":"15:00","room":"34-301"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.4210","terms":["fall"],"rating":5.48,"hours":12.2,"inClassHours":3.34,"outOfClassHours":8.86,"prerequisites":"(6.100A, 6.3900)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.4212","title":"Robotic Manipulation","level":"G","description":"Introduces the fundamental algorithmic approaches for creating robot systems that can autonomously manipulate physical objects in unstructured environments such as homes and restaurants. Topics include perception (including approaches based on deep learning and approaches based on 3D geometry), planning (robot kinematics and trajectory generation, collision-free motion planning, task-and-motion planning, and planning under uncertainty), as well as dynamics and control (both model-based and learning-based. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"45-230"}]},{"type":"Lab","options":[{"days":["F"],"start":"12:00","end":"13:00","room":"4-149"},{"days":["F"],"start":"13:00","end":"14:00","room":"4-149"},{"days":["F"],"start":"13:00","end":"14:00","room":"66-168"},{"days":["F"],"start":"14:00","end":"15:00","room":"66-168"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.4212","terms":["fall"],"rating":5.48,"hours":12.2,"inClassHours":3.34,"outOfClassHours":8.86,"prerequisites":"(6.100A, 6.3900)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.431A","title":"Introduction to Probability I","level":"G","description":"Provides an introduction to probability theory and the modeling and analysis of probabilistic systems. Probabilistic models, conditional probability. Discrete and continuous random variables. Expectation and conditional expectation. Limit Theorems. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"12:00","end":"13:00","room":"2-190"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"11:00","end":"12:00","room":"24-121"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"24-121"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"1-150"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"1-150"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.431A","terms":["fall","spring"],"rating":5.24,"hours":9.65,"inClassHours":3.91,"outOfClassHours":5.74,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"6.431B","title":"Introduction to Probability II","level":"G","description":"Continuation of 6.431A. Further topics about random variables. Bayesian estimation and hypothesis testing. Elements of statistical inference. Bernoulli and Poisson processes. Markov chains. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"12:00","end":"13:00","room":"2-190"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"11:00","end":"12:00","room":"24-121"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"24-121"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"1-150"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"1-150"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.431B","terms":["fall","spring"],"rating":5.39,"hours":10.93,"inClassHours":4.04,"outOfClassHours":6.89,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"6.4400","title":"Computer Graphics","level":"U","description":"Introduction to computer graphics algorithms, software and hardware. Topics include ray tracing, the graphics pipeline, transformations, texture mapping, shadows, sampling, global illumination, splines, animation and color.","groups":[{"type":"Lecture","options":[{"days":["W","F"],"start":"11:00","end":"12:30","room":"1-190"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.4400","terms":["fall"],"rating":5.52,"hours":10.02,"inClassHours":2.63,"outOfClassHours":7.39,"prerequisites":"6.1010, (18.06/18.C06)","corequisites":"","recommendedPreparation":""},{"code":"6.4420","title":"Computational Design and Fabrication","level":"U","description":"Introduces computational aspects of computer-aided design and manufacturing. Explores relevant methods in the context of additive manufacturing (e.g., 3D printing). Topics include computer graphics (geometry modeling, solid modeling, procedural modeling), physically-based simulation (kinematics, finite element method), 3D scanning/geometry processing, and an overview of 3D fabrication methods. Exposes students to the latest research in computational fabrication. Students taking the graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"32-141"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.4420","terms":["fall"],"rating":4.57,"hours":11.45,"inClassHours":3.49,"outOfClassHours":7.96,"prerequisites":"GIR:CAL2, (6.1010/''permission of instructor'')","corequisites":"","recommendedPreparation":""},{"code":"6.4550","title":"Interactive Music Systems","level":"U","description":"Explores audio synthesis, musical structure, human computer interaction (HCI), and visual presentation for the creation of interactive musical experiences. Topics include audio synthesis; mixing and looping; MIDI sequencing; generative composition; motion sensors; music games; and graphics for UI, visualization, and aesthetics. Includes weekly programming assignments in python. Teams build an original, dynamic, and engaging interactive music system for their final project. Students taking graduate version complete different assignments. Limited to 36.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"4-270"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.4550","terms":["fall","spring"],"rating":6.78,"hours":11.28,"inClassHours":3.08,"outOfClassHours":8.2,"prerequisites":"6.1010, (21M.051/21M.150/21M.151)","corequisites":"","recommendedPreparation":""},{"code":"6.4570","title":"Creating Video Games","level":"U","description":"Introduces students to the complexities of working in small, multidisciplinary teams to develop video games. Covers creative design and production methods, stressing design iteration and regular testing across all aspects of game development (design, visual arts, music, fiction, and programming). Assumes a familiarity with current video games, and the ability to discuss games critically. Previous experience in audio design, visual arts, or project management recommended. Limited to 36.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"16:00","room":"32-124"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.4570","terms":["fall"],"rating":6.32,"hours":11.46,"inClassHours":5.75,"outOfClassHours":5.71,"prerequisites":"6.100A/CMS.301","corequisites":"","recommendedPreparation":"Assumes a familiarity with current video games, and the ability to discuss games critically. Previous experience in audio design, visual arts, or project management recommended."},{"code":"6.4610","title":"Natural Language Processing","level":"U","description":"Introduces the study of computational models of human language, covering classical statistical methods, representation learning, and modern deep network models through the lens of language modeling. Students complete a substantial final project, applying or extending these methods. Instruction and practice in oral and written communication provided.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"32-123"}]},{"type":"Recitation","options":[{"days":["F"],"start":"09:00","end":"10:00","room":"36-153"},{"days":["F"],"start":"10:00","end":"11:00","room":"36-153"},{"days":["F"],"start":"16:00","end":"17:00","room":"36-112"},{"days":["F"],"start":"11:00","end":"12:00","room":"36-153"},{"days":["F"],"start":"11:00","end":"12:00","room":"36-112"},{"days":["F"],"start":"12:00","end":"13:00","room":"36-153"},{"days":["F"],"start":"12:00","end":"13:00","room":"36-155"},{"days":["F"],"start":"13:00","end":"14:00","room":"36-155"},{"days":["F"],"start":"13:00","end":"14:00","room":"56-154"},{"days":["F"],"start":"14:00","end":"15:00","room":"56-154"},{"days":["F"],"start":"15:00","end":"16:00","room":"36-112"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.4610","terms":["fall"],"rating":4.9,"hours":10.3,"inClassHours":3.1,"outOfClassHours":7.2,"prerequisites":"6.3900, (6.3700/6.3800), (18.06/18.C06)","corequisites":"","recommendedPreparation":""},{"code":"6.4800","title":"Biomedical Imaging with MRI: From Technology to Computation Applications","level":"U","description":"Presents medical imaging with MRI, motivated by examples of problems in human health that engage students in imaging hardware design, data acquisition and image reconstruction, and signal analysis and inference. Data from scientific and clinical applications in neuro- and cardiac MRI as applied in current practice are sourced for computational labs. Labs include kits for interactive and portable low-cost devices that can be assembled by the students to demonstrate fundamental building blocks of an MRI system. Students program lab MRI systems on their laptops for data collection and image reconstruction. Students apply concepts from lectures in labs for data collection for image reconstruction, image analysis, and inference by their own design, drawing on concepts in signal processing and machine learning.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"15:00","room":"48-316"}]},{"type":"Lab","options":[{"days":["F"],"start":"14:00","end":"17:00","room":"38-530"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.4800","terms":["fall"],"rating":7.0,"hours":6.72,"inClassHours":5.44,"outOfClassHours":1.28,"prerequisites":"(18.C06, (6.3000/16.002))/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.4820","title":"Quantitative and Clinical Physiology","level":"U","description":"Application of the principles of energy and mass flow to major human organ systems. Anatomical, physiological and clinical features of the cardiovascular, respiratory and renal systems. Mechanisms of regulation and homeostasis. Systems, features and devices that are most illuminated by the methods of physical sciences and engineering models. Required laboratory work includes animal studies. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"4-265"}]},{"type":"Recitation","options":[{"days":["W"],"start":"13:00","end":"14:00","room":"34-301"},{"days":["W"],"start":"14:00","end":"15:00","room":"34-301"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.4820","terms":["fall"],"rating":6.66,"hours":11.68,"inClassHours":4.38,"outOfClassHours":7.3,"prerequisites":"GIR:PHY2/18.03/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.4822","title":"Quantitative and Clinical Physiology","level":"G","description":"Application of the principles of energy and mass flow to major human organ systems. Anatomical, physiological and clinical features of the cardiovascular, respiratory and renal systems. Mechanisms of regulation and homeostasis. Systems, features and devices that are most illuminated by the methods of physical sciences and engineering models. Required laboratory work includes animal studies. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"4-265"}]},{"type":"Recitation","options":[{"days":["W"],"start":"13:00","end":"14:00","room":"34-301"},{"days":["W"],"start":"14:00","end":"15:00","room":"34-301"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.4822","terms":["fall"],"rating":6.66,"hours":11.68,"inClassHours":4.38,"outOfClassHours":7.3,"prerequisites":"6.4810, (2.006/6.2300)","corequisites":"","recommendedPreparation":""},{"code":"6.4832","title":"Fields, Forces, and Flows in Biological Systems","level":"G","description":"Molecular diffusion, diffusion-reaction, conduction, convection in biological systems; fields in heterogeneous media; electrical double layers; Maxwell stress tensor, electrical forces in physiological systems. Fluid and solid continua: equations of motion useful for porous, hydrated biological tissues. Case studies of membrane transport, electrode interfaces, electrical, mechanical, and chemical transduction in tissues, convective-diffusion/reaction, electrophoretic, electroosmotic flows in tissues/MEMs, and ECG. Electromechanical and physicochemical interactions in cells and biomaterials; musculoskeletal, cardiovascular, and other biological and clinical examples. Prior undergraduate coursework in transport recommended.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"4-231"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.4832","terms":["fall"],"rating":6.38,"hours":10.51,"inClassHours":3.01,"outOfClassHours":7.5,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":"Prior undergraduate coursework in transport recommended."},{"code":"6.4850","title":"Multiphysics Systems Modeling","level":"U","description":"Practices the use of modern numerical analysis tools (e.g., COMSOL) for biological and other systems with multi-physics behavior. Covers modeling diffusion, reaction, convection, and other transport mechanisms. Analysis of microfluidic devices provided as examples. Discusses practical issues and challenges in numerical modeling. Includes weekly modeling homework and major modeling projects. No prior knowledge of modeling software is required. Lectures are viewed outside of class; in-class time is dedicated to problem-solving and discussion. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"14:00","end":"15:00","room":"5-134"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.4850","terms":["fall"],"rating":6.4,"hours":13.3,"inClassHours":3.0,"outOfClassHours":10.3,"prerequisites":"2.005/6.2210/20.330/''permission of instructor''","corequisites":"","recommendedPreparation":"No prior knowledge of modeling software is required."},{"code":"6.4852","title":"Multiphysics Systems Modeling","level":"G","description":"Practices the use of modern numerical analysis tools (e.g., COMSOL) for biological and other systems with multi-physics behavior. Covers modeling diffusion, reaction, convection, and other transport mechanisms. Analysis of microfluidic devices provided as examples. Discusses practical issues and challenges in numerical modeling. Includes weekly modeling homework and major modeling projects. No prior knowledge of modeling software is required. Lectures are viewed outside of class; in-class time is dedicated to problem-solving and discussion. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"14:00","end":"15:00","room":"5-134"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.4852","terms":["fall"],"rating":6.4,"hours":13.3,"inClassHours":3.0,"outOfClassHours":10.3,"prerequisites":"2.005/6.2210/20.330/''permission of instructor''","corequisites":"","recommendedPreparation":"No prior knowledge of modeling software is required."},{"code":"6.5060","title":"Algorithm Engineering","level":"G","description":"Covers the theory and practice of algorithms and data structures. Topics include models of computation, algorithm design and analysis, and performance engineering of algorithm implementations. Presents the design and implementation of sequential, parallel, cache-efficient, and external-memory algorithms. Illustrates many of the principles of algorithm engineering in the context of parallel algorithms and graph problems.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"34-304"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.5060","terms":["fall"],"rating":6.33,"hours":12.34,"inClassHours":3.29,"outOfClassHours":9.05,"prerequisites":"6.1060, 6.1220","corequisites":"","recommendedPreparation":""},{"code":"6.5210","title":"Advanced Algorithms","level":"G","description":"First-year graduate subject in algorithms. Emphasizes fundamental algorithms and advanced methods of algorithmic design, analysis, and implementation. Surveys a variety of computational models and the algorithms for them. Data structures, network flows, linear programming, computational geometry, approximation algorithms, online algorithms, parallel algorithms, external memory, streaming algorithms.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"14:30","end":"16:00","room":"32-123"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.5210","terms":["fall"],"rating":6.35,"hours":16.86,"inClassHours":4.17,"outOfClassHours":12.69,"prerequisites":"6.1220, (6.1200/6.3700/18.600)","corequisites":"","recommendedPreparation":""},{"code":"6.5240","title":"Sublinear Time Algorithms","level":"G","description":"Sublinear time algorithms understand parameters and properties of input data after viewing only a minuscule fraction of it. Tools from number theory, combinatorics, linear algebra, optimization theory, distributed algorithms, statistics, and probability are covered. Topics include: testing and estimating properties of distributions, functions, graphs, strings, point sets, and various combinatorial objects.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"36-153"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.5240","terms":["fall"],"rating":6.6,"hours":10.12,"inClassHours":2.96,"outOfClassHours":7.16,"prerequisites":"6.1220/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.5400","title":"Theory of Computation","level":"G","description":"A more extensive and theoretical treatment of the material in 6.1400J/18.400J, emphasizing computability and computational complexity theory. Regular and context-free languages. Decidable and undecidable problems, reducibility, recursive function theory. Time and space measures on computation, completeness, hierarchy theorems, inherently complex problems, oracles, probabilistic computation, and interactive proof systems. Students in Course 18 must register for the undergraduate version, 18.404.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"54-100"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"4-159"},{"days":["F"],"start":"11:00","end":"12:00","room":"4-159"},{"days":["F"],"start":"12:00","end":"13:00","room":"4-257"},{"days":["F"],"start":"13:00","end":"14:00","room":"4-257"},{"days":["F"],"start":"14:00","end":"15:00","room":"4-145"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.5400","terms":["fall"],"rating":6.52,"hours":10.44,"inClassHours":3.33,"outOfClassHours":7.11,"prerequisites":"6.1200/18.200","corequisites":"","recommendedPreparation":""},{"code":"6.5430","title":"Quantum Complexity Theory","level":"G","description":"Introduction to quantum computational complexity theory, the study of the fundamental capabilities and limitations of quantum computers. Topics include complexity classes, lower bounds, communication complexity, proofs and advice, and interactive proof systems in the quantum world; classical simulation of quantum circuits. The objective is to bring students to the research frontier.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"36-153"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.5430","terms":["fall"],"rating":6.97,"hours":8.95,"inClassHours":3.0,"outOfClassHours":5.95,"prerequisites":"6.1400, 18.4041, 18.435","corequisites":"","recommendedPreparation":""},{"code":"6.5620","title":"Foundations of Cryptography","level":"G","description":"A rigorous introduction to modern cryptography. Emphasis on the fundamental cryptographic primitives such as public-key encryption, digital signatures, and pseudo-random number generation, as well as advanced cryptographic primitives such as zero-knowledge proofs, homomorphic encryption, and secure multiparty computation.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"2-190"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.5620","terms":["fall"],"rating":6.65,"hours":14.3,"inClassHours":3.07,"outOfClassHours":11.23,"prerequisites":"6.1220/6.1400/18.4041","corequisites":"","recommendedPreparation":""},{"code":"6.5820","title":"Computer Networks","level":"G","description":"Presents topics on the engineering and analysis of network protocols and architecture, including: architectural principles for designing heterogeneous networks; transport protocols; Internet routing; router design; congestion control and network resource management; wireless networks; network security; naming; overlay; and peer-to-peer networks. Includes readings from original research papers and a term-long project and paper. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"6-120"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.5820","terms":["fall"],"rating":6.27,"hours":11.09,"inClassHours":3.16,"outOfClassHours":7.93,"prerequisites":"6.1800/6.1810/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.5821","title":"Computer Networks","level":"U","description":"Presents topics on the engineering and analysis of network protocols and architecture, including: architectural principles for designing heterogeneous networks; transport protocols; Internet routing; router design; congestion control and network resource management; wireless networks; network security; naming; overlay; and peer-to-peer networks. Includes readings from original research papers and a term-long project and paper. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"6-120"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.5821","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"6.1800/6.1810/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.5900","title":"Computer System Architecture","level":"G","description":"Introduction to the principles underlying modern computer architecture. Emphasizes the relationship among technology, hardware organization, and programming systems in the evolution of computer architecture. Topics include pipelined, out-of-order, and speculative execution; caches, virtual memory and exception handling, superscalar, very long instruction word (VLIW), vector, and multithreaded processors; on-chip networks, memory models, synchronization, and cache coherence protocols for multiprocessors.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"45-102"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:30","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.5900","terms":["fall"],"rating":5.05,"hours":11.61,"inClassHours":3.64,"outOfClassHours":7.97,"prerequisites":"6.1910","corequisites":"","recommendedPreparation":""},{"code":"6.5940","title":"TinyML and Efficient Deep Learning Computing","level":"G","description":"Introduces efficient deep learning computing techniques that enable powerful deep learning applications on resource-constrained devices. Topics include model compression, pruning, quantization, neural architecture search, distributed training, data/model parallellism, gradient compression, on-device fine-tuning. It also introduces application-specific acceleration techniques for video recognition, point cloud, and generative AI (diffusion model, LLM). Students will get hands-on experience accelerating deep learning applications with an open-ended design project.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"16:00","end":"17:30","room":"54-100"}]}],"url":"http://student.mit.edu/catalog/m6a.html#6.5940","terms":["fall"],"rating":6.2,"hours":7.37,"inClassHours":3.07,"outOfClassHours":4.3,"prerequisites":"6.1910, 6.3900","corequisites":"","recommendedPreparation":""},{"code":"6.6010","title":"Analysis and Design of Digital Integrated Circuits","level":"G","description":"Device and circuit level optimization of digital building blocks. Circuit design styles for logic, arithmetic, and sequential blocks. Estimation and minimization of energy consumption. Interconnect models and parasitics, device sizing and logical effort, timing issues (clock skew and jitter), and active clock distribution techniques. Memory architectures, circuits (sense amplifiers), and devices. Evaluation of how design choices affect tradeoffs across key metrics including energy consumption, speed, robustness, and cost. Extensive use of modern design flow and EDA/CAD tools for the analysis and design of digital building blocks and digital VLSI design for labs and design projects","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"34-302"}]},{"type":"Lab","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"32-144"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.6010","terms":["fall"],"rating":5.89,"hours":19.05,"inClassHours":3.58,"outOfClassHours":15.47,"prerequisites":"6.1910, (6.2080/6.2500)","corequisites":"","recommendedPreparation":""},{"code":"6.6020","title":"High-Frequency Integrated Circuits","level":"G","description":"Principles and techniques of high-speed integrated circuits used in wireless/wireline data links and remote sensing. On-chip passive component design of inductors, capacitors, and antennas. Analysis of distributed effects, such as transmission line modeling, S-parameters, and Smith chart. Transceiver architectures and circuit blocks, which include low-noise amplifiers, mixers, voltage-controlled oscillators, power amplifiers, and frequency dividers. Involves IC/EM simulation and laboratory projects.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"3-333"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.6020","terms":["fall"],"rating":5.21,"hours":10.72,"inClassHours":3.11,"outOfClassHours":7.61,"prerequisites":"6.2080","corequisites":"","recommendedPreparation":""},{"code":"6.6210","title":"Electromagnetic Fields, Forces and Motion","level":"G","description":"Study of electromagnetics and electromagnetic energy conversion leading to an understanding of devices, including electromagnetic sensors, actuators, motors and generators. Quasistatic Maxwell's equations and the Lorentz force law. Studies of the quasistatic fields and their sources through solutions of Poisson's and Laplace's equations. Boundary conditions and multi-region boundary-value problems. Steady-state conduction, polarization, and magnetization. Charge conservation and relaxation, and magnetic induction and diffusion. Extension to moving materials. Electric and magnetic forces and force densities derived from energy, and stress tensors. Extensive use of engineering examples. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"32-124"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"2-136"},{"days":["F"],"start":"11:00","end":"12:00","room":"2-136"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.6210","terms":["fall"],"rating":6.5,"hours":12.43,"inClassHours":4.41,"outOfClassHours":8.02,"prerequisites":"GIR:PHY2, 18.03","corequisites":"","recommendedPreparation":""},{"code":"6.6300","title":"Electromagnetics","level":"G","description":"Explores electromagnetic phenomena in modern applications, including wireless and optical communications, circuits, computer interconnects and peripherals, microwave communications and radar, antennas, sensors, micro-electromechanical systems, and power generation and transmission. Fundamentals include quasistatic and dynamic solutions to Maxwell's equations; waves, radiation, and diffraction; coupling to media and structures; guided and unguided waves; modal expansions; resonance; acoustic analogs; and forces, power, and energy.","groups":[{"type":"Lecture","options":[{"days":["W","F"],"start":"13:00","end":"14:30","room":"32-144"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.6300","terms":["fall"],"rating":6.11,"hours":14.68,"inClassHours":4.04,"outOfClassHours":10.64,"prerequisites":"GIR:PHY2, 6.3000","corequisites":"","recommendedPreparation":""},{"code":"6.6310","title":"Optics and Photonics","level":"G","description":"Introduction to fundamental concepts and techniques of optics, photonics, and fiber optics, aimed at developing skills for independent research. Topics include: Review of Maxwell's equations, light propagation, reflection and transmission, dielectric mirrors and filters. Scattering matrices, interferometers, and interferometric measurement. Fresnel and Fraunhoffer diffraction theory. Lenses, optical imaging systems, and software design tools. Gaussian beams, propagation and resonator design. Optical waveguides, optical fibers and photonic devices for encoding and detection. Discussion of research operations / funding and professional development topics. The course reviews and introduces mathematical methods and techniques, which are fundamental in optics and photonics, but also useful in many other engineering specialties.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"16:30","room":"36-372"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.6310","terms":["fall"],"rating":5.66,"hours":22.16,"inClassHours":3.38,"outOfClassHours":18.78,"prerequisites":"6.2300/8.03","corequisites":"","recommendedPreparation":""},{"code":"6.6400","title":"Applied Quantum and Statistical Physics","level":"G","description":"Elementary quantum mechanics and statistical physics. Introduces applied quantum physics. Emphasizes experimental basis for quantum mechanics. Applies Schrodinger's equation to the free particle, tunneling, the harmonic oscillator, and hydrogen atom. Variational methods. Elementary statistical physics; Fermi-Dirac, Bose-Einstein, and Boltzmann distribution functions. Simple models for metals, semiconductors, and devices such as electron microscopes, scanning tunneling microscope, thermonic emitters, atomic force microscope, and more. Some familiarity with continuous time Fourier transforms recommended.","groups":[{"type":"Lecture","options":[{"days":["W","F"],"start":"11:00","end":"12:30","room":"4-153"}]},{"type":"Recitation","options":[{"days":["M"],"start":"11:00","end":"12:00","room":"4-159"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.6400","terms":["fall"],"rating":5.97,"hours":19.44,"inClassHours":5.55,"outOfClassHours":13.89,"prerequisites":"18.06","corequisites":"","recommendedPreparation":"Some familiarity with continuous time Fourier transforms recommended."},{"code":"6.6410","title":"Quantum Computation","level":"G","description":"Provides an introduction to the theory and practice of quantum computation. Topics covered: physics of information processing; quantum algorithms including the factoring algorithm and Grover's search algorithm; quantum error correction; quantum communication and cryptography. Knowledge of quantum mechanics helpful but not required.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"54-100"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.6410","terms":["fall"],"rating":5.23,"hours":8.24,"inClassHours":2.71,"outOfClassHours":5.53,"prerequisites":"8.05/18.06/18.700/18.701/18.C06","corequisites":"","recommendedPreparation":"Knowledge of quantum mechanics helpful but not required."},{"code":"6.6500","title":"Integrated Microelectronic Devices","level":"G","description":"Covers physics of microelectronic semiconductor devices for integrated circuit applications. Topics include semiconductor fundamentals, p-n junction, metal-oxide semiconductor structure, metal-semiconductor junction, MOS field-effect transistor, and bipolar junction transistor.  Emphasizes physical understanding of device operation through energy band diagrams and short-channel MOSFET device design and modern device scaling. Familiarity with MATLAB recommended.","groups":[{"type":"Lecture","options":[{"days":["M","T","W","R"],"start":"10:00","end":"11:00","room":"36-153"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.6500","terms":["fall"],"rating":6.64,"hours":13.96,"inClassHours":4.2,"outOfClassHours":9.76,"prerequisites":"3.42/6.2500","corequisites":"","recommendedPreparation":"Familiarity with MATLAB recommended."},{"code":"6.6630","title":"Control of Manufacturing Processes","level":"G","description":"Statistical modeling and control in manufacturing processes. Use of experimental design and response surface modeling to understand manufacturing process physics. Defect and parametric yield modeling and optimization. Forms of process control, including statistical process control, run by run and adaptive control, and real-time feedback control. Application contexts include semiconductor manufacturing, conventional metal and polymer processing, and emerging micro-nano manufacturing processes.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"9-354"}]}],"url":"http://student.mit.edu/catalog/m6b.html#6.6630","terms":["fall"],"rating":5.51,"hours":13.17,"inClassHours":3.49,"outOfClassHours":9.68,"prerequisites":"2.008/6.2600/6.3700","corequisites":"","recommendedPreparation":""},{"code":"6.7210","title":"Introduction to Mathematical Programming","level":"G","description":"Introduction to linear optimization and its extensions emphasizing both methodology and the underlying mathematical structures and geometrical ideas. Covers classical theory of linear programming as well as some recent advances in the field. Topics: simplex method; duality theory; sensitivity analysis; network flow problems; decomposition; robust optimization; integer programming; interior point algorithms for linear programming; and introduction to combinatorial optimization and NP-completeness.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"32-141"}]},{"type":"Recitation","options":[{"days":["F"],"start":"12:00","end":"13:00","room":"2-105"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.7210","terms":["fall"],"rating":6.33,"hours":13.02,"inClassHours":3.79,"outOfClassHours":9.23,"prerequisites":"18.06","corequisites":"","recommendedPreparation":""},{"code":"6.7300","title":"Introduction to Modeling and Simulation","level":"G","description":"Introduction to computational techniques for modeling and simulation of a variety of large and complex engineering, science, and socio-economical systems. Prepares students for practical use and development of computational engineering in their own research and future work. Topics include mathematical formulations (e.g., automatic assembly of constitutive and conservation principles); linear system solvers (sparse and iterative); nonlinear solvers (Newton and homotopy); ordinary, time-periodic and partial differential equation solvers; and model order reduction. Students develop their own models and simulators for self-proposed applications, with an emphasis on creativity, teamwork, and communication. Prior basic linear algebra required and at least one numerical programming language (e.g., MATLAB, Julia, Python, etc.) helpful.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.7300","terms":["fall"],"rating":5.69,"hours":14.44,"inClassHours":3.23,"outOfClassHours":11.21,"prerequisites":"18.03/18.06","corequisites":"","recommendedPreparation":"Prior basic linear algebra required and at least one numerical programming language (e.g., MATLAB, Julia, Python, etc.) helpful."},{"code":"6.7310","title":"Introduction to Numerical Methods","level":"G","description":"Advanced introduction to numerical analysis: accuracy and efficiency of numerical algorithms. In-depth coverage of sparse-matrix/iterative and dense-matrix algorithms in numerical linear algebra (for linear systems and eigenproblems). Floating-point arithmetic, backwards error analysis, conditioning, and stability. Other computational topics (e.g., numerical integration or nonlinear optimization) may also be surveyed. Final project involves some programming.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.7310","terms":["fall"],"rating":6.28,"hours":8.78,"inClassHours":2.78,"outOfClassHours":6.0,"prerequisites":"18.06/18.700/18.701","corequisites":"","recommendedPreparation":""},{"code":"6.7330","title":"Numerical Methods for Partial Differential Equations","level":"G","description":"Covers the fundamentals of modern numerical techniques for a wide range of linear and nonlinear elliptic, parabolic, and hyperbolic partial differential and integral equations. Topics include mathematical formulations; finite difference, finite volume, finite element, and boundary element discretization methods; and direct and iterative solution techniques. The methodologies described form the foundation for computational approaches to engineering systems involving heat transfer, solid mechanics, fluid dynamics, and electromagnetics. Computer assignments requiring programming.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"37-212"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.7330","terms":["fall"],"rating":6.17,"hours":16.35,"inClassHours":4.11,"outOfClassHours":12.24,"prerequisites":"18.03/18.06","corequisites":"","recommendedPreparation":""},{"code":"6.7410","title":"Principles of Digital Communication","level":"G","description":"Covers communications by progressing through signal representation, sampling, quantization, compression, modulation, coding and decoding, medium access control, and queueing and principles of protocols. By providing simplified proofs, seeks to present an integrated, systems-level view of networking and communications while laying the foundations of analysis and design. Lectures are offered online; in-class time is dedicated to recitations, exercises, and weekly group labs. Homework exercises are based on theoretical derivation and software implementation. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"56-154"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.7410","terms":["fall"],"rating":5.77,"hours":10.82,"inClassHours":3.23,"outOfClassHours":7.59,"prerequisites":"(6.3000/6.3102), (6.3700/6.3800/18.05)","corequisites":"","recommendedPreparation":""},{"code":"6.7411","title":"Principles of Digital Communication","level":"U","description":"Covers communications by progressing through signal representation, sampling, quantization, compression, modulation, coding and decoding, medium access control, and queueing and principles of protocols. By providing simplified proofs, seeks to present an integrated, systems-level view of networking and communications while laying the foundations of analysis and design. Lectures are offered online; in-class time is dedicated to recitations, exercises, and weekly group labs. Homework exercises are based on theoretical derivation and software implementation. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"56-154"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.7411","terms":["fall"],"rating":5.8,"hours":11.53,"inClassHours":3.2,"outOfClassHours":8.33,"prerequisites":"(6.3000/6.3100/6.3400), (6.3700/6.3800/18.05)","corequisites":"","recommendedPreparation":""},{"code":"6.7700","title":"Fundamentals of Probability","level":"G","description":"Introduction to probability theory. Probability spaces and measures. Discrete and continuous random variables. Conditioning and independence. Multivariate normal distribution. Abstract integration, expectation, and related convergence results. Moment generating and characteristic functions. Bernoulli and Poisson process. Finite-state Markov chains. Convergence notions and their relations. Limit theorems. Familiarity with elementary probability and real analysis is desirable.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"45-230"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"3-333"},{"days":["F"],"start":"14:00","end":"15:00","room":"3-333"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.7700","terms":["fall"],"rating":6.07,"hours":13.62,"inClassHours":3.39,"outOfClassHours":10.23,"prerequisites":"GIR:CAL2","corequisites":"","recommendedPreparation":"Familiarity with elementary probability and real analysis is desirable."},{"code":"6.7730","title":"Modern Mathematical Statistics","level":"G","description":"Presents mathematical statistics as a formal language for reasoning about data and uncertainty. Introduction to the basic framework of statistical decision theory, along with core concepts such as sufficiency, Bayes and minimax optimality of statistical procedures, with applications to optimal estimation, hypothesis testing, and prediction. Discussion topics include causality, multiple hypothesis testing, nonparametric and semiparametric statistics, and results for model misspecification. Targeted to students interested in statistical and machine learning research, with an emphasis on proofs and fundamental understanding.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:30","end":"11:00","room":"45-102"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.7730","terms":["fall"],"rating":6.6,"hours":12.9,"inClassHours":2.9,"outOfClassHours":10.0,"prerequisites":"18.100A, 18.C06, (6.3700/18.600), (6.3720/18.650)","corequisites":"","recommendedPreparation":""},{"code":"6.7810","title":"Algorithms for Inference","level":"G","description":"Introduction to computational aspects of statistical inference via probabilistic graphical models. Directed and undirected graphical models, and factor graphs, over discrete and Gaussian distributions; hidden Markov models, linear dynamical systems. Sum-product and junction tree algorithms; forward-backward algorithm, Kalman filtering and smoothing. Min-sum and Viterbi algorithms. Variational methods, mean-field theory, and loopy belief propagation. Sampling methods; Glauber dynamics and mixing time analysis. Parameter structure learning for graphical models; Baum-Welch and Chow-Liu algorithms. Selected topics such as causal inference, particle filtering, restricted Boltzmann machines, and graph neural networks.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"32-123"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.7810","terms":["fall"],"rating":5.82,"hours":13.91,"inClassHours":3.2,"outOfClassHours":10.71,"prerequisites":"18.06, (6.3700/6.3800/6.7700)","corequisites":"","recommendedPreparation":""},{"code":"6.7900","title":"Machine Learning","level":"G","description":"Principles, techniques, and algorithms in machine learning from the point of view of statistical inference; representation, generalization, and model selection; and methods such as linear/additive models, active learning, boosting, support vector machines, non-parametric Bayesian methods, hidden Markov models, Bayesian networks, and convolutional and recurrent neural networks. Recommended prerequisite: 6.3900 or other previous experience in machine learning. Enrollment may be limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"32-123"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.7900","terms":["fall"],"rating":5.25,"hours":12.44,"inClassHours":3.41,"outOfClassHours":9.03,"prerequisites":"18.06, (6.3700/6.3800/18.600)","corequisites":"","recommendedPreparation":"Recommended prerequisite: 6.3900 or other previous experience in machine learning."},{"code":"6.7910","title":"Statistical Learning Theory and Applications","level":"G","description":"Covers foundations and recent advances in statistical machine learning theory, with the dual goals of providing students with the theoretical knowledge to use machine learning and preparing more advanced students to contribute to progress in the field. The content is roughly divided into three parts. The first part is about classical regularization, margin, stochastic gradient methods, overparametrization, implicit regularization, and stability. The second part is about deep networks: approximation and optimization theory plus roots of generalization. The third part is about the connections between learning theory and the brain. Occasional talks by leading researchers on advanced research topics. Emphasis on current research topics.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"46-3002"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.7910","terms":["fall"],"rating":5.66,"hours":9.97,"inClassHours":3.18,"outOfClassHours":6.79,"prerequisites":"6.3700/6.7900/18.06/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.7920","title":"Reinforcement Learning: Foundations and Methods","level":"G","description":"Examines reinforcement learning (RL) as a methodology for approximately solving sequential decision-making under uncertainty, with foundations in optimal control and machine learning. Provides a mathematical introduction to RL, including dynamic programming, statistical, and empirical perspectives, and special topics. Core topics include: dynamic programming, special structures, finite and infinite horizon Markov Decision Processes, value and policy iteration, Monte Carlo methods, temporal differences, Q-learning, stochastic approximation, and bandits. Also covers approximate dynamic programming, including value-based methods and policy space methods. Applications and examples drawn from diverse domains. Focus is mathematical, but is supplemented with computational exercises. An analysis prerequisite is suggested but not required; mathematical maturity is necessary.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"34-101"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"26-210"},{"days":["F"],"start":"11:00","end":"12:00","room":"26-142"},{"days":["F"],"start":"13:00","end":"14:00","room":"26-314"},{"days":["F"],"start":"14:00","end":"15:00","room":"26-314"},{"days":["F"],"start":"15:00","end":"16:00","room":"26-314"},{"days":["F"],"start":"16:00","end":"17:00","room":"56-154"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.7920","terms":["fall"],"rating":5.29,"hours":15.15,"inClassHours":3.56,"outOfClassHours":11.59,"prerequisites":"6.3700/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.7960","title":"Deep Learning","level":"G","description":"Fundamentals of deep learning, including both theory and applications. Topics include neural net architectures (MLPs, CNNs, RNNs, graph nets, transformers), geometry and invariances in deep learning, backpropagation and automatic differentiation, learning theory and generalization in high-dimensions, and applications to computer vision, natural language processing, and robotics.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"45-230"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.7960","terms":["fall"],"rating":5.93,"hours":10.77,"inClassHours":2.7,"outOfClassHours":8.07,"prerequisites":"18.05, (6.3720/6.3900/6.C01)","corequisites":"","recommendedPreparation":""},{"code":"6.7980","title":"Topics in Multiagent Learning","level":"G","description":"Examines the foundations of multi-agent systems from a combined game-theoretic, optimization, and learning-theoretic perspective. Studies settings involving multiple learning agents with distinct objectives, where standard training methods may induce nonstationary or unstable behaviors. Introduces fundamental models including matrix games, stochastic games, and imperfect-information games. Studies modern settings deviating from standard models wherein strategies and utilities are represented using deep neural networks. Presents equilibrium concepts, equilibrium computation methods, and equilibrium learning methods. Studies the complexity of solution concepts. Discusses applications in machine learning, including multi-agent reinforcement learning, adversarial learning, AI-AI interactions, and strategic decision-making systems underlying game-playing agents in domains such as Go, poker, Diplomacy, and Stratego.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"E25-111"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.7980","terms":["fall"],"rating":null,"hours":null,"inClassHours":null,"outOfClassHours":null,"prerequisites":"6.1200/6.1220/15.C571","corequisites":"","recommendedPreparation":""},{"code":"6.809","title":"Interactive Music Systems","level":"U","description":"Explores audio synthesis, musical structure, human computer interaction (HCI), and visual presentation for the creation of interactive musical experiences. Topics include audio synthesis; mixing and looping; MIDI sequencing; generative composition; motion sensors; music games; and graphics for UI, visualization, and aesthetics. Includes weekly programming assignments in python. Teams build an original, dynamic, and engaging interactive music system for their final project. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"VIRTUAL"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.809","terms":["fall","spring"],"rating":6.85,"hours":11.03,"inClassHours":3.04,"outOfClassHours":7.99,"prerequisites":"(6.009, 21M.301)/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.8370","title":"Advanced Computational Photography","level":"G","description":"Presents fundamentals and applications of hardware and software techniques used in digital and computational photography, with an emphasis on software methods. Provides sufficient background to implement solutions to photographic challenges and opportunities. Topics include cameras and image formation, image processing and image representations, high-dynamic-range imaging, human visual perception and color, single view 3-D model reconstruction, morphing, data-rich photography, super-resolution, and image-based rendering. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"45-230"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.8370","terms":["fall"],"rating":6.71,"hours":9.65,"inClassHours":2.69,"outOfClassHours":6.96,"prerequisites":"GIR:CAL2, 6.1010","corequisites":"","recommendedPreparation":""},{"code":"6.8371","title":"Digital and Computational Photography","level":"U","description":"Presents fundamentals and applications of hardware and software techniques used in digital and computational photography, with an emphasis on software methods. Provides sufficient background to implement solutions to photographic challenges and opportunities. Topics include cameras and image formation, image processing and image representations, high-dynamic-range imaging, human visual perception and color, single view 3-D model reconstruction, morphing, data-rich photography, super-resolution, and image-based rendering. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"45-230"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.8371","terms":["fall"],"rating":6.71,"hours":9.65,"inClassHours":2.69,"outOfClassHours":6.96,"prerequisites":"GIR:CAL2, 6.1010","corequisites":"","recommendedPreparation":""},{"code":"6.8410","title":"Shape Analysis","level":"G","description":"Introduces mathematical, algorithmic, and statistical tools needed to analyze geometric data and to apply geometric techniques to data analysis, with applications to fields such as computer graphics, machine learning, computer vision, medical imaging, and architecture. Potential topics include applied introduction to differential geometry, discrete notions of curvature, metric embedding, geometric PDE via the finite element method (FEM) and discrete exterior calculus (DEC),; computational spectral geometry and relationship to graph-based learning, correspondence and mapping, level set method, descriptor, shape collections, optimal transport, and vector field design.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"32-124"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.8410","terms":["fall"],"rating":5.94,"hours":14.15,"inClassHours":2.92,"outOfClassHours":11.23,"prerequisites":"GIR:CAL2, 18.06, (6.8300/6.4400)","corequisites":"","recommendedPreparation":""},{"code":"6.8420","title":"Computational Design and Fabrication","level":"G","description":"Introduces computational aspects of computer-aided design and manufacturing. Explores relevant methods in the context of additive manufacturing (e.g., 3D printing). Topics include computer graphics (geometry modeling, solid modeling, procedural modeling), physically-based simulation (kinematics, finite element method), 3D scanning/geometry processing, and an overview of 3D fabrication methods. Exposes students to the latest research in computational fabrication. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"32-141"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.8420","terms":["fall"],"rating":4.52,"hours":13.01,"inClassHours":3.47,"outOfClassHours":9.54,"prerequisites":"GIR:CAL2, (6.1010/''permission of instructor'')","corequisites":"","recommendedPreparation":""},{"code":"6.8720","title":"Principles of Synthetic Biology","level":"G","description":"Introduces the basics of synthetic biology, including quantitative cellular network characterization and modeling. Considers the discovery and genetic factoring of useful cellular activities into reusable functions for design. Emphasizes the principles of biomolecular system design and diagnosis of designed systems. Illustrates cutting-edge applications in synthetic biology and enhances skills in analysis and design of synthetic biological applications. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"26-328"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.8720","terms":["fall"],"rating":5.85,"hours":8.53,"inClassHours":3.53,"outOfClassHours":5.0,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"6.8721","title":"Principles of Synthetic Biology","level":"U","description":"Introduces the basics of synthetic biology, including quantitative cellular network characterization and modeling. Considers the discovery and genetic factoring of useful cellular activities into reusable functions for design. Emphasizes the principles of biomolecular system design and diagnosis of designed systems. Illustrates cutting-edge applications in synthetic biology and enhances skills in analysis and design of synthetic biological applications. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"26-328"}]}],"url":"http://student.mit.edu/catalog/m6d.html#6.8721","terms":["fall"],"rating":5.85,"hours":8.53,"inClassHours":3.53,"outOfClassHours":5.0,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"6.902","title":"Design Thinking and Innovation Leadership for Engineers","level":"U","description":"Project-based course develops students' ability to conceive, implement, and evaluate successful projects in any engineering discipline. Lessons focus on an iterative design process, techniques for leading the creative process in teams, the ethics of engineering systems, methods for articulating designs with group collaboration, identifying and reconciling paradoxes of engineering designs, using a systems thinking approach for stakeholder analysis, and communicating solution concepts with impact. Working in teams, students employ design thinking techniques and leadership skills to collaboratively conceive, implement, and iteratively refine through user feedback robust applications using a simple web-based platform. Students also give oral presentations and receive feedback to sharpen their communication skills.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"21:00","room":"VIRTUAL"}]},{"type":"Design","options":[{"days":["M"],"start":"21:00","end":"22:00","room":"VIRTUAL"}]}],"url":"http://student.mit.edu/catalog/m6c.html#6.902","terms":["fall","spring"],"rating":5.07,"hours":6.94,"inClassHours":2.95,"outOfClassHours":3.99,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"6.9020","title":"How to Make (Almost) Anything","level":"G","description":"Provides a practical hands-on introduction to digital fabrication, including CAD/CAM/CAE, NC machining, 3-D printing and scanning, molding and casting, composites, laser and waterjet cutting, PCB design and fabrication; sensors and actuators; mixed-signal instrumentation, embedded processing, and wired and wireless communications. Develops an understanding of these capabilities through projects using them individually and jointly to create functional systems.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"16:00","room":"E14-633"}]},{"type":"Recitation","options":[{"days":["R"],"start":"17:00","end":"19:00","room":"E14-633"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.9020","terms":["fall"],"rating":6.52,"hours":22.19,"inClassHours":4.96,"outOfClassHours":17.23,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.9101","title":"Introduction to Design Thinking and Innovation in Engineering","level":"U","description":"Introduces students to concepts of design thinking and innovation that can be applied to any engineering discipline. Focuses on introducing an iterative design process, a systems-thinking approach for stakeholder analysis, methods for articulating design concepts, methods for concept selection, and techniques for testing with users. Provides an opportunity for first-year students to explore product or system design and development, and to build their understanding of what it means to lead and coordinate projects in engineering design. Subject can count toward the 6-unit discovery-focused credit limit for first-year students. Enrollment limited to 25; priority to first-year students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"21:00","room":"32-141"}]},{"type":"Recitation","options":[{"days":["M"],"start":"21:00","end":"22:00","room":"32-123"},{"days":["W"],"start":"12:00","end":"13:00","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.9101","terms":["fall"],"rating":5.81,"hours":5.1,"inClassHours":3.0,"outOfClassHours":2.1,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"6.910A","title":"Design Thinking and Innovation Leadership for Engineers","level":"U","description":"Introductory subject in design thinking and innovation. Develops students' ability to conceive, implement, and evaluate successful projects in any engineering discipline. Lessons focus on an iterative design process, a systems-thinking approach for stakeholder analysis, methods for articulating design concepts, methods for concept selection, and techniques for testing with users.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"21:00","room":"32-141"},{"days":["M"],"start":"15:00","end":"17:00","room":"32-141"}]},{"type":"Recitation","options":[{"days":["M"],"start":"21:00","end":"22:00","room":"32-123"},{"days":["W"],"start":"12:00","end":"13:00","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.910A","terms":["fall"],"rating":5.04,"hours":5.23,"inClassHours":2.98,"outOfClassHours":2.25,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"6.910B","title":"Design Thinking and Innovation Project","level":"U","description":"Project-based subject. Students employ design-thinking techniques learned in 6.902A to develop a robust speech-recognition application using a web-based platform. Students practice in leadership and teamwork skills as they collaboratively conceive, implement, and iteratively refine their designs based on user feedback. Topics covered include techniques for leading the creative process in teams, the ethics of engineering systems, methods for articulating designs with group collaboration, identifying and reconciling paradoxes of engineering designs, and communicating solution concepts with impact. Students present oral presentations and receive feedback to sharpen their communication skills.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"21:00","room":"32-141"},{"days":["M"],"start":"15:00","end":"17:00","room":"32-141"}]},{"type":"Recitation","options":[{"days":["M"],"start":"21:00","end":"22:00","room":"32-123"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.910B","terms":["fall"],"rating":4.67,"hours":6.65,"inClassHours":2.91,"outOfClassHours":3.74,"prerequisites":"6.910A","corequisites":"","recommendedPreparation":""},{"code":"6.9110","title":"Engineering Leadership Lab","level":"U","description":"Advances students' leadership, teamwork, and communication skills through further exposure to leadership frameworks, models, and cases within an engineering context in an interactive, practice-based environment. Students coach others, assess performance, and lead guided reflections on individual and team successes, while discovering opportunities for improvement. Students assist with programmatic planning and implementation of role-play simulations, small group discussions, and performance and peer assessments by and of other students and by instructors. Includes frequent engineering industry-guest participation and involvement. Content is frequently student-led. Second year Gordon Engineering Leadership Program (GEL) Program students register for 6.9130. Preference to students enrolled in the second year of the Gordon-MIT Engineering Leadership Program.","groups":[{"type":"Lab","options":[{"days":["F"],"start":"09:00","end":"11:00","room":"32-124"},{"days":["F"],"start":"13:00","end":"15:00","room":"32-124"},{"days":["F"],"start":"15:00","end":"17:00","room":"32-124"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.9110","terms":["fall","spring"],"rating":6.18,"hours":3.45,"inClassHours":2.2,"outOfClassHours":1.25,"prerequisites":"","corequisites":"6.9120/''permission of instructor''","recommendedPreparation":""},{"code":"6.9120","title":"Engineering Leadership","level":"U","description":"Exposes students to the models and methods of engineering leadership within the contexts of conceiving, designing, implementing and operating products, processes and systems. Introduces the Capabilities of Effective Engineering Leaders, and models and theories related to the capabilities. Discusses the appropriate times and reasons to use particular models to deliver engineering success. Includes occasional guest speakers or panel discussions. May be repeated for credit once with permission of instructor. Preference to first-year students in the Gordon Engineering Leadership Program.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"11:00","end":"12:30","room":"4-153"},{"days":["M"],"start":"13:00","end":"14:30","room":"4-153"},{"days":["T"],"start":"11:00","end":"12:30","room":"4-153"},{"days":["T"],"start":"13:00","end":"14:30","room":"4-153"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.9120","terms":["fall","spring"],"rating":6.02,"hours":3.66,"inClassHours":2.04,"outOfClassHours":1.62,"prerequisites":"","corequisites":"6.9110/''permission of instructor''","recommendedPreparation":""},{"code":"6.9130","title":"Engineering Leadership Lab","level":"U","description":"Advances students' leadership, teamwork, and communication skills through further exposure to leadership frameworks, models, and cases within an engineering context in an interactive, practice-based environment. Students coach others, assess performance, and lead guided reflections on individual and team successes, while discovering opportunities for improvement. Students assist with programmatic planning and implementation of role-play simulations, small group discussions, and performance and peer assessments by and of other students and by instructors. Includes frequent engineering industry-guest participation and involvement. Content is frequently student-led. Second year Gordon Engineering Leadership Program (GEL) Program students register for 6.9130. Preference to students enrolled in the second year of the Gordon-MIT Engineering Leadership Program.","groups":[{"type":"Lab","options":[{"days":["F"],"start":"09:00","end":"11:00","room":"32-124"},{"days":["F"],"start":"13:00","end":"15:00","room":"32-124"},{"days":["F"],"start":"15:00","end":"17:00","room":"32-124"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.9130","terms":["fall","spring"],"rating":6.18,"hours":3.45,"inClassHours":2.2,"outOfClassHours":1.25,"prerequisites":"6.910A/6.9110/6.9120/''permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.9270","title":"Negotiation and Influence Skills for Technical Leaders","level":"G","description":"Focuses around the premise that the abilities to negotiate with, and influence others, are essential to being an effective leader in technology rich environments. Provides graduate students with underlying principles and a repertoire of negotiation and influence skills that apply to interpersonal situations, particularly those where an engineer or project leader lacks formal authority over others in delivering results. Utilizes research-based approaches through the application of multiple learning methods, including experiential role plays, case studies, assessments, feedback, and personal reflections. Concepts such as the zone of possible agreements, best alternative to negotiated agreements, and sources of influence are put into practice. Satisfies the requirements for the Graduate Certificate in Technical Leadership.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"16:00","end":"18:00","room":"56-114"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.9270","terms":["fall"],"rating":6.7,"hours":5.67,"inClassHours":2.84,"outOfClassHours":2.83,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"6.9280","title":"Leading Creative Teams","level":"G","description":"Prepares students to lead teams charged with developing creative solutions in engineering and technical environments. Grounded in research but practical in focus, equips students with leadership competencies such as building self-awareness, motivating and developing others, creative problem solving, influencing without authority, managing conflict, and communicating effectively. Teamwork skills include how to convene, launch, and develop various types of teams, including project teams. Learning methods emphasize personalized and experiential skill development. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"9-354"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.9280","terms":["fall","spring"],"rating":6.1,"hours":7.73,"inClassHours":3.11,"outOfClassHours":4.62,"prerequisites":"''Permission of instructor''","corequisites":"","recommendedPreparation":""},{"code":"6.9320","title":"Ethics for Engineers","level":"U","description":"Explores how to be an ethical engineer. Students examine engineering case studies alongside key readings by foundational ethical thinkers from Aristotle to Martin Luther King, Jr., and investigate which ethical approaches are best and how to apply them. Topics include justice, rights, cost-benefit analysis, safety, bias, genetic engineering, climate change, and the promise and peril of AI. Discussion-based, with the aim of introducing students to new ways of thinking. All sections cover the same core ethical frameworks, but some sections have a particular focus for case studies, such as bioengineering, or have an in-depth emphasis on particular thinkers. The subject is taught in separate sections. Students are eligible to take any section regardless of their registered subject number. For 20.005, students additionally undertake an ethical-technical analysis of a BE-related topic of their choosing.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["T"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["W"],"start":"19:00","end":"21:00","room":"66-148"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.9320","terms":["fall","spring"],"rating":6.41,"hours":5.01,"inClassHours":2.06,"outOfClassHours":2.95,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"6.9360","title":"Management in Engineering","level":"U","description":"Introduction and overview of engineering management. Financial principles, management of innovation, technical strategy and best management practices. Case study method of instruction emphasizes participation in class discussion. Focus is on the development of individual skills and management tools. Restricted to juniors and seniors.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"35-225"}]},{"type":"Lab","options":[{"days":["M"],"start":"16:00","end":"17:00","room":"1-150"},{"days":["T"],"start":"10:00","end":"11:00","room":"1-375"},{"days":["R"],"start":"16:00","end":"17:00","room":"1-375"},{"days":["F"],"start":"13:00","end":"14:00","room":"1-135"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.9360","terms":["fall"],"rating":4.75,"hours":8.38,"inClassHours":3.99,"outOfClassHours":4.39,"prerequisites":"","corequisites":"","recommendedPreparation":""},{"code":"6.C06","title":"Linear Algebra and Optimization","level":"U","description":"Introductory course in linear algebra and optimization, assuming no prior exposure to linear algebra and starting from the basics, including vectors, matrices, eigenvalues, singular values, and least squares. Covers the basics in optimization including convex optimization, linear/quadratic programming, gradient descent, and regularization, building on insights from linear algebra. Explores a variety of applications in science and engineering, where the tools developed give powerful ways to understand complex systems and also extract structure from data.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"11:00","end":"12:00","room":"45-230"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"10:00","end":"11:00","room":"45-102"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"45-102"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"45-102"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"45-102"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.C06","terms":["fall"],"rating":5.47,"hours":10.88,"inClassHours":4.59,"outOfClassHours":6.29,"prerequisites":"GIR:CAL2","corequisites":"","recommendedPreparation":""},{"code":"6.C25","title":"Real World Computation with Julia","level":"U","description":"Focuses on algorithms and techniques for writing and using modern technical software in a job, lab, or research group environment that may consist of interdisciplinary teams, where performance may be critical, and where the software needs to be flexible and adaptable. Topics include automatic differentiation, matrix calculus, scientific machine learning, parallel and GPU computing, and performance optimization with introductory applications to climate science, economics, agent-based modeling, and other areas. Labs and projects focus on performant, readable, composable algorithms, and software. Programming will be in Julia. Expects students to have some familiarity with Python, Matlab, or R. No Julia experience necessary.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"45-102"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.C25","terms":["fall"],"rating":6.3,"hours":7.33,"inClassHours":3.1,"outOfClassHours":4.23,"prerequisites":"6.100A, 18.03, 18.06","corequisites":"","recommendedPreparation":"Expects students to have some familiarity with Python, Matlab, or R."},{"code":"6.C27","title":"Computational Imaging: Physics and Algorithms","level":"U","description":"Explores the contemporary computational understanding of imaging: encoding information about a physical object onto a form of radiation, transferring the radiation through an imaging system, converting it to a digital signal, and computationally decoding and presenting the information to the user. Introduces a unified formulation of computational imaging systems as a three-round 'learning spiral': the first two rounds describe the physical and algorithmic parts in two exemplary imaging systems. The third round involves a class project on an imaging system chosen by students. Undergraduate and graduate versions share lectures but have different recitations. Involves optional 'clinics' to even out background knowledge of linear algebra, optimization, and computational imaging-related programming best practices for students of diverse disciplinary backgrounds. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"24-121"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.C27","terms":["fall"],"rating":6.43,"hours":12.4,"inClassHours":3.14,"outOfClassHours":9.26,"prerequisites":"18.C06, (1.00/1.000/2.086/3.019/6.100A)","corequisites":"","recommendedPreparation":"Involves optional 'clinics' to even out background knowledge of linear algebra, optimization, and computational imaging-related programming best practices for students of diverse disciplinary backgrounds."}]);
